var e=JSON.parse(`{"wrist-circles":{"name":"Cercles de poignets","description":"Tenez-vous droit, coudes souples et avant-bras devant vous. Dessinez des cercles lents avec les deux poignets, quatre temps dans un sens et quatre dans l'autre, en gardant les doigts relâchés.","goodFor":"Échauffe les poignets et les avant-bras qui font la plupart du travail avec chaque agrès.","alignmentCues":["Les coudes restent immobiles ; seuls les poignets bougent.","Gardez les cercles grands et fluides."],"commonMistakes":["Aller trop vite dans les cercles, ce qui les transforme en petits coups secs."]},"arm-circles":{"name":"Cercles de bras","description":"Pieds écartés à la largeur des hanches, bras tendus. Balancez les deux bras en grands cercles vers l'avant pendant quatre temps, puis vers l'arrière pendant quatre, en laissant les omoplates glisser.","goodFor":"Ouvre les épaules pour les rotations de staff et le travail du hoop au-dessus de la tête.","alignmentCues":["Les côtes restent basses quand les bras passent au-dessus de la tête.","Expirez sur le mouvement descendant."]},"shoulder-rolls":{"name":"Rotations d'épaules","description":"Bras relâchés le long du corps. Montez les épaules vers les oreilles, roulez-les vers l'arrière et vers le bas, et répétez en boucle lente.","goodFor":"Libère les tensions qui rendent les lancers raides et courts."},"neck-rolls":{"name":"Demi-cercles de nuque","description":"Baissez le menton vers la poitrine et balayez-le lentement d'une épaule à l'autre en demi-cercle. Évitez de basculer la tête en arrière.","goodFor":"Détend la nuque avant de regarder les lancers vers le haut pendant de longues périodes.","avoidIf":["Blessure à la nuque ou vertiges lors des mouvements de tête."]},"hip-circles":{"name":"Cercles de hanches","description":"Mains sur les hanches, genoux souples. Faites des cercles lents avec les hanches dans un sens pendant deux mesures et dans l'autre pendant deux, en gardant la tête droite.","goodFor":"Prépare les hanches pour le hoop à la taille et le corps pour le flow."},"torso-twists":{"name":"Torsions du buste","description":"Pieds écartés, bras relâchés. Tournez les côtes à gauche et à droite et laissez les bras se balancer et s'enrouler autour de vous comme des manches vides.","goodFor":"Réveille la rotation pour les weaves au staff et les passes au hoop."},"knee-bounce":{"name":"Rebonds de genoux","description":"Tenez-vous debout, pieds sous les hanches, et rebondissez doucement sur les genoux à chaque temps, bras balancés librement. Trouvez la musique dans vos jambes.","goodFor":"Met le rythme dans votre corps avant de prendre un agrès."},"one-ball-toss":{"name":"Lancer d'une balle","description":"Tenez une balle dans la main droite à hauteur de taille. Ramenez-la vers l'intérieur, puis lancez-la en arc qui culmine juste au-dessus du niveau des yeux et retombe dans la main gauche. Renvoyez-la de la même façon. Gardez les yeux sur le sommet de l'arc, pas sur vos mains.","goodFor":"Construit l'arc sur lequel repose chaque figure de jonglage.","alignmentCues":["Coudes le long du corps, avant-bras à l'horizontale.","Le sommet est à la même hauteur à chaque lancer.","Attrapez à hauteur de taille et laissez la main amortir un peu."],"commonMistakes":["Lancer vers l'avant, ce qui vous oblige à avancer après la balle.","Regarder les mains au lieu du sommet."]},"two-ball-exchange":{"name":"Échange à deux balles","description":"Une balle dans chaque main. Lancez la balle droite dans son arc ; quand elle culmine, lancez la balle gauche en dessous, à l'intérieur. Attrapez les deux et marquez une pause. Puis commencez avec la main gauche.","goodFor":"Enseigne l'échange : le deuxième lancer part quand le premier culmine.","alignmentCues":["Deuxième lancer au sommet, jamais en avance.","Lancez la deuxième balle à l'intérieur de la première."],"commonMistakes":["Passer la deuxième balle d'une main à l'autre au lieu de la lancer.","Lancer les deux en même temps."]},"cascade":{"name":"Cascade à trois balles","description":"Deux balles dans la main droite, une dans la gauche. Lance depuis la droite ; au sommet, lance depuis la gauche ; au sommet, relance depuis la droite. Chaque lancer tombe sur le temps, en croisant vers l'autre main dans un arc en 8.","goodFor":"Le motif fondamental de la jonglerie.","modifications":["Travaille le flash : trois lancers, trois rattrapés, stop."],"deepen":["Jongle sur un tempo plus rapide avec des sommets plus bas.","Compte 20 rattrapés sans faire tomber."],"alignmentCues":["Lance depuis l'intérieur, rattrape à l'extérieur.","Sommets au niveau des yeux.","Tiens-toi contre un mur si tu avances sans cesse."],"commonMistakes":["Lancer vers l'avant et courir après le motif.","Se précipiter dès qu'un lancer rate."]},"reverse-cascade":{"name":"Cascade inversée","description":"La cascade à l'envers : chaque balle est lancée depuis l'extérieur, par-dessus le motif, et retombe au centre dans l'autre main.","goodFor":"Entraîne les lancers depuis l'extérieur et ouvre la voie à des figures comme le Mills Mess.","alignmentCues":["Les lancers passent au-dessus de la balle qui arrive.","Rattrape au centre."]},"siteswap-423":{"name":"423","description":"Un motif à trois balles : un lancer haut de la même main (4), une balle tenue (2), puis un lancer de cascade (3). Le 4 monte du même côté ; le 2 est simplement tenu pendant un temps.","goodFor":"Ta première figure en siteswap : apprend les lancers hauts et les tenues."},"siteswap-441":{"name":"441","description":"Deux lancers hauts qui restent de leur côté (4, 4) suivis d'un zip rapide d'une main à l'autre (1).","goodFor":"Développe le timing entre lancers hauts et passes rapides."},"two-in-one":{"name":"Deux dans une main","description":"Jongle deux balles dans une main en colonnes côte à côte ou en petits cercles vers l'extérieur, un lancer tous les deux temps. Travaille chaque main.","goodFor":"La brique de base de la jonglerie à quatre balles."},"siteswap-531":{"name":"531","description":"Un lancer croisé très haut (5), un lancer de cascade (3) et un zip rapide (1). Le 5 monte pendant que les deux autres balles continuent de travailler en dessous.","goodFor":"Contrôle de la hauteur et figure à trois balles qui impressionne."},"shower":{"name":"Douche à trois balles","description":"Les balles voyagent en cercle : la main droite lance chaque balle haut vers la gauche, et la main gauche renvoie chacune directement vers la droite.","goodFor":"Motif circulaire classique ; entraîne les passes rapides d'une main à l'autre."},"mills-mess":{"name":"Mills Mess","description":"Une cascade à trois balles où les bras ne cessent de se croiser et se décroiser, chaque lancer partant du côté opposé du corps. Les trajectoires des balles dessinent un motif tissé.","goodFor":"Un classique qui impressionne le public et affine la coordination."},"four-ball-fountain":{"name":"Fontaine à quatre balles","description":"Chaque main jongle deux balles dans sa propre colonne, les mains alternant les lancers pour que le motif ne croise jamais.","goodFor":"Ton premier motif à quatre balles."},"sync-fountain":{"name":"Fontaine synchrone","description":"Quatre balles avec les deux mains qui lancent exactement au même moment, chacune de son côté.","goodFor":"Développe la symétrie et mène aux figures synchrones."},"five-ball-cascade":{"name":"Cascade à cinq balles","description":"La cascade à cinq balles : des lancers hauts et rapides dans un grand motif croisé. Comptez des mois de pratique.","goodFor":"Un cap pour les jongleurs dévoués."},"tennis":{"name":"Tennis","description":"Une cascade où une balle, la « balle de tennis », traverse toujours la figure par le haut au lieu de passer par le milieu. La main qui la tient la lance sur l'extérieur, si bien qu'elle retombe en cloche au-dessus du motif, comme un échange au-dessus du filet.","goodFor":"Premier pas vers les lancers extérieurs, sur un rythme de cascade classique.","alignmentCues":["Désigne une balle comme balle de tennis et garde-la en vue.","Lance-la depuis l'extérieur, à la même hauteur que les autres."],"commonMistakes":["Perdre de vue la balle qui passe au-dessus.","Lancer la balle du dessus plus haut que les autres."]},"half-shower":{"name":"Demi-douche","description":"Une main lance toutes les balles par-dessus pendant que l'autre les lance toutes par-dessous. Les deux arcs se séparent en un trajet haut par l'extérieur et un trajet bas par l'intérieur, et les balles se poursuivent en boucle.","goodFor":"Donner un rôle à chaque main tout en gardant un rythme régulier.","alignmentCues":["La main du dessus lance à l'extérieur, un cran plus haut.","La main du dessous garde ses lancers serrés et à l'intérieur."],"commonMistakes":["Retomber peu à peu dans la cascade classique avec les deux mains.","Collisions au milieu quand les arcs sont à la même hauteur."]},"claw-cascade":{"name":"Cascade en griffe","description":"La cascade attrapée paume vers le bas. Chaque main monte chercher la balle et la saisit en l'air par le dessus, puis tire vers le bas et retourne le poignet pour relancer. Les mains semblent griffer les balles.","goodFor":"Développe des attrapes actives et une rotation de poignet puissante.","alignmentCues":["Monte à la rencontre de la balle, doigts écartés.","Tire vers le bas et retourne le poignet en un seul geste."],"commonMistakes":["Saisir trop tard : la balle tape le dos de la main.","Relancer trop bas parce que le retournement prend trop de temps."]},"chops":{"name":"Côtelettes","description":"Après chaque attrape, la main porte la balle haut à travers le corps puis l'abat vers le bas en relançant du côté opposé. Les bras se croisent comme pour trancher, et les balles retombent en cascade serrée en dessous.","goodFor":"De grands portés de bras, avec le timing de la cascade qui continue en dessous.","alignmentCues":["Attrape haut, porte en travers, abat et lance.","Lance depuis le côté opposé de ton corps."],"commonMistakes":["Porter trop loin, si bien que l'attrape suivante arrive en retard.","Bras qui se heurtent au milieu."]},"penguin-cascade":{"name":"Cascade pingouin","description":"Les bras pendent le long du corps, paumes tournées vers le bas. Chaque attrape se fait bas et sur le côté, et les lancers jaillissent d'un coup de poignet depuis la hanche. On dirait un pingouin qui bat des ailes en rythme.","goodFor":"Des lancers menés par le poignet et des attrapes loin de la position habituelle des mains.","alignmentCues":["Coudes tendus, mains au niveau des hanches.","Coup de poignet, paumes tournées vers l'arrière."],"commonMistakes":["Replier les coudes et retomber dans la cascade normale.","Lancers qui dérivent vers l'avant parce que le poignet est trop cassé."]},"under-the-leg":{"name":"Sous la jambe","description":"Une cascade où un lancer sur six passe sous la jambe droite. Lève le genou quand la balle arrive, glisse la main sous la cuisse et lance vers le haut depuis l'extérieur, puis repose le pied pour l'attrape suivante.","goodFor":"Le premier lancer à travers le corps : lever de jambe et main qui passe dessous, le tout calé sur un seul temps.","alignmentCues":["Lève le genou avant le lancer, pas pendant.","Lance un peu plus haut pour compenser la portée supplémentaire."],"commonMistakes":["Se pencher en avant vers la jambe au lieu de lever le genou.","Se précipiter sur le lancer suivant dès que la jambe redescend."]},"behind-the-back":{"name":"Derrière le dos","description":"Un lancer sur six, la main droite passe derrière la taille et lance la balle en l'air par-dessus l'épaule opposée, pour la faire retomber dans la figure devant toi. Les autres lancers restent une cascade normale.","goodFor":"Lancer à l'aveugle dans une figure que tu ne vois pas.","alignmentCues":["Passe la main derrière tôt, au moment où la balle retombe.","Vise au-dessus de l'épaule opposée, un peu plus haut que d'habitude."],"commonMistakes":["Lancer trop vers l'avant, si bien que la balle tombe devant toi.","Pivoter tout le buste."]},"over-the-shoulder":{"name":"Par-dessus l'épaule","description":"Tous les six lancers, la main droite envoie sa balle haut de l'avant, vers le haut et vers l'arrière par-dessus l'épaule gauche. La main gauche se balance derrière sa hanche et l'attrape à l'aveugle, puis lance sa prochaine balle à côté de la hanche. Tout le reste n'est qu'une simple cascade.","goodFor":"Une prise aveugle derrière le dos, chronométrée par la sensation au lieu de la vue.","alignmentCues":["Lancez suffisamment haut pour vous vider la tête, juste derrière l'épaule gauche.","Mettez la main qui attrape derrière la hanche tôt, la paume tournée vers le haut."],"commonMistakes":["Tourner la tête pour chercher la balle.","Lancer trop bas pour que la balle clipse la tête ou l'épaule."]},"knee-bounce-cascade":{"name":"Rebond sur le genou","description":"Un lancer sur six, la main droite dépose sa balle sur le genou droit au moment où le genou monte. La balle rebondit sur le haut de la cuisse, monte et traverse vers la main gauche, et le pied redescend pour la réception suivante.","goodFor":"En équilibre sur une jambe pendant que le genou rejoint la figure sur le temps.","alignmentCues":["Lève le genou pour aller à la rencontre de la balle, à hauteur de cuisse.","Dépose la balle, ne la lance pas vers le bas."],"commonMistakes":["Donner un coup de pied dans la balle, qui part vers l'avant.","Se pencher vers le genou au lieu de le lever."]},"head-bounce-cascade":{"name":"Rebond sur la tête","description":"Un lancer sur six passe au-dessus de ta tête. Incline la tête en arrière pour que la balle se pose sur ton front, puis hoche la tête pour l'envoyer vers le bas et l'avant, dans la main gauche. Les autres lancers restent une simple cascade en dessous.","goodFor":"Suivre du regard une balle droit au-dessus de soi pendant que les mains continuent la cascade.","alignmentCues":["Incline la tête en arrière tôt et garde les yeux sur la balle.","Plie un peu les genoux pour amortir le rebond."],"commonMistakes":["Frapper la balle de la tête au lieu de la laisser atterrir.","Perdre la cascade en levant les yeux."]},"crossed-arm-cascade":{"name":"Cascade bras croisés","description":"Croise les avant-bras, main droite côté gauche, et garde-les croisés. Jongle en cascade depuis cette position. Les lancers semblent en miroir, même si la figure a l'air normale.","goodFor":"Casser l'habitude de la place de chaque main.","alignmentCues":["Garde le croisement au niveau des poignets, pas des coudes.","Les lancers culminent à hauteur des yeux, comme d'habitude."],"commonMistakes":["Décroiser les bras entre les lancers.","Mains qui se percutent en changeant de côté."]},"burkes-barrage":{"name":"Barrage de Burke","description":"Construit sur le 423. La balle lancée en 4 est attrapée en claw et portée de l'autre côté, le 2 est une courte élévation dans la même main, et le 3 est abattu vers le bas dans la figure. Les bras se tressent l'un par-dessus l'autre dans un moulinet animé.","goodFor":"Combiner portés et claws sur un siteswap que tu connais déjà.","alignmentCues":["Apprends d'abord le timing du 423, puis ajoute le porté.","Le 2 quitte à peine la main."],"commonMistakes":["Lancer le 2 si haut que ça casse le rythme.","Oublier le chop sur le 3."]},"rubensteins-revenge":{"name":"La vengeance de Rubenstein","description":"Un enchevêtrement de portés sur le 52233. Un lancer haut te donne du temps pendant que les mains s'attrapent en claw, font le chop et se croisent, puis la figure se déroule à nouveau en cascade. Apprends-le lentement, une main à la fois.","goodFor":"Une figure de spectacle qui travaille les portés, les claws et les bras croisés en même temps.","alignmentCues":["Le 5 est le seul lancer haut.","Apprends le trajet des mains sans la balle haute."],"commonMistakes":["Paniquer pendant les portés et lancer trop tôt.","Le lancer haut qui dérive vers l'avant."]},"siteswap-42":{"name":"42 à deux balles","description":"Deux balles : chaque main se lance une balle haute et garde l'autre un temps. Les balles hautes montent en colonnes de chaque côté pendant que les mains se relaient. Une façon tranquille d'apprendre les selfs.","goodFor":"Des lancers sur place à hauteur 4, la brique de base du deux dans une main.","alignmentCues":["Chaque lancer reste de son côté.","Garde le 2 immobile dans la paume."],"commonMistakes":["Des lancers qui dérivent vers le centre.","Lancer la balle tenue par erreur."]},"snake":{"name":"Serpent","description":"Trois balles lancées en cinqs croisés bien hauts, avec un temps vide après chacune. Les balles se suivent l'une après l'autre le long du même grand arc, comme un serpent qui glisse au-dessus de ta tête.","goodFor":"Des lancers hauts et réguliers, sans la pression d'un rythme complet à cinq balles.","alignmentCues":["Tous les cinqs à la même hauteur.","Profite du temps vide pour replacer la main."],"commonMistakes":["Des cinqs qui dérivent vers l'avant.","Lancer sur le temps vide par habitude."]},"grace":{"name":"Grace","description":"Un multiplex tout en douceur : une main lance deux balles en même temps, un lancer croisé normal et une petite passe directe vers l'autre main. Puis un temps tenu, et retour à la cascade.","goodFor":"Une introduction en douceur aux lancers du deux dans une main.","alignmentCues":["Lâche les deux balles en même temps.","La petite s'élève à peine."],"commonMistakes":["Lâcher les deux balles à des moments différents.","Lancer la petite balle trop haut."]},"orinoco-flow":{"name":"Flux de l'Orénoque","description":"Deux tours de 42 avec un lancer de cascade cousu au bout, si bien que les lancers sur place changent de côté à chaque tour. Le motif ondule entre colonnes et cascade.","goodFor":"Basculer en douceur entre lancers sur place et lancers croisés.","alignmentCues":["Des quatres qui montent tout droit à côté de toi.","Le 3 est un lancer de cascade normal."],"commonMistakes":["Des quatres qui penchent vers l'intérieur.","Perdre le compte du cycle de cinq lancers."]},"relfs-rhythm":{"name":"Rythme de Relf","description":"Un lancer sur place et une tenue, puis trois lancers de cascade. Comme le cycle est impair, le lancer sur place atterrit dans l'autre main à chaque tour.","goodFor":"Insérer une figure dans une cascade en cours, d'un côté comme de l'autre.","alignmentCues":["Commence par la cascade, puis insère le 42.","Garde le quatre de son côté."],"commonMistakes":["Le faire uniquement de la main dominante.","La cascade qui s'accélère ensuite."]},"frostbite":{"name":"Gelure","description":"Deux quatres rapides, une passe éclair en travers, puis deux lancers de cascade. La passe se faufile par-dessous pendant que les quatres flottent au-dessus.","goodFor":"Mélanger des passes rapides et des lancers hauts dans un même cycle.","alignmentCues":["Le 1 est un petit geste sec, direct en travers.","Les quatres restent verticaux."],"commonMistakes":["Lancer le 1 en cloche au lieu de le passer.","Oublier le deuxième quatre."]},"siteswap-52512":{"name":"52512","description":"Deux 5 hauts séparés par un temps tenu, puis un 5, une passe rapide et un temps tenu. Le motif mêle des lancers croisés hauts et des lancers courts et bas.","goodFor":"Contrôle précis haut-bas à trois balles.","alignmentCues":["Les 5 atteignent tous la même hauteur.","Les 2 restent en main."],"commonMistakes":["Lancer les 2.","Des 5 irréguliers."]},"high-low-shower":{"name":"Douche haut-bas","description":"Une douche avec une variante : une balle monte très haut pendant que les autres traversent en dessous, basses et rapides. Le rythme ressemble à un galop.","goodFor":"Grand contraste de hauteur et mains rapides dans un motif à trois balles.","alignmentCues":["Le 7 part haut et tout droit.","Les 1 sont des passes à plat."],"commonMistakes":["Les 7 dérivent vers l'avant.","Les 1 montent trop en cloche."]},"siteswap-612":{"name":"612","description":"Un self haut, une passe rapide et un temps tenu. Le 6 monte à côté de toi, du même côté, pendant que les deux autres balles s'échangent en dessous.","goodFor":"Des selfs hauts mêlés à des passes basses et rapides.","alignmentCues":["Le 6 reste de son côté.","Passe le 1 à plat et vite."],"commonMistakes":["Le 6 croise de l'autre côté.","Tenir le 2 trop longtemps."]},"three-in-one":{"name":"Trois balles dans une main","description":"Trois balles jonglées avec la seule main droite, en colonnes hautes ou en petite fontaine. Chaque lancer est haut, ce qui laisse le temps d'attraper et de relancer.","goodFor":"Contrôle à une main et régularité de la hauteur.","alignmentCues":["Les lancers culminent bien au-dessus de la tête.","Garde la main en mouvement dans un petit cercle."],"commonMistakes":["Les lancers dérivent vers l'extérieur.","Lancers trop bas pour garder les trois en l'air."]},"columns":{"name":"Colonnes","description":"Trois balles qui montent en colonnes verticales. Les deux mains lancent leurs balles extérieures ensemble, puis la droite lance la balle du milieu toute seule. Ça monte, ça monte, ça monte, comme des pistons.","goodFor":"Premiers lancers simultanés et base pour plein de tricks en synchro.","alignmentCues":["Les colonnes extérieures montent ensemble.","La colonne du milieu monte tout droit depuis le centre."],"commonMistakes":["Les colonnes s'inclinent et les balles se percutent.","Timing irrégulier sur la paire."]},"infinity":{"name":"Infini","description":"Un motif de colonnes où le lancer seul part en travers au lieu de monter tout droit, si bien que la balle du milieu change de côté à chaque fois. Les balles dessinent un huit.","goodFor":"Basculer un motif en synchro d'un côté à l'autre.","alignmentCues":["La paire tout droit, le lancer seul en travers.","Les côtés alternent à chaque cycle."],"commonMistakes":["Le lancer seul part tout droit par habitude.","La paire dérive."]},"rainbow-cross":{"name":"Croix arc-en-ciel","description":"Deux balles se croisent en même temps, puis une monte tout droit au milieu. Les arcs croisés dessinent un arc-en-ciel au-dessus de ta tête.","goodFor":"Lancers croisés synchrones, sans collisions.","alignmentCues":["Un lancer croisé légèrement devant l'autre.","Le lancer du milieu monte tout droit."],"commonMistakes":["Les balles se percutent en croisant.","Le lancer du milieu penche."]},"crossunder":{"name":"croisement par dessous","description":"Tous les lancers croisent : une paire croisée, puis un lancer croisé seul qui change de côté à chaque cycle. Les balles passent tour à tour au-dessus et en dessous l'une de l'autre.","goodFor":"Contrôle d'un synchrone où tout croise.","alignmentCues":["Garde les lancers croisés dans des plans légèrement décalés.","Hauteur régulière tout du long."],"commonMistakes":["Collisions au milieu.","Le lancer seul trop bas."]},"yo-yo":{"name":"Yo-Yo","description":"Une main lance des colonnes pendant que l'autre garde une balle en main et la fait monter et descendre sous l'une d'elles, comme si les deux balles étaient reliées par une ficelle.","goodFor":"Une illusion qui apprend à déplacer une balle tenue le long d'une colonne.","alignmentCues":["La balle tenue suit la balle de la colonne.","Les colonnes restent verticales."],"commonMistakes":["La balle tenue prend du retard.","Les colonnes s'écartent."]},"box":{"name":"Boîte","description":"Les balles dessinent un carré. Une main lance une balle tout droit vers le haut pendant que l'autre en passe une en travers, puis les rôles s'inversent. Côtés verticaux, haut et bas bien à plat.","goodFor":"Une figure synchrone classique qui travaille les passes horizontales.","alignmentCues":["Les passes traversent tout droit à hauteur de main.","Les verticales montent tout droit."],"commonMistakes":["Les passes partent trop en cloche.","Les colonnes penchent vers l'intérieur."]},"broken-box":{"name":"Boîte cassée","description":"Une box qui change de côté à chaque lancer : le lancer vertical et la passe croisée alternent de main, si bien que le carré se replie sans arrêt sur lui-même.","goodFor":"Changement de rôles rapide en synchrone.","alignmentCues":["Alterne le vertical à chaque temps.","Fais la passe à plat et rapidement."],"commonMistakes":["Répéter le vertical du même côté.","Précipiter la passe."]},"als-slide":{"name":"Al's Slide","description":"Un lancer haut croisé associé à une passe à plat, puis une tenue et un autre lancer haut croisé. Les balles glissent en haut et en bas dans un mouvement roulant bien fluide.","goodFor":"Lancers croisés synchrones mêlés à des passes et des tenues.","alignmentCues":["Les lancers croisés en 4 culminent ensemble.","Garde le 2 bien immobile."],"commonMistakes":["Tu lances la balle tenue.","Les balles se percutent au milieu."]},"factory":{"name":"Usine","description":"Une main fait office de tapis roulant, transportant les balles en travers à hauteur de taille, pendant que l'autre main lance des colonnes. Les balles tournent en boucle, dans un cycle mécanique.","goodFor":"Coordination porté-lancer en synchro.","alignmentCues":["La main qui porte décrit une grande boucle.","Les verticales restent hautes."],"commonMistakes":["La main qui porte dépose les balles dans la colonne.","Les colonnes penchent."]},"broken-shower":{"name":"Shower brisé","description":"Un shower synchrone : la main droite lance haut en travers pendant que la gauche passe bas en travers au même moment. Les balles tournent en boucle serrée.","goodFor":"Une version en synchro de la boucle du shower.","alignmentCues":["Les deux mains lâchent en même temps.","Arc haut pour la droite, passe à plat pour la gauche."],"commonMistakes":["Tu lâches les balles l'une après l'autre.","La passe monte en arc vers la balle haute."]},"crossed-arm-shower":{"name":"Shower bras croisés","description":"Le shower jonglé avec les avant-bras croisés. Les lancers hauts partent du côté gauche du corps et les passes rapides repassent en dessous.","goodFor":"Contrôle du shower dans une position de bras inhabituelle.","alignmentCues":["Reste croisé tout du long.","Garde les passes près du corps."],"commonMistakes":["Tu décroises les bras pour rattraper.","Des passes trop hautes."]},"siteswap-534":{"name":"534","description":"Une figure à quatre balles mêlant un cinq croisé, un trois en cascade et un quatre self. On dirait un 423 à quatre balles, et ça mène naturellement à la fontaine.","goodFor":"La figure à quatre balles la plus populaire, et une porte d'entrée vers des siteswaps plus élevés.","alignmentCues":["Le cinq au plus haut, le trois au plus bas.","Le quatre reste de son côté."],"commonMistakes":["Tu aplatris les hauteurs.","Tu précipites le trois."]},"siteswap-552":{"name":"552","description":"Deux cinq croisés et un hold. Quatre balles jonglées sur un rythme à cinq balles, avec un temps pour respirer.","goodFor":"Des lancers hauteur cinq avec le temps de récupérer.","alignmentCues":["Les deux cinq identiques.","Garde le 2 immobile."],"commonMistakes":["Tu lances le hold.","Les cinq dérivent vers l'avant."]},"siteswap-5551":{"name":"5551","description":"Trois cinq d'affilée et une passe rapide. Une bonne étape vers la cascade à cinq balles.","goodFor":"Travailler des séries de cinq avec quatre balles.","alignmentCues":["Les cinq tous à la même hauteur.","Une passe rapide et à plat pour le 1."],"commonMistakes":["Les cinq perdent de la hauteur.","Tu lobes le 1."]},"siteswap-55550":{"name":"55550","description":"Quatre cinqs et une main vide. Une cascade à cinq balles avec une balle en moins, ce qui en fait une excellente répétition pour la cascade à cinq.","goodFor":"La dernière étape avant la cascade à cinq balles.","alignmentCues":["Profite du vide pour te stabiliser.","Cinqs réguliers."],"commonMistakes":["Tu lances dans le vide.","Cinqs qui dérivent."]},"siteswap-633":{"name":"633","description":"Un self haut puis deux lancers de cascade. Le six reste suspendu en hauteur pendant que la cascade tourne en dessous.","goodFor":"Des selfs hauts tissés dans un rythme à quatre balles.","alignmentCues":["Le six reste au-dessus de sa propre main.","Les trois restent bas."],"commonMistakes":["Le six dérive en travers.","Trois trop hauts."]},"siteswap-53":{"name":"53","description":"Une main lance des cinqs croisés en hauteur pendant que l'autre lance des trois de cascade bien bas. Une shower à quatre balles, moitié haute, moitié basse.","goodFor":"Contrôle des hauteurs entre les deux mains.","alignmentCues":["Main droite en haut, main gauche en bas.","Rythme régulier."],"commonMistakes":["Les hauteurs se rapprochent.","Tu précipites les trois."]},"wimpy":{"name":"Le Wimpy","description":"Quatre balles où chaque paire croise en même temps. Les arcs changent de côté à chaque temps dans un large croisement.","goodFor":"Synchronisation des croisés à quatre balles.","alignmentCues":["Une main lance un peu trop devant.","Lâche en même temps."],"commonMistakes":["Collision au milieu.","Tu décales le lâcher."]},"four-ball-shower":{"name":"Shower à quatre balles","description":"Quatre balles en cercle : des lancers très hauts d'une main et des passes à plat de l'autre.","goodFor":"Régularité des lancers hauts à quatre balles.","alignmentCues":["Septs droits et hauts.","Passes rapides et à plat."],"commonMistakes":["Septs qui dérivent vers l'avant.","Passes qui montent."]},"tsunami":{"name":"Tsunami","description":"Un sept haut, une retenue, un self quatre, une passe et un self six très haut. Des vagues de hauteur déferlent dans le pattern.","goodFor":"Contrôle avancé des hauteurs mixtes à quatre balles.","alignmentCues":["Apprends les lancers lentement, dans l'ordre.","Le sept et le six partent tous les deux en hauteur."],"commonMistakes":["Hauteurs irrégulières.","Tu perds le compte."]},"siteswap-645":{"name":"645","description":"La version à cinq balles du 534 : un self six bien haut, un self quatre et un cinq croisé.","goodFor":"Un premier trick à partir de la cascade à cinq balles.","alignmentCues":["Six tout en haut.","Le quatre reste de son côté."],"commonMistakes":["Hauteurs qui s'aplatissent.","Dérive."]},"siteswap-744":{"name":"744","description":"Un sept croisé très haut suivi de deux selfs quatre.","goodFor":"Insertion d'un lancer haut à cinq balles.","alignmentCues":["Sept droit et bien haut.","Quatres bien verticaux."],"commonMistakes":["Le sept dérive.","Les quatres se croisent."]},"five-ball-shower":{"name":"Shower à cinq balles","description":"Cinq balles en boucle : des neufs très hauts d'une main et des passes à plat qui reviennent par en dessous.","goodFor":"Hauteur et précision au sommet de l'échelle.","alignmentCues":["Neufs droits et réguliers.","Passes à plat."],"commonMistakes":["Neufs qui vagabondent.","Passes qui montent."]},"five-ball-half-shower":{"name":"Demi-shower à cinq balles","description":"Lancers croisés en synchrone, une main plus haute que l'autre, avec cinq balles.","goodFor":"Maîtrise des croisés synchrones à cinq balles.","alignmentCues":["Droite plus haute, gauche plus basse.","Lâchez ensemble."],"commonMistakes":["Hauteurs qui convergent.","Collisions."]},"martins-one-count":{"name":"Schéma de Martin","description":"Un multiplex : un six haut et une balle tenue, lâchés ensemble, puis une balle qui reste en main et un cinq croisé.","goodFor":"Timing du multiplex à cinq balles.","alignmentCues":["Le multiplex se libère proprement.","Le cinq croise."],"commonMistakes":["Séparation du multiplex.","Le six dérive."]},"six-ball-fountain":{"name":"Fontaine à six balles","description":"Trois balles dans chaque main, jonglées en deux fontaines hautes côte à côte.","goodFor":"Le cap du numbers à six balles.","alignmentCues":["Chaque main fait tourner sa propre fontaine.","Lancers hauts et réguliers."],"commonMistakes":["Fontaines qui dérivent ensemble.","Lancers trop bas."]},"club-swing":{"name":"Spin simple de massue","description":"Tiens une massue par le manche, le pommeau calé dans le talon de la main. Balance-la vers le haut depuis la taille pour qu'elle fasse un tour en l'air et arrive manche en premier dans l'autre main. Renvoie-la de la même façon.","goodFor":"Apprendre le spin simple, la base de toutes les figures à la massue.","alignmentCues":["Lève depuis le coude, laisse le poignet faire tourner la massue.","Attrape le manche à hauteur de taille."],"commonMistakes":["Un coup de poignet qui fait faire un tour de trop à la massue.","Lancer vers l'avant : le manche atterrit loin devant toi."]},"club-exchange":{"name":"Échange à deux massues","description":"Une massue dans chaque main. Lance un simple de la main droite ; au sommet du lancer, envoie la massue gauche en dessous. Attrape les deux par le manche, marque une pause, puis repars avec l'autre main.","goodFor":"Le timing de deux massues en rotation, sans collision.","alignmentCues":["La deuxième massue part au sommet de la première.","Lance la deuxième massue à l'intérieur de la première."],"commonMistakes":["Les massues s'entrechoquent au milieu.","Une rotation inégale entre les deux mains."]},"club-cascade":{"name":"Cascade à trois massues","description":"La cascade avec des massues, chacune faisant un tour. Les lancers partent de l'intérieur du corps et traversent, les manches toujours pointés vers toi.","goodFor":"La figure de base de toute la jonglerie aux massues.","alignmentCues":["Lance depuis le coude, garde les poignets souples.","Les massues restent parallèles à ta poitrine."],"commonMistakes":["Les massues s'inclinent et se mettent à tourner sur le côté.","Une rotation trop rapide qui emporte la massue contre le corps."]},"club-doubles":{"name":"Doubles aux massues","description":"Une cascade à trois massues où chaque massue fait deux tours en l'air. Les lancers sont plus hauts et plus lents, et les massues dessinent de grands cercles flous.","goodFor":"Le contrôle de la rotation et la hauteur nécessaire pour quatre massues.","alignmentCues":["Lève davantage avec le bras, pas avec le poignet.","Garde le double bien fluide et régulier."],"commonMistakes":["Un coup de poignet trop sec, et la massue fait un tour de trop.","Lancer les doubles trop bas."]},"club-flats":{"name":"Massues à plat","description":"Une cascade où les massues ne tournent pas du tout. Chaque massue traverse en flottant, manche vers le bas, poussée vers le haut par un poignet bien tendu, et arrive droite dans l'autre main.","goodFor":"Le contrôle du poignet, et un contraste facile avec les lancers en rotation.","alignmentCues":["Verrouille le poignet et pousse depuis le coude.","La massue reste droite tout du long."],"commonMistakes":["Des demi-tours involontaires.","Lancer trop haut, si haut que la massue vacille."]},"club-under-leg":{"name":"Massue sous la jambe","description":"Une cascade à la massue où un lancer sur six passe sous la jambe droite. Lève le genou, balance la massue sous la cuisse et laisse-la remonter en tournant dans la figure.","goodFor":"Le premier lancer sous le corps avec les massues.","alignmentCues":["Lève le genou en avance.","Un peu de hauteur en plus sur le lancer sous la jambe."],"commonMistakes":["La massue touche la jambe.","Se pencher en avant au lieu de lever le genou."]},"club-behind-back":{"name":"Massue derrière le dos","description":"Une cascade de massues où un lancer sur six est balancé derrière la taille et renvoyé par-dessus l'épaule opposée pour réintégrer la figure.","goodFor":"Des lancers de massues à l'aveugle derrière le corps.","alignmentCues":["Balance le bras derrière toi tôt.","Vise par-dessus l'épaule opposée."],"commonMistakes":["La massue atterrit trop loin devant.","Torsion du buste."]},"club-four-fountain":{"name":"Fontaine à quatre massues","description":"Deux massues dans chaque main, chaque main lance des doubles dans sa propre fontaine. Les massues ne franchissent jamais le milieu.","goodFor":"L'étape clé des quatre massues.","alignmentCues":["Des doubles de chaque côté.","Les mains alternent régulièrement."],"commonMistakes":["Les massues dérivent vers le centre.","Rotations inégales entre les mains."]},"ring-cascade":{"name":"Cascade à trois anneaux","description":"La cascade avec les anneaux tenus de chant, comme un volant de voiture vu de côté. Chaque anneau traverse la figure sans tourner, et les bords tranchent l'air proprement.","goodFor":"Une façon simple d'essayer les anneaux et de sentir comment ils flottent.","alignmentCues":["Tiens l'anneau de chant face à toi.","Lâche avec le poignet bien droit."],"commonMistakes":["Les anneaux oscillent à cause d'un poignet plié.","Les lancer à plat, ce qui les fait prendre le vent."]},"ring-pancakes":{"name":"Pancakes d'anneaux","description":"Une cascade d'anneaux où chaque anneau se retourne à plat au sommet du lancer et revient de chant pour la réception, comme une crêpe retournée dans la poêle.","goodFor":"Un contrôle du poignet et un flourish d'anneaux spectaculaire.","alignmentCues":["Un bref tour de poignet au lâcher.","Rattrape l'anneau de chant à nouveau."],"commonMistakes":["Trop de rotation.","Lancer trop bas : l'anneau n'a pas le temps de se retourner."]},"ring-four-fountain":{"name":"Fontaine à quatre anneaux","description":"Deux anneaux dans chaque main, jonglés en fontaines séparées, les bords tranchant l'air à la verticale.","goodFor":"Quatre objets avec un accessoire léger et flottant.","alignmentCues":["Les anneaux restent de chant.","Chaque main gère sa propre colonne."],"commonMistakes":["Les anneaux se touchent au milieu.","Les lancers dérivent vers l'avant."]},"hoop-juggle-single":{"name":"Lancer à un seul hoop","description":"Tiens un hoop par le bord, qui pend à côté de toi. Lance-le dans un arc doux vers l'autre main, pour qu'il voyage de chant et arrive à la même hauteur qu'au départ.","goodFor":"Apprendre comment vole un hoop de taille standard avant d'en ajouter d'autres.","alignmentCues":["Garde le cerceau de chant face à ta poitrine.","Lance depuis l'épaule, pas du poignet."],"commonMistakes":["Lance-le de face pour qu'il flotte au loin.","Lance bas et attrape."]},"hoop-juggle-exchange":{"name":"Échange à deux cerceaux","description":"Un cerceau dans chaque main. Lance celui de droite ; quand il atteint son point culminant, lance celui de gauche en dessous. Les cerceaux se croisent de près, l'un devant l'autre.","goodFor":"Le timing à deux cerceaux et éviter les collisions.","alignmentCues":["Deuxième cerceau au sommet du premier.","Lance le deuxième légèrement devant."],"commonMistakes":["Les cerceaux se percutent.","Lancer les deux trop vite."]},"hoop-juggle-cascade":{"name":"Cascade à trois cerceaux","description":"La cascade avec des cerceaux pleine taille. Les mains restent bien écartées, les lancers sont amples et lents, et chaque cerceau tourne de chant tout au long de la figure.","goodFor":"La figure de base pour jongler avec des cerceaux.","alignmentCues":["Bras écartés, coudes souples.","Tous les cerceaux dans le même plan."],"commonMistakes":["Les cerceaux dérivent vers l'avant.","Précipiter les lancers."]},"hoop-juggle-reverse":{"name":"Fausse cascade à cerceaux","description":"Des cerceaux lancés par le haut depuis l'extérieur et rattrapés à l'intérieur : la fausse cascade, en grand.","goodFor":"Des lancers extérieurs avec des cerceaux.","alignmentCues":["Lance depuis l'extérieur, par le haut.","Attrape vers le centre."],"commonMistakes":["Les cerceaux retombent trop large.","Des trajectoires inégales."]},"hoop-juggle-shower":{"name":"Shower à cerceaux","description":"Trois cerceaux en cercle : des lancers hauts d'une main et des passes rapides par-dessous.","goodFor":"La hauteur et le contrôle des passes avec des cerceaux.","alignmentCues":["Des lancers hauts, à la verticale puis en travers.","Passe près du corps."],"commonMistakes":["Des lancers hauts qui dérivent.","Des passes qui montent."]},"hoop-juggle-two-in-one":{"name":"Deux cerceaux dans une main","description":"Deux cerceaux jonglés avec la seule main droite, qui montent en colonnes à côté de toi.","goodFor":"Le contrôle des cerceaux à une main.","alignmentCues":["Les colonnes restent verticales.","Lance haut pour gagner du temps."],"commonMistakes":["Les cerceaux dérivent vers l'extérieur.","Trop bas."]},"hoop-juggle-423":{"name":"Cerceau 423","description":"Le siteswap 423 avec trois hoops : un quatre en self, un deux tenu et un trois croisé.","goodFor":"Variété de siteswaps avec des hoops.","alignmentCues":["Le quatre reste de son côté.","Garde le 2 en main."],"commonMistakes":["Le 2 lancé.","Le quatre part en travers."]},"hoop-juggle-441":{"name":"Cerceau 441","description":"Deux quatre en self et un passage de main à main rapide avec des hoops. Le passage glisse sous la paire haute.","goodFor":"Passages de main à main rapides entre des lancers de hoops hauts.","alignmentCues":["Les quatre verticaux.","Passage à plat."],"commonMistakes":["Passage en cloche.","Les quatre qui dérivent."]},"hoop-juggle-four":{"name":"Fontaine à quatre hoops","description":"Deux hoops dans chaque main, jonglés en fontaines côte à côte.","goodFor":"L'étape clé des quatre hoops.","alignmentCues":["Chaque côté séparé.","Rythme régulier."],"commonMistakes":["Les hoops qui dérivent ensemble.","Lancers trop bas."]},"hoop-juggle-under-leg":{"name":"Hoop sous la jambe","description":"Une cascade de hoops avec un lancer sur six passé sous la jambe droite levée.","goodFor":"Lancers autour du corps avec un grand accessoire.","alignmentCues":["Monte le genou bien haut.","Lance un peu plus haut."],"commonMistakes":["Le hoop accroche le pied.","Buste penché en avant."]},"hoop-juggle-back-throw":{"name":"Hoop derrière le dos","description":"Une cascade de hoops où un lancer sur six passe derrière le dos et au-dessus de l'épaule opposée.","goodFor":"Lancers à l'aveugle avec des hoops.","alignmentCues":["Amène le hoop derrière tôt.","Au-dessus de l'épaule opposée."],"commonMistakes":["Le hoop retombe devant.","Le buste qui se tord."]},"hoop-juggle-body-hoop":{"name":"Jongler en hula hoop","description":"Garde un hoop en rotation à la taille pendant que tu jongles avec trois autres en cascade. Les hanches gardent leur propre rythme sous les bras.","goodFor":"Attention partagée entre le hoop à la taille et le jonglage.","alignmentCues":["Les hanches pilotent le hoop à la taille, les bras restent indépendants.","Garde le plan de jonglage devant le hoop à la taille."],"commonMistakes":["Le hoop à la taille ralentit quand tu te concentres sur le jonglage.","Les bras qui retombent dans le hoop autour du corps."]},"pass-one-ball":{"name":"Passe à une balle","description":"Placez-vous face à votre partenaire, à environ deux mètres et demi l'un de l'autre. Lancez une balle de votre main droite dans un arc doux vers sa main gauche. Votre partenaire la transfère à sa main droite et la relance vers votre gauche ; vous la transférez ensuite à nouveau vers votre droite.","goodFor":"Apprendre la hauteur et la distance d'une passe avant même de jongler.","alignmentCues":["Lancez droit en face, sans croiser.","Le sommet est juste au-dessus de la tête, à mi-chemin entre vous deux.","Regardez votre partenaire, pas la balle dans votre main."],"commonMistakes":["Lancer droit vers le visage du partenaire au lieu de monter en courbe.","Viser la main droite du partenaire, ce qui fait croiser la passe."]},"pass-hand-across":{"name":"Passe à deux balles","description":"Deux balles chacun. Vous passez tous les deux de la main droite sur le même temps. Chaque main gauche rattrape la passe entrante et la transfère directement à la droite, prête pour la passe suivante. Rien n'est lancé pour soi : tout est une question de caler les passes ensemble.","goodFor":"Passer sur un temps commun avant d'ajouter la cascade.","alignmentCues":["Passez ensemble : les mains droites sur le temps.","Rattrapez avec la gauche, transférez bas et vite."],"commonMistakes":["L'un des deux passe trop tôt, et les passes se croisent en l'air à des moments différents.","Lancer le transfert au lieu de le faire de la main à la main."]},"pass-six-count":{"name":"Six temps","description":"Vous jonglez tous les deux en cascade à trois balles et passez toutes les six lances, toujours de la main droite vers la main gauche de votre partenaire. Entre les passes, vous avez cinq selfs pour stabiliser le pattern.","goodFor":"Le premier pattern de passing complet : tout le temps qu'il faut entre les passes.","alignmentCues":["Comptez à voix haute : passe, deux, trois, quatre, cinq, six.","Gardez vos selfs à la même hauteur que la passe.","Regardez votre partenaire, pas vos mains."],"commonMistakes":["Perdre le compte et passer sur le mauvais temps.","Passer trop court, obligeant votre partenaire à se jeter en avant."]},"pass-four-count":{"name":"Quatre temps","description":"Passe un lancer sur quatre, soit un lancer sur deux de la main droite. Passe, self, self, self, puis repasse. C’est l’échauffement standard du passing à massues et la base de la plupart des variations.","goodFor":"La figure de passing du quotidien ; la plupart des tricks partent d’ici.","alignmentCues":["Les mains droites passent en même temps.","Trois selfs, puis la passe revient."],"commonMistakes":["Raccourcir les selfs pour laisser le temps à la passe.","Pivoter les épaules pour lancer au lieu d’utiliser l’avant-bras."]},"pass-three-count":{"name":"Trois temps","description":"Passe un lancer sur trois, donc les passes alternent de main en main : droite, puis gauche, puis droite. Chaque passe de la main gauche part en face, vers la main droite de ton partenaire.","goodFor":"Passer des deux mains et attraper des deux mains.","alignmentCues":["Les passes de la main gauche partent en face, comme celles de la droite.","Garde la même hauteur de passe des deux mains."],"commonMistakes":["Une passe molle de la main gauche qui tombe court.","Croiser la passe de gauche vers sa main gauche."]},"pass-two-count":{"name":"Deux temps","description":"Chaque lancer de la main droite est une passe, chaque lancer de la main gauche est un self. Passe, self, passe, self. Deux fois plus de passes qu’au quatre temps, avec le même jeu de jambes.","goodFor":"Un rythme de passing rapide et régulier ; la porte d’entrée vers les figures à sept objets.","alignmentCues":["La main droite passe, la main gauche fait des selfs.","Garde le self de gauche à l’intérieur, sous la passe qui arrive."],"commonMistakes":["Laisser les selfs descendre de plus en plus bas.","Attraper les passes trop près du corps."]},"pass-left-two-count":{"name":"Deux temps main gauche","description":"Le deux temps en miroir : chaque lancer de la main gauche est une passe, en face vers la main droite de ton partenaire, et la main droite fait des selfs.","goodFor":"Équilibrer ta main de passe la plus faible.","alignmentCues":["Les passes de gauche partent en face, pas en croisé.","Même hauteur et même impulsion que tes passes de la droite."],"commonMistakes":["Passer trop court de la main faible.","Revenir aux passes de la main droite par habitude."]},"pass-ultimates":{"name":"Ultimates","description":"Chaque lancer est une passe. Les mains droites passent en face vers les mains gauches, et les mains gauches passent en face vers les mains droites ; personne ne lance de self. Les balles forment un flux continu entre vous deux.","goodFor":"Précision et rythme du passing sous pression.","alignmentCues":["Chaque lancer part en face : droite, gauche, droite, gauche.","Attrape et repasse en un seul geste fluide."],"commonMistakes":["Garder une balle en main et casser le flux.","Des passes de plus en plus plates quand le tempo monte."]},"club-pass-four-count":{"name":"Quatre temps à massues","description":"Le quatre temps avec massues. Chaque passe est un tour simple, lancée de la main droite vers la main gauche de ton partenaire, et arrive manche en premier. Trois selfs simples entre les passes.","goodFor":"Le début classique de toute session de passing à massues.","alignmentCues":["Passe depuis le côté de la hanche droite, avec un geste bien droit vers l’avant.","Un tour simple : le manche doit atterrir dans la main de ton partenaire."],"commonMistakes":["Trop de rotation : la passe arrive pommeau en premier.","Passe devant toi vers la droite de ton partenaire."]},"club-pass-two-count":{"name":"Deux temps aux massues","description":"Chaque lancer de la main droite est une passe simple, chaque lancer de la main gauche un self simple. Le rythme de base du passing aux massues.","goodFor":"Un rythme de passing aux massues bien régulier.","alignmentCues":["Passe, self, passe, self, sur les temps pairs.","Garde le self gauche serré et vers l’intérieur."],"commonMistakes":["Perte de rotation sur le self gauche.","Passes qui partent à gauche et à droite."]},"club-pass-three-count":{"name":"Trois temps aux massues","description":"Tu passes une massue un lancer sur trois, donc les passes alternent de main. Les passes de la main gauche traversent en ligne droite vers la droite de ton partenaire.","goodFor":"Passes de massue de la main faible.","alignmentCues":["Le même geste des deux mains.","Droite, puis gauche, puis droite : compte à voix haute."],"commonMistakes":["Passes de la main gauche avec trop peu de rotation.","Pivot du corps pour la passe de la main gauche."]},"club-pass-doubles":{"name":"Quatre temps aux massues avec doubles","description":"Un quatre temps où chaque passe est une double, lancée plus haut pour atterrir un temps plus tard. Pour laisser la place, la main gauche garde sa massue un temps après la passe au lieu de lancer.","goodFor":"La double passe, première étape vers le passing à sept massues.","alignmentCues":["Une double passe est plus haute et plus lente : deux tours complets.","Garde la massue gauche le temps de la passe, puis continue."],"commonMistakes":["Lancer la double aussi vite qu’une simple : elle tourne trop.","Lancer la massue gauche au lieu de la garder."]},"club-pass-ultimates":{"name":"Ultimates aux massues","description":"Chaque lancer est une passe simple, alternant droite et gauche. Six massues circulent entre vous, sans selfs.","goodFor":"La précision du passing aux massues à pleine cadence.","alignmentCues":["Attrape et passe en un seul geste.","Passes droites : de droite à gauche, de gauche à droite."],"commonMistakes":["Passes qui dérivent vers le centre et se percutent.","Garder une massue et casser le flux."]},"club-pass-seven-doubles":{"name":"Doubles croisés à sept massues","description":"Sept massues entre vous deux. Ta main droite passe un double croisé à la main droite de ton partenaire un lancer sur deux, et sa main gauche répond un lancer plus tard avec un double croisé vers ta gauche. Des simples comblent les intervalles.","goodFor":"Une première figure à sept massues, construite sur les doubles.","alignmentCues":["Tes doubles partent en croisé vers la main droite du partenaire.","Attrape son double dans ta main gauche, juste après ta propre passe."],"commonMistakes":["Passer droit au lieu de croiser.","Doubles trop bas pour finir leurs deux tours."]},"staff-wheel-spin":{"name":"Rotation de bâton à deux mains en roue","description":"Tenez le bâton au milieu avec les deux mains, paumes vers le bas, à hauteur de poitrine. Faites-le tourner à votre côté comme une roue en passant la rotation d'une main à l'autre, en le gardant près du corps.","goodFor":"La première rotation de bâton ; développe la prise et la rotation du poignet.","alignmentCues":["Le bâton reste parallèle à votre corps, sans jamais s'incliner.","Prise souple : laissez-le rouler entre les doigts."],"props":["bâton"],"commonMistakes":["Serrer trop fort, ce qui bloque la rotation.","Incliner le plan vers l'avant."]},"staff-front-spin":{"name":"Moulin à vent avant","description":"Faites tourner le bâton devant vous comme une hélice, dans le plan du mur, en le passant fluidement d'une main à l'autre autour de son centre.","goodFor":"Ajoute le plan du mur et le passage main par main.","props":["bâton"]},"staff-figure-8":{"name":"Tissage en huit","description":"Faites tourner le bâton dans le plan de la roue sur votre côté droit, puis croisez-le vers votre côté gauche et faites-le tourner là, en traçant un huit devant vous.","goodFor":"Relie les deux côtés du corps ; la base du flow au bâton.","alignmentCues":["Changez de côté quand les embouts passent près du sol.","Faites pivoter légèrement le torse à chaque changement de côté."],"props":["bâton"]},"staff-pass-through":{"name":"Passage à travers","description":"Tournez dans le plan du mur mais lâchez à chaque demi-tour : une main relâche le bâton et l'autre le rattrape au centre, de sorte que le bâton passe entre vos mains.","goodFor":"Enseigne le timing du lâcher et de la réception.","props":["bâton"]},"staff-one-hand-spin":{"name":"Rotation à une main","description":"Faites tourner le bâton devant vous avec une main, en le faisant rouler sur le dos de la main et entre les doigts. Entraînez les deux mains.","goodFor":"Force des doigts et du poignet ; libère l'autre main pour les figures.","props":["bâton"]},"staff-helicopter":{"name":"Hélicoptère au-dessus de la tête","description":"Levez le bâton au-dessus de la tête et faites-le tourner à plat dans le plan du sol avec une main, comme les pales d'un hélicoptère.","goodFor":"Introduit le plan du sol.","props":["bâton"]},"staff-butterfly":{"name":"Papillon","description":"Tournez devant vous, puis repliez le bâton derrière votre épaule et ressortez-le, en alternant avant et arrière de chaque côté comme des ailes.","goodFor":"Mobilité des épaules et transition fluide d'avant en arrière.","props":["bâton"]},"staff-behind-back-pass":{"name":"Passage dans le dos","description":"Passez le bâton en rotation d'une main à l'autre derrière votre dos au point bas de la rotation, puis ramenez-le devant.","goodFor":"Enroulements du corps et passages spectaculaires.","props":["bâton"]},"staff-isolation":{"name":"Isolation de staff","description":"Tiens le staff près d'une extrémité et fais tourner ta main autour du centre du staff, pour que le centre semble rester fixe dans l'air pendant que le staff tourne autour de lui.","goodFor":"Travail d'illusion et trajectoires de main précises.","props":["bâton"]},"staff-antispin-flower":{"name":"Antispin quatre pétales","description":"Fais tourner ta main dans un sens pendant que le staff tourne dans l'autre sens trois fois plus vite, pour que le staff dessine une fleur à quatre pétales.","goodFor":"La fleur VTG signature ; contrôle profond du timing.","props":["bâton"]},"staff-neck-roll":{"name":"Roulé de cou","description":"Lâche le staff sur le haut de tes épaules et laisse-le rouler sur la nuque jusqu'à l'autre main. Commence doucement avec un staff rembourré.","goodFor":"Contact staff : le staff se déplace sur le corps sans les mains.","avoidIf":["Douleur à la nuque."],"props":["bâton"]},"staff-reverse-wheel":{"name":"Roue inversée","description":"Le wheel spin dans l'autre sens : le bout avant du staff monte et repasse par-dessus. Les deux mains restent au milieu et le font rouler, exactement comme dans le spin avant.","goodFor":"Équilibrer les deux directions de spin pour que chaque mouvement suivant marche dans un sens comme dans l'autre.","alignmentCues":["La même roue à plat à côté de toi, seul le sens change.","Guide avec les phalanges qui roulent vers l'arrière."],"props":["bâton"],"commonMistakes":["Le plan qui dérive en travers de ton corps.","Repasser en sens avant sans s'en rendre compte."]},"staff-reverse-front-spin":{"name":"Front spin inversé","description":"Un front spin à deux mains qui tourne dans le sens inverse. Le bout du haut tombe vers ta droite au lieu de ta gauche.","goodFor":"Les deux sens du front spin avant les passes et les weaves.","alignmentCues":["Garde le staff bien à plat, face à la poitrine.","Les mains se croisent de la même façon, juste en sens inverse."],"props":["bâton"],"commonMistakes":["Les bouts qui basculent vers toi.","Perdre le rythme au changement de main."]},"staff-one-hand-wheel":{"name":"Roue à une main","description":"Fais tourner le staff à côté de toi dans le plan de la roue avec une seule main, en le roulant sur le dos de la main et entre les doigts.","goodFor":"Le contrôle à une main le long du corps : la base des isolations en roue et du double staff.","alignmentCues":["Le staff passe juste à l'extérieur de la hanche.","Le coude reste près des côtes."],"props":["bâton"],"commonMistakes":["Le bout qui accroche la jambe.","Le poignet qui se bloque."]},"staff-wheel-pass":{"name":"Passage de roue","description":"Un wheel spin qui change de main à chaque demi-tour. Chaque main prend le staff quand il est à l'horizontale, l'accompagne sur un demi-tour, puis le transmet.","goodFor":"Des changements de main fluides le long du corps.","alignmentCues":["Attrape à l'horizontale.","La main libre attend tout près."],"props":["bâton"],"commonMistakes":["Attraper avant que le staff soit à l'horizontale.","Le plan qui dérive à chaque passage."]},"staff-two-hand-helicopter":{"name":"Hélicoptère à deux mains","description":"Le staff tourne à plat au-dessus de ta tête, les deux mains dessus, une main passant par-dessus l'autre comme un rotor.","goodFor":"Une première approche tout en douceur du plan au sol.","alignmentCues":["Bras souples, staff juste au-dessus de la tête.","Les mains se croisent devant le visage."],"props":["bâton"],"commonMistakes":["Le staff qui penche vers l'avant.","Épaules crispées."]},"staff-overhead-pass":{"name":"Passe au-dessus de la tête","description":"L'hélicoptère se passe de main en main au-dessus de la tête, chaque main le portant sur un demi-tour.","goodFor":"Changements de main dans le plan du sol.","alignmentCues":["Passe quand le bâton pointe vers l'avant et vers l'arrière.","Garde les coudes souples."],"props":["bâton"],"commonMistakes":["Le bâton tombe derrière la tête.","Saisie trop tôt."]},"staff-one-hand-reverse":{"name":"Reverse Spin à une main","description":"Un spin avant à une main qui tourne dans l'autre sens, en roulant d'abord côté pouce.","goodFor":"Contrôle à une main dans les deux sens.","alignmentCues":["Même plan, même vitesse, en sens inverse.","Les doigts se relâchent pendant que le bâton roule."],"props":["bâton"],"commonMistakes":["Poignet crispé.","Le spin ralentit sur une moitié."]},"staff-reverse-helicopter":{"name":"Hélicoptère inversé","description":"L'hélicoptère à une main qui tourne dans l'autre sens au-dessus de la tête.","goodFor":"Les deux sens au-dessus de la tête.","alignmentCues":["Le bâton bien à plat.","La main reste au-dessus du front."],"props":["bâton"],"commonMistakes":["Inclinaison vers l'avant.","Bras complètement tendu."]},"staff-extension":{"name":"Prolongement","description":"Tiens le bâton près d'une extrémité et laisse-le balayer un grand cercle autour de ta main, qui ne bouge presque pas. Le bout libre dessine un grand anneau devant toi.","goodFor":"De grandes formes et le roulement de poignet nécessaires pour les isolations.","alignmentCues":["La main est le moyeu du cercle.","Roule le poignet, ne balance pas le bras."],"props":["bâton"],"commonMistakes":["Balancement depuis l'épaule.","Le cercle s'aplatit en ovale."]},"staff-wheel-extension":{"name":"Extension en roue","description":"Une extension le long du corps : le bâton balaie une grande roue autour de la main, à hauteur de hanche.","goodFor":"Grands cercles en plan roue.","alignmentCues":["Garde le cercle à l'extérieur de la jambe.","Le poignet tourne, le bras reste tranquille."],"props":["bâton"],"commonMistakes":["Le bâton accroche le pied.","Le corps penche à l'opposé du staff."]},"staff-floor-extension":{"name":"Extension au-dessus de la tête","description":"Une extension à plat au-dessus de la tête : le staff balaie l'espace autour de la main levée comme une longue pale de rotor.","goodFor":"Allonge au-dessus de la tête et une forme spectaculaire à l'horizontale.","alignmentCues":["Main au-dessus de la tête.","La lame reste bien horizontale."],"props":["bâton"],"commonMistakes":["Le staff plonge vers l'arrière.","Le bras dérive vers l'avant."]},"staff-wheel-isolation":{"name":"Isolation en plan de roue","description":"L'isolation le long du corps : le centre du staff reste fixe pendant que la main tourne autour.","goodFor":"Contrôle de l'isolation dans un second plan.","alignmentCues":["Choisis un point près de ta hanche comme centre.","La main décrit un petit cercle."],"props":["bâton"],"commonMistakes":["Le centre se balade.","Le plan s'incline."]},"staff-floor-isolation":{"name":"Isolation au-dessus de la tête","description":"Une isolation à plat au-dessus de la tête : le staff pivote sur un point fixe pendant que la main tourne autour.","goodFor":"Isolations au-dessus de la tête.","alignmentCues":["Un point fixe au-dessus de toi.","Petit cercle avec la main."],"props":["bâton"],"commonMistakes":["Le centre dérive.","Le cercle de la main s'agrandit."]},"staff-isolation-pass":{"name":"Passe d'isolation","description":"Une isolation passée d'une main à l'autre à chaque demi-tour : le point fixe reste immobile pendant que les mains se relaient.","goodFor":"Contrôle de l'isolation à deux mains.","alignmentCues":["Passe en bas du cercle.","Garde le centre fixe pendant la passe."],"props":["bâton"],"commonMistakes":["Le centre saute au moment de la passe.","Les mains se percutent."]},"staff-antispin-3":{"name":"Antispin à trois pétales","description":"La main tourne dans un sens tandis que le staff tourne dans l'autre, dessinant une fleur à trois pétales.","goodFor":"La première fleur en antispin.","alignmentCues":["Cercle de la main lent et bien rond.","Le staff tourne en sens inverse."],"props":["bâton"],"commonMistakes":["Les pétales sont inégaux.","Le cercle de la main se referme."]},"staff-antispin-5":{"name":"Antispin à cinq pétales","description":"Une fleur antispin plus fine, à cinq pétales, la main tournant plus lentement à l'inverse de la rotation.","goodFor":"Timing antispin précis.","alignmentCues":["Compte les pétales.","La main bouge lentement."],"props":["bâton"],"commonMistakes":["Les pétales fusionnent.","La main se précipite."]},"staff-wheel-antispin":{"name":"Antispin en plan de roue","description":"Une fleur antispin tracée à côté du corps dans le plan de roue.","goodFor":"Des fleurs dans un second plan.","alignmentCues":["Plan vertical.","Pétales réguliers."],"props":["bâton"],"commonMistakes":["Le plan penche.","Les pétales dérivent vers l'avant."]},"staff-floor-antispin":{"name":"Antispin au-dessus de la tête","description":"Une fleur antispin tracée à plat au-dessus de la tête.","goodFor":"Des fleurs au-dessus de la tête.","alignmentCues":["Plan horizontal.","La main au-dessus de la tête."],"props":["bâton"],"commonMistakes":["Ça penche.","Pétales irréguliers."]},"staff-inspin-3":{"name":"Inspin à trois pétales","description":"La main tourne dans le même sens que la rotation, mais plus lentement, et le bâton trace trois pétales pointant vers l'intérieur.","goodFor":"La fleur la plus douce à apprendre.","alignmentCues":["La main et le bâton tournent dans le même sens.","Cercle de main ample et lent."],"props":["bâton"],"commonMistakes":["La main accélère pour suivre le bâton.","Pétales déséquilibrés."]},"staff-inspin-4":{"name":"Inspin à quatre pétales","description":"Une fleur inspin à quatre pétales vers l'intérieur.","goodFor":"Plus de contrôle en inspin.","alignmentCues":["Compte quatre pétales.","Main stable."],"props":["bâton"],"commonMistakes":["Les pétales fusionnent.","La main dérive."]},"staff-wheel-inspin":{"name":"Roue inspin","description":"Un inspin à trois pétales tracé à côté du corps.","goodFor":"Inspins dans le plan de roue.","alignmentCues":["Plan vertical.","Main lente."],"props":["bâton"],"commonMistakes":["Ça penche.","Ça accroche la jambe."]},"staff-reverse-figure-8":{"name":"Figure 8 inversée","description":"La figure 8 tournée dans l'autre sens : le staff monte devant et redescend derrière de chaque côté.","goodFor":"Les deux sens du weave.","alignmentCues":["Croisement devant le corps.","Chaque côté vertical."],"props":["bâton"],"commonMistakes":["Le plan s'affaisse au croisement.","Buste raide."]},"staff-front-weave":{"name":"Tresse avant","description":"Un spin devant qui glisse d'un côté du corps à l'autre à chaque tour, le buste suivant le mouvement.","goodFor":"Le spin traverse le corps.","alignmentCues":["Le buste suit le staff.","Le spin reste bien face à toi."],"props":["bâton"],"commonMistakes":["Les pieds tournent aussi.","Le plan penche au croisement."]},"staff-overhead-weave":{"name":"Tresse au-dessus de la tête","description":"Un helicopter à deux mains qui passe d'un côté de la tête à l'autre à chaque tour.","goodFor":"Weave dans le plan du sol.","alignmentCues":["Les lames restent au même niveau tout du long.","Le buste tourne avec le staff."],"props":["bâton"],"commonMistakes":["Le staff plonge d'un seul côté.","La tête gêne le mouvement."]},"staff-fountain":{"name":"Fontaine","description":"Un tressage en temps décalé dans le plan roue : les bouts jaillissent vers le haut et retombent alternativement de chaque côté, comme l'eau d'une fontaine.","goodFor":"Temps décalé à côté du corps.","alignmentCues":["Les bouts montent alternativement de chaque côté.","Garde le croisement rapide."],"props":["bâton"],"commonMistakes":["Retomber dans un simple huit.","Inclinaison du plan."]},"staff-reel":{"name":"Bobine","description":"Un huit qui change de main à chaque croisement, le staff déroulant d'un côté à l'autre.","goodFor":"Combiner weaves et passes.","alignmentCues":["Passe au croisement.","Chaque côté à la verticale."],"props":["bâton"],"commonMistakes":["Attraper trop tôt.","Buste raide."]},"staff-wall-wheel-hybrid":{"name":"Hybride Mur-Roue","description":"À chaque tour, la rotation alterne entre le plan frontal et le plan de roue à côté de toi, en changeant quand le staff est vertical.","goodFor":"Changer de plan sans s'arrêter.","alignmentCues":["Change quand le staff pointe droit vers le haut.","Le poignet pivote d'un quart de tour."],"props":["bâton"],"commonMistakes":["Changement à l'horizontale.","Perte de vitesse au changement."]},"staff-floor-wall-hybrid":{"name":"Hybride Mur-Sol","description":"La rotation alterne entre devant toi et au-dessus de ta tête, en changeant chaque fois que le staff est à l'horizontale.","goodFor":"Enchaîner spins frontaux et hélicoptères.","alignmentCues":["Change à l'horizontale.","Lève le bras en douceur."],"props":["bâton"],"commonMistakes":["Changement à la verticale.","Coude qui se bloque."]},"staff-floor-wheel-hybrid":{"name":"Hybride Sol-Roue","description":"Un hélicoptère qui descend en roue à côté de toi et remonte, à chaque tour.","goodFor":"Tous les changements de plan réunis.","alignmentCues":["Le bras monte et descend en douceur.","Des plans bien nets."],"props":["bâton"],"commonMistakes":["Plan intermédiaire brouillon.","Vitesse en baisse."]},"staff-under-leg-pass":{"name":"Passe sous la jambe","description":"Un passage qui plonge sous la jambe droite levée une passe sur deux.","goodFor":"Ajouter les jambes aux passes.","alignmentCues":["Lève le genou vers le staff.","Reste grand.","Revenez vers le haut lorsque la baguette dépasse la jambe."],"props":["bâton"],"commonMistakes":["Se pencher en avant.","Se hâter de passer sous la jambe.","Passer trop vite sous la jambe."]},"staff-reverse-behind-back":{"name":"Passage derrière le dos inversé","description":"Le passage derrière le dos parcourt le corps dans le sens opposé, la rotation tournant à l'envers.","goodFor":"Emmener le staff autour du corps dans les deux directions.","alignmentCues":["La main derrière attend bas.","Garde la rotation derrière le dos."],"props":["bâton"],"commonMistakes":["Perte du plan derrière le dos.","Stopper la rotation."]},"staff-fishtail":{"name":"cavité en V","description":"Le staff se balance d'avant en arrière sur la paume ouverte, comme un poisson qui bat de la queue, sans jamais tout à fait boucler un tour complet.","goodFor":"Contrôle main ouverte et changement de sens de rotation.","alignmentCues":["Pivot entre le pouce et les doigts.","De petits flicks de poignet inversent le balancé."],"props":["bâton"],"commonMistakes":["Serrer trop fort.","Des balancés qui deviennent trop grands."]},"staff-wheel-fishtail":{"name":"Queue de poisson de la roue","description":"Un fishtail le long du corps, dans le plan roue.","goodFor":"Des fishtails dans un second plan.","alignmentCues":["Plan vertical.","Main ouverte."],"props":["bâton"],"commonMistakes":["Incliner.","Serrer."]},"staff-steering-wheel":{"name":"Volant","description":"Tourne le staff de main en main avec les paumes à plat et ouvertes, comme si tu tournais un grand volant devant toi.","goodFor":"Mains détendues et contact paume ouverte.","alignmentCues":["Paumes à plat, doigts souples.","Main sur main en haut."],"props":["bâton"],"commonMistakes":["Saisir au lieu de guider.","Des coudes qui s'écartent."]},"staff-palm-spin":{"name":"Palm spin","description":"Équilibre le milieu du staff sur la paume à plat et levée, et laisse-le tourner comme une hélice.","goodFor":"Équilibre et toucher léger au-dessus de la tête.","alignmentCues":["Paume à plat et de niveau.","De petits cercles l'empêchent de s'arrêter."],"props":["bâton"],"commonMistakes":["Paume qui s'incline.","Pousser au lieu de guider."]},"staff-hand-roll":{"name":"Roulé sur la main","description":"Le bâton roule sur le dos de la main ouverte et autour du pouce, sans être agrippé.","goodFor":"Le premier vrai roulé de contact.","alignmentCues":["Main ouverte et souple.","Laisse le bâton faire le travail."],"props":["bâton"],"commonMistakes":["Fermer les doigts.","La main bouge trop."]},"staff-forearm-roll":{"name":"Roulé sur l'avant-bras","description":"Dépose la rotation sur l'avant-bras, laisse le bâton tourner dessus, puis reprends-le en rotation de main.","goodFor":"Faire passer une rotation sur le bras, puis la reprendre.","alignmentCues":["Avant-bras horizontal et immobile.","Ouvre la main à la réception."],"props":["bâton"],"commonMistakes":["L'avant-bras s'incline.","Saisir trop tôt."]},"staff-elbow-roll":{"name":"Roulé sur le coude","description":"La rotation passe dans le pli du coude, y tourne avec la main levée, puis revient dans la main.","goodFor":"Contrôle de contact avancé.","alignmentCues":["Avant-bras vertical.","Coude immobile."],"props":["bâton"],"commonMistakes":["Le coude tombe.","Le bâton glisse."]},"staff-shoulder-roll":{"name":"Roulé sur l'épaule","description":"Une rotation en roue déposée sur le dessus de l'épaule, où elle tourne à côté de la tête avant de retomber dans la main.","goodFor":"Les roulés de contact sur le haut du corps.","alignmentCues":["Épaule légèrement levée.","La tête s'incline à l'opposé."],"props":["bâton"],"commonMistakes":["La tête gêne le mouvement.","L'épaule tombe."]},"staff-chest-roll":{"name":"Roulé sur la poitrine","description":"Le bâton roule à l'horizontale sur la poitrine, d'une main à l'autre, puis revient.","goodFor":"Contact avec le corps sur le devant.","alignmentCues":["Poitrine relevée.","Le bâton reste à l'horizontale."],"props":["bâton"],"commonMistakes":["La poitrine s'affaisse.","Le bâton penche."]},"staff-angel-roll":{"name":"Rouleau d'ange","description":"Les bras bien écartés, le bâton roule sur l'arrière des épaules puis le long des deux bras, d'une main à l'autre.","goodFor":"Un roulé de contact spectaculaire.","alignmentCues":["Bras à l'horizontale, paumes vers le haut.","Omoplates serrées."],"props":["bâton"],"commonMistakes":["Les bras tombent.","Tête en avant."]},"staff-toss":{"name":"Lancer de bâton","description":"Lâche le bâton en rotation à une main, à l'horizontale, laisse-le faire un tour en l'air, puis rattrape-le dans la même rotation.","goodFor":"Lâcher et rattraper un bâton en rotation.","alignmentCues":["Lâche à l'horizontale.","Rattrape au milieu."],"props":["bâton"],"commonMistakes":["Lancer vers l'avant.","Rattraper le bout."]},"staff-double-toss":{"name":"Double lancer","description":"Un lancer plus haut, avec deux tours complets avant la réception.","goodFor":"Contrôle de la hauteur et de la rotation en l'air.","alignmentCues":["Plus de hauteur, même rotation.","Les yeux sur le milieu."],"props":["bâton"],"commonMistakes":["Trop de rotation.","Dérive vers l'avant."]},"staff-flat-toss":{"name":"Lancer à plat","description":"Lance le bâton bien verticalement, comme un hélicoptère, pour qu'il tourne à plat en l'air, puis rattrape-le au-dessus de la tête.","goodFor":"Lancer dans le plan du sol.","alignmentCues":["Lâcher à plat.","Rattrape au-dessus de la tête."],"props":["bâton"],"commonMistakes":["Le bâton penche au lâcher.","Lancer vers l'arrière."]},"double-staff-same-time":{"name":"Double bâton en même temps","description":"Un bâton court dans chaque main, les deux tournant devant toi dans le même sens et en phase.","goodFor":"Le premier enchaînement en double bâton.","alignmentCues":["Bâtons côte à côte, l'un légèrement en avant.","Les deux mains à la même vitesse."],"props":["deux bâtons courts"],"commonMistakes":["Les bâtons s'entrechoquent.","Une main prend du retard."]},"double-staff-split-time":{"name":"Double bâton en temps décalé","description":"Les deux bâtons tournent dans le même sens, mais l'un a un quart de tour de retard : l'un est à la verticale quand l'autre est à l'horizontale.","goodFor":"Timing indépendant entre les deux mains.","alignmentCues":["Un à la verticale, un à l'horizontale.","Décalage constant."],"props":["deux bâtons courts"],"commonMistakes":["Ça retombe en synchro.","Les bâtons se percutent."]},"double-staff-wheels":{"name":"Double bâton en roues","description":"Une roue de chaque côté du corps, les deux tournant vers l'avant en même temps.","goodFor":"Les deux bâtons le long du corps.","alignmentCues":["Chaque roue à l'extérieur de sa hanche.","Même vitesse."],"props":["deux bâtons courts"],"commonMistakes":["Les roues s'inclinent vers l'intérieur.","Les mains s'écartent."]},"double-staff-split-wheels":{"name":"Double bâton en roues décalées","description":"Des roues de chaque côté, décalées d'un quart de tour, comme des jambes qui marchent.","goodFor":"Temps décalés le long du corps.","alignmentCues":["Un vers le haut, un à l'horizontale.","Décalage constant."],"props":["deux bâtons courts"],"commonMistakes":["Ça se synchronise.","Ça penche."]},"double-staff-windmill":{"name":"Double bâton en moulinet","description":"Des roues de chaque côté, tournant en sens opposés, comme un moulin vu de profil.","goodFor":"Sens opposés dans les deux mains.","alignmentCues":["Un vers l'avant, un vers l'arrière.","Vitesse égale."],"props":["deux bâtons courts"],"commonMistakes":["Les deux dérivent dans la même direction.","Vitesse inégale."]},"double-staff-reverse":{"name":"Double bâton inversé","description":"Spins avant en temps décalé, les deux bâtons tournant en sens inverse.","goodFor":"Les deux directions avec deux bâtons.","alignmentCues":["Garde le décalage.","Même plan pour les deux."],"props":["deux bâtons courts"],"commonMistakes":["Les bâtons se percutent.","Tu perds le décalage."]},"double-staff-helicopters":{"name":"Hélicoptères en double bâton","description":"Un hélicoptère au-dessus de chaque épaule, les deux tournant en phase.","goodFor":"Double bâton au-dessus de la tête.","alignmentCues":["Extrémités au même niveau.","Bras souples."],"props":["deux bâtons courts"],"commonMistakes":["Extrémités qui se touchent.","Tes bras fatiguent et retombent."]},"double-staff-isolations":{"name":"Isolations en double bâton","description":"Une isolation dans chaque main en même temps, les deux centres fixes côte à côte.","goodFor":"Deux isolations en même temps.","alignmentCues":["Deux points fixes.","Les mains tournent ensemble."],"props":["deux bâtons courts"],"commonMistakes":["Tes centres dérivent.","Une main prend du retard."]},"hoop-waist":{"name":"Hoop à la taille","description":"Tiens-toi avec un pied légèrement devant l'autre. Place le cerceau contre ton bas du dos, lance-le autour de ta taille et pousse le ventre vers l'avant puis vers l'arrière (pas en cercles) chaque fois que le cerceau passe devant toi.","goodFor":"La première compétence au hoop ; développe le rythme du centre.","modifications":["Utilise un cerceau plus grand et plus lourd : il tourne plus lentement."],"alignmentCues":["Bascule d'avant en arrière, pas en cercles.","Pousse sur le cerceau quand il passe sur ton ventre."],"props":["cerceau"],"commonMistakes":["Faire tourner les hanches comme une danseuse de hula.","Un cerceau trop petit ou trop léger."]},"hoop-hand-spin":{"name":"Spin de main","description":"Tiens le cerceau devant toi avec la main à l'intérieur, pouce vers le haut. Pousse-le pour qu'il tourne autour de la toile de ta main, en gardant le cerceau à plat devant toi.","goodFor":"Base du hoop off-body.","props":["cerceau"]},"hoop-chest":{"name":"Hoop à la poitrine","description":"Lève les bras au-dessus de la tête et fais tourner le cerceau autour de la poitrine, en balançant la cage thoracique d'avant en arrière tout en gardant les hanches calmes.","goodFor":"Isolation de la cage thoracique et contrôle du haut du corps.","props":["cerceau"]},"hoop-lasso":{"name":"Lasso","description":"Tiens le cerceau au-dessus de la tête et fais-le tourner à plat comme un lasso, le cerceau tournant autour de ta main.","goodFor":"Contrôle du plan au sol au-dessus de la tête.","props":["cerceau"]},"hoop-wedgie":{"name":"slip coincé entre les fesses","description":"Fais tourner le cerceau dans le plan du mur et attrape-le dans le creux entre le pouce et les doigts, en le laissant rouler et basculer là avant de le relancer.","goodFor":"Contrôle de la prise et transition fluide.","props":["cerceau"]},"hoop-knees":{"name":"Hoop aux genoux","description":"Pieds joints, garde le cerceau en rotation autour de tes genoux en poussant les genoux d'avant en arrière.","goodFor":"Hooping du bas du corps et escalator.","props":["cerceau"]},"hoop-pass":{"name":"Passe main à main","description":"Fais tourner le hoop devant toi et passe-le d'une main à l'autre à chaque révolution, en gardant le plan stable.","goodFor":"Enchaîne les tricks hors du corps des deux côtés.","props":["cerceau"]},"hoop-isolation":{"name":"Isolation au hoop","description":"Déplace ta main autour du hoop pour que son centre reste fixe dans l'air devant toi pendant que le hoop tourne autour de ce point.","goodFor":"L'illusion classique au hoop.","props":["cerceau"]},"hoop-escalator":{"name":"Escalator","description":"Garde le hoop en rotation en le faisant descendre de la taille aux genoux puis remonter à la poitrine, une zone du corps par mesure.","goodFor":"Relie toutes les zones du body hooping en un seul flow.","props":["cerceau"]},"hoop-neck":{"name":"Hooping au cou","description":"Incline légèrement la tête et laisse un hoop léger tourner autour du cou, guidé par de petites impulsions de la tête et des épaules.","goodFor":"Un move de show qui travaille des impulsions petites et précises.","avoidIf":["Douleur au cou."],"props":["cerceau"]},"hoop-reverse-waist":{"name":"Hooping à la taille en reverse","description":"Le hooping à la taille dans l'autre sens. Change le pied qui est devant, lance le hoop dans la nouvelle direction et garde la même pulsation avant-arrière.","goodFor":"Équilibrer les deux directions pour que tous les tricks suivants marchent dans un sens comme dans l'autre.","alignmentCues":["Inverse ton pied avant.","Même pulsation, nouvelle direction."],"props":["cerceau"],"commonMistakes":["Un cercle autour des hanches.","Tu abandonnes trop vite ton côté faible."]},"hoop-hips":{"name":"Hooping sur les hanches","description":"Laisse le hoop descendre de la taille jusqu'aux os des hanches et garde-le en place avec une pulsation plus basse et plus petite venue du bassin.","goodFor":"Contrôle sous la taille et un pas de plus vers les genoux.","alignmentCues":["Genoux souples.","La pulsation vient du bassin, pas du ventre."],"props":["cerceau"],"commonMistakes":["Tu le laisses glisser vers le bas.","Pulsation trop ample."]},"hoop-thighs":{"name":"Hooping sur les cuisses","description":"Les pieds rapprochés, garde le hoop en rotation autour du haut des cuisses grâce à un petit et rapide rebond des genoux.","goodFor":"Le rythme des jambes et le lien entre hanches et genoux.","alignmentCues":["Pieds joints.","Petits rebonds rapides."],"props":["cerceau"],"commonMistakes":["Pieds écartés.","Rebonds trop lents."]},"hoop-reverse-chest":{"name":"Chest hooping inversé","description":"Chest hooping dans l'autre sens, bras levés et côtes qui entraînent le hoop.","goodFor":"Les deux sens, bien haut sur le corps.","alignmentCues":["Bras levés et dégagés.","La cage thoracique bascule d'avant en arrière."],"props":["cerceau"],"commonMistakes":["Bras qui retombent dans le hoop.","Hanches qui font le travail."]},"hoop-shoulder":{"name":"Hooping sur les épaules","description":"Le hoop tourne autour des épaules et du haut de la poitrine, bras levés au-dessus de la tête.","goodFor":"Hooping dans le haut du corps.","alignmentCues":["Bras tendus vers le haut.","Petites pulsations d'épaules."],"props":["cerceau"],"commonMistakes":["Bras qui se plient vers l'intérieur.","Hoop qui glisse vers la poitrine."]},"hoop-arm":{"name":"Hooping sur le bras","description":"Lève un bras bien droit et fais tourner le hoop autour de l'avant-bras, la main dessinant un petit cercle pour entretenir la rotation.","goodFor":"Hooping sur les membres et sensation de lasso bras levé.","alignmentCues":["Bras tendu, main au-dessus de la tête.","Petit cercle avec la main."],"props":["cerceau"],"commonMistakes":["Tout le bras qui tourne.","Bras qui part vers l'avant."]},"hoop-elbow":{"name":"Hooping au coude","description":"Le bras est écarté sur le côté, plié au coude, et le hoop tourne autour de l'articulation du coude.","goodFor":"Contrôle des membres, loin du corps.","alignmentCues":["Haut du bras à l'horizontale.","Petits cercles avec le coude."],"props":["cerceau"],"commonMistakes":["Coude qui baisse.","Hoop qui glisse vers l'épaule."]},"hoop-foot":{"name":"Hooping à la jambe","description":"Lève une jambe et fais tourner le hoop autour du tibia, le pied dessinant de petits cercles pour entretenir la rotation.","goodFor":"Équilibre et contrôle de la jambe.","alignmentCues":["Jambe d'appui solide.","Petits cercles avec le pied."],"props":["cerceau"],"commonMistakes":["Perte d'équilibre.","Cercles trop grands."]},"hoop-full-escalator":{"name":"Escalator complet","description":"Emmène le hoop des genoux jusqu'aux épaules, puis redescends-le sans t'arrêter.","goodFor":"Toute l'amplitude du corps en un seul mouvement continu.","alignmentCues":["Accélère le pulse en montant.","Les bras montent avec le hoop."],"props":["cerceau"],"commonMistakes":["Perte au passage taille-poitrine.","Les bras gênent."]},"hoop-vortex":{"name":"Vortex","description":"Fais un lasso au-dessus de la tête, laisse le hoop descendre autour des épaules et de la poitrine, puis rattrape-le à la taille en une seule descente en spirale.","goodFor":"Relier le hooping off-body et on-body.","alignmentCues":["Garde la vitesse du lasso en lâchant.","Commence à pulser avant qu'il arrive."],"props":["cerceau"],"commonMistakes":["Lâcher trop lentement.","Le hoop penche en descendant."]},"hoop-duck-out":{"name":"Duck Out","description":"Fais remonter le hoop de la taille en passant par la poitrine, saisis-le au-dessus de la tête en lasso, puis ramène-le en spin sur la main devant toi.","goodFor":"Sortir le hoop du corps proprement.","alignmentCues":["Monte avec les côtes.","Saisis-le au-dessus de la tête sur le beat."],"props":["cerceau"],"commonMistakes":["Saisir trop tôt.","Perte de vitesse."]},"hoop-drop-in":{"name":"Déposer dans","description":"Depuis un lasso au-dessus de la tête, lâche prise et rattrape le hoop sur la poitrine, puis laisse-le descendre jusqu'à la taille.","goodFor":"Le moyen le plus simple de repasser du off-body au corps.","alignmentCues":["Bras levés pendant qu'il descend.","Rattrape avec un pulse."],"props":["cerceau"],"commonMistakes":["Descente trop rapide.","Les bras se rabattent."]},"hoop-chest-lift":{"name":"Crunch","description":"Monte le hoop de la taille à la poitrine et redescends-le avec un pulse plus appuyé.","goodFor":"Passer d'une zone du corps à l'autre.","alignmentCues":["Pulse plus rapide pour monter.","Lève les bras tôt."],"props":["cerce"],"commonMistakes":["Perte de contrôle pendant le changement.","Les bras baissent."]},"hoop-knee-drop":{"name":"Descente du genou","description":"Laisse le cerce descendre de la taille aux genoux, garde-le là, puis laisse-le remonter en rebond jusqu'à la taille.","goodFor":"Transitions du bas du corps.","alignmentCues":["Pieds joints pour les genoux.","Rebond plus ample pour remonter."],"props":["cerce"],"commonMistakes":["Pieds écartés.","Perte de contrôle à la remontée."]},"hoop-side-spin":{"name":"Rotation latérale","description":"Un spin à la main le long du corps, dans le plan roue : le cerce tourne comme une roue à côté de toi.","goodFor":"Le plan roue du cerce.","alignmentCues":["Cerce bien à plat à côté de toi.","Main à hauteur de hanche."],"props":["cerce"],"commonMistakes":["Le cerce touche la jambe.","Le plan penche."]},"hoop-reverse-hand-spin":{"name":"Tour de main inversé","description":"Le spin à la main qui tourne dans l'autre sens devant toi.","goodFor":"Les deux sens, hors du corps.","alignmentCues":["Même plan, autre sens.","Le pouce reste en haut."],"props":["cerce"],"commonMistakes":["Le cerce vacille.","La rotation ralentit."]},"hoop-reverse-lasso":{"name":"Lasso inversé","description":"Le lasso au-dessus de la tête qui tourne dans l'autre sens.","goodFor":"Les deux sens du lasso.","alignmentCues":["Cerce bien à l'horizontale.","Petit cercle de la main."],"props":["cerce"],"commonMistakes":["Le cerce penche.","Grands cercles de bras."]},"hoop-palm-spin":{"name":"Tour de paume en hauteur","description":"Un spin à la main levé au-dessus de la tête sur la paume ouverte, le cerce tournant de face au-dessus de toi.","goodFor":"Des spins hors du corps, portés en hauteur.","alignmentCues":["Bras bien tendu.","Paume ouverte."],"props":["cerceau"],"commonMistakes":["Le cerceau dérive vers l’arrière.","Le bras plie."]},"hoop-coin-flip":{"name":"Pile ou face","description":"Équilibre le cerceau à la verticale sur le bout des doigts, puis, d’un petit coup sec, fais-le tourner autour de son axe vertical, comme une pièce qu’on lance.","goodFor":"Un contrôle précis des doigts et un nouvel axe.","alignmentCues":["Cerceau bien vertical.","Coup sec, puis laisse-le tourner."],"props":["cerceau"],"commonMistakes":["Le cerceau penche.","Tu serres trop fort."]},"hoop-cateye":{"name":"Œil de chat","description":"Tiens le cerceau par le côté de l’anneau et fais-le basculer autour de son axe vertical : de face, il se resserre puis s’élargit comme un œil de chat.","goodFor":"Des mouvements de bascule et une illusion saisissante.","alignmentCues":["Main immobile sur l’anneau.","Bascule régulièrement."],"props":["cerceau"],"commonMistakes":["La main bouge.","Bascule irrégulière."]},"hoop-weave":{"name":"Weave","description":"Une rotation à la main qui glisse d’un côté du corps à l’autre, le plan tournant avec le buste.","goodFor":"Faire passer la rotation d’un côté à l’autre du corps.","alignmentCues":["Le buste tourne avec.","Garde la rotation."],"props":["cerceau"],"commonMistakes":["Tu t’arrêtes au milieu.","Le plan penche."]},"hoop-halo":{"name":"Auréole","description":"Le cerceau orbite à plat autour de la tête, la main levée suivant l’anneau au-dessus de toi.","goodFor":"Orbites à hauteur de tête.","alignmentCues":["Cerceau bien à plat autour de la tête.","Main proche de la tête."],"props":["cerceau"],"commonMistakes":["Le cerceau plonge devant toi.","Tu baisses la tête."]},"hoop-toss":{"name":"Lancer de hoop","description":"Lance le cerceau droit vers le haut, toujours en train de tourner, et rattrape-le dans la rotation.","goodFor":"Lâcher et rattraper un cerceau en pleine rotation.","alignmentCues":["Lance bien droit vers le haut.","Rattrape là où tu as lancé."],"props":["cerceau"],"commonMistakes":["Lancer vers l'avant.","Attraper le bord trop tard."]},"hoop-boomerang":{"name":"boomerang","description":"Lance le hoop vers le bas et loin de toi, avec du backspin, pour qu'il roule au sol et revienne vers toi.","goodFor":"Du backspin et un trick au sol amusant.","alignmentCues":["Ramène le poignet d'un coup sec.","Lance bas et vers l'avant."],"props":["cerceau"],"commonMistakes":["Pas assez de backspin.","Lancer trop haut."]},"hoop-jump-through":{"name":"Sauter à travers","description":"Tiens le hoop à deux mains comme une corde à sauter : balance-le au-dessus de la tête et saute à travers quand il passe sous tes pieds.","goodFor":"Du rythme, de la coordination et un bon coup de cardio.","alignmentCues":["Petit saut, genoux souples.","Balance depuis les poignets."],"props":["cerceau"],"commonMistakes":["Sauter trop tôt.","De trop grands mouvements de bras."]},"hoop-behind-back-pass":{"name":"Passe dans le dos","description":"Un spin sur la main passé dans le dos d'une main à l'autre, puis ramené devant.","goodFor":"Faire passer le hoop tout autour du corps.","alignmentCues":["Garde le spin derrière toi.","La main libre se tend vers l'arrière."],"props":["cerceau"],"commonMistakes":["Le hoop cale dans le dos.","Le hoop touche le dos."]},"hoop-under-leg-pass":{"name":"Passe sous la jambe","description":"Une passe de main à main qui plonge sous la jambe droite levée.","goodFor":"Ajouter les jambes aux passes.","alignmentCues":["Lève le genou jusqu'au hoop.","Reste bien droit.","Relevez-vous à nouveau lorsque l'anneau sort de l'autre côté."],"props":["cerceau"],"commonMistakes":["Se pencher en avant.","Précipitation.","Se précipiter."]},"hoop-corkscrew":{"name":"Tire-bouchon","description":"Un lasso qui descend en spirale jusqu'aux hanches puis remonte, le hoop dessinant un corkscrew.","goodFor":"Emmener le lasso à travers les niveaux.","alignmentCues":["Plie les genoux pour descendre.","Garde le hoop bien horizontal."],"props":["cerceau"],"commonMistakes":["Le hoop s'incline vers le bas.","Le spin ralentit."]},"hoop-barrel-roll":{"name":"Tonneau","description":"Un spin à la main qui fait le tour du corps tous les quatre temps, le hoop roulant autour de toi.","goodFor":"Flow off-body en cercle complet.","alignmentCues":["Tourne avec le hoop.","Garde le spin en continu."],"props":["cerceau"],"commonMistakes":["Le hoop accroche le corps.","Le spin cale dans le dos."]},"hoop-chest-roll":{"name":"Roulé de poitrine","description":"Lâche un spin à la main sur la poitrine et laisse-le rouler jusqu'à l'autre main.","goodFor":"Le premier roll de hoop.","alignmentCues":["Poitrine relevée.","Bras ouverts pendant qu'il roule."],"props":["cerce"],"commonMistakes":["La poitrine s'affaisse.","La main attrape trop tôt."]},"hoop-back-roll":{"name":"Roulé de dos","description":"Le hoop roule sur l'arrière des épaules d'une main à l'autre.","goodFor":"Roule derrière le corps.","alignmentCues":["Omoplates serrées.","Tête légèrement en avant."],"props":["cerce"],"commonMistakes":["Le dos s'arrondit.","Le hoop tombe."]},"hoop-isopop":{"name":"Iso Pop","description":"Une isolation qui cale et fait poper le hoop sur le côté tous les deux temps avant de repartir.","goodFor":"Des accents et des stalls dans les isolations.","alignmentCues":["Pop sur le temps.","L'isolation reste propre entre les pops."],"props":["cerce"],"commonMistakes":["Les pops sont trop amples.","Le centre se balade."]},"hoop-wheel-isolation":{"name":"Isolation latérale","description":"Une isolation à côté du corps, dans le plan de roue.","goodFor":"Des isolations dans un second plan.","alignmentCues":["Un centre fixe à côté de toi.","La main tourne autour."],"props":["cerce"],"commonMistakes":["Le centre dérive.","Ça penche."]},"hoop-floor-isolation":{"name":"Isolation à plat","description":"Une isolation avec le cerce à plat, le centre fixe pendant que la main tourne autour.","goodFor":"Isolations dans le plan du sol.","alignmentCues":["Cerce à plat.","Centre fixe."],"props":["cerce"],"commonMistakes":["Ça penche.","Le centre dérive."]},"doubles-hand-spins":{"name":"Doubles spins à la main","description":"Une cerce dans chaque main, les deux qui tournent devant toi en miroir.","goodFor":"Le premier move en doubles.","alignmentCues":["Cerces côte à côte.","Calque la vitesse."],"props":["deux cerces"],"commonMistakes":["Les cerces se percutent.","Une qui ralentit."]},"doubles-offset-spins":{"name":"Doubles spins décalés","description":"Des doubles spins à la main tournant dans le même sens, décalés d'un demi-tour.","goodFor":"Timing indépendant entre les mains.","alignmentCues":["Une en haut, l'autre en bas.","Dans le même sens."],"props":["deux cerces"],"commonMistakes":["Ça se synchronise.","Ça se percute."]},"doubles-side-spins":{"name":"Doubles spins de côté","description":"Une cerce en spin à côté de chaque hanche, dans le plan de roue.","goodFor":"Des doubles dans le plan de roue.","alignmentCues":["Cerces verticales.","Éloignées des jambes."],"props":["deux cerces"],"commonMistakes":["Ça touche les jambes.","Ça penche."]},"doubles-floor-spins":{"name":"Doubles lassos","description":"Un lasso au-dessus de la tête dans chaque main, en miroir.","goodFor":"Des doubles au-dessus de la tête.","alignmentCues":["Les deux à plat.","Petits cercles de main."],"props":["deux cerceaux"],"commonMistakes":["Cerceaux qui se touchent.","Les bras fatiguent."]},"doubles-wedgies":{"name":"Wedgies doubles","description":"Un wedgie dans chaque main, les deux cerceaux se balançant dans le creux des pouces.","goodFor":"Mouvements de balancement en doubles.","alignmentCues":["Pouces vers l'extérieur.","Balancements réguliers."],"props":["deux cerceaux"],"commonMistakes":["Cerceaux qui s'entrechoquent.","Timing irrégulier."]},"doubles-coin-flips":{"name":"Coin flips doubles","description":"Un coin flip sur chaque main en même temps.","goodFor":"Contrôle des doigts en doubles.","alignmentCues":["Les deux verticaux.","Flicker ensemble."],"props":["deux cerceaux"],"commonMistakes":["Ça penche.","Ça s'entrechoque."]},"doubles-isolations":{"name":"Isolations doubles","description":"Une isolation dans chaque main, les deux centres fixes côte à côte.","goodFor":"Deux isolations en même temps.","alignmentCues":["Deux centres immobiles.","Les mains tournent ensemble."],"props":["deux cerceaux"],"commonMistakes":["Les centres dérivent.","Cerceaux qui s'entrechoquent."]},"doubles-toss":{"name":"Toss doubles","description":"Lance les deux cerceaux en rotation vers le haut en même temps, puis rattrape-les pour reprendre les spins en doubles.","goodFor":"Releases en doubles.","alignmentCues":["Lance droit vers le haut, ensemble.","Rattrape là où tu as lancé."],"props":["deux cerceaux"],"commonMistakes":["Lancers irréguliers.","Dérive vers l'avant."]},"doubles-waist-and-hand":{"name":"Cerceau à la taille et spin à la main","description":"Garde un cerceau en rotation à la taille tout en faisant tourner un second dans la main gauche.","goodFor":"Attention partagée entre le corps et la main.","alignmentCues":["Les hanches gardent leur pulsation.","Spin à la main devant le hoop au corps."],"props":["deux hoops"],"commonMistakes":["Le hoop au corps ralentit.","Le hoop à la main touche le hoop au corps."]},"doubles-chest-and-hand":{"name":"Chest hoop et spin à la main","description":"Chest hoop avec un bras levé pendant que l'autre main fait tourner un deuxième hoop.","goodFor":"Hooping au corps en hauteur avec un trick à la main.","alignmentCues":["Un bras levé.","Les côtes pilotent le hoop au corps."],"props":["deux hoops"],"commonMistakes":["Le bras descend dans le chest hoop.","On perd le pulse."]},"doubles-waist-and-lasso":{"name":"Hoop à la taille et lasso","description":"Hoop à la taille en bas, lasso au-dessus de la tête : deux hoops à deux niveaux en même temps.","goodFor":"Deux niveaux de hooping en même temps.","alignmentCues":["Les hanches pulsent, la main tourne en cercles.","Lasso au-dessus de la tête."],"props":["deux hoops"],"commonMistakes":["Le hoop au corps descend.","Le lasso s'incline."]},"poi-one-hand-spin":{"name":"Spin avant à une poi","description":"Une poi tourne devant toi comme l'aiguille d'une horloge, la tête frôlant ton côté à chaque passage. Le poignet fait un petit cercle régulier et la corde reste tendue.","goodFor":"Sens la corde qui tire et le rythme d'un tour par temps.","alignmentCues":["Petits cercles au poignet, grands cercles de poi.","Garde le cercle bien plat devant toi, comme une vitre."],"props":["une poi"],"commonMistakes":["Balancer depuis l'épaule.","Laisser le cercle pencher vers toi."]},"poi-wall-spin":{"name":"Wall Spin avant","description":"Les deux poi tournent en avant ensemble devant toi, une de chaque côté des épaules, côte à côte comme deux roues sur un même essieu. Le premier mouvement à deux poi.","goodFor":"Deux poi en phase entre elles et avec le rythme.","alignmentCues":["Les deux têtes arrivent en haut ensemble.","Mains à peu près à la largeur des épaules."],"props":["paire de poi"],"commonMistakes":["Une poi qui prend du retard sur l'autre.","Les cercles qui se chevauchent."]},"poi-reverse-wall-spin":{"name":"Wall Spin arrière","description":"Le wall spin dans l'autre sens : les têtes montent par l'extérieur et redescendent au milieu.","goodFor":"Les deux sens avant les weaves et les flowers.","alignmentCues":["Mêmes plans bien plats, seul le sens change.","Mène les cercles avec le dos du poignet."],"props":["paire de poi"],"commonMistakes":["Retomber dans le spin avant.","Les plans qui penchent vers l'avant."]},"poi-split-time":{"name":"Wall Spin en split time","description":"Les deux poi tournent dans le même sens, mais décalées d'un demi-tour : quand l'une est en haut, l'autre est en bas. Le timing sur lequel chaque weave se construit.","goodFor":"Un timing indépendant dans chaque main.","alignmentCues":["Haut, bas, haut, bas : les têtes alternent.","Compte le point haut de chaque poi sur le temps et sur le « et »."],"props":["paire de poi"],"commonMistakes":["Retomber en same time.","Des mains qui vont à des vitesses différentes."]},"poi-butterfly":{"name":"Papillon","description":"Mains rapprochées devant toi, les poi tournant en sens opposés pour se rejoindre en haut et en bas, comme les ailes d'un papillon.","goodFor":"Timing en sens opposés et mains rapprochées.","alignmentCues":["Les têtes s'effleurent en haut et en bas.","Poignets presque en contact."],"props":["paire de poi"],"commonMistakes":["Têtes qui se percutent quand les plans se croisent.","Mains qui s'écartent."]},"poi-reverse-butterfly":{"name":"Papillon inversé","description":"Le papillon avec les deux ailes qui tournent dans l'autre sens : les têtes montent ensemble au milieu et redescendent sur les côtés.","goodFor":"Équilibrer le papillon dans les deux sens.","alignmentCues":["Les têtes se rejoignent au milieu, en haut.","Mains aussi rapprochées que pour le papillon avant."],"props":["paire de poi"],"commonMistakes":["Têtes qui s'emmêlent en haut.","Une aile qui retombe."]},"poi-chase-the-sun":{"name":"Chassez le soleil","description":"Mains réunies devant, en timing décalé : les deux têtes se suivent sur un seul grand cercle, toujours à un demi-tour l'une de l'autre.","goodFor":"Timing décalé avec les mains rapprochées, idéal pour les weaves.","alignmentCues":["Une tête toujours opposée à l'autre.","Les mains bougent à l'unisson."],"props":["paire de poi"],"commonMistakes":["Têtes qui se rattrapent.","Mains qui se séparent."]},"poi-wheels":{"name":"Roues avant","description":"Les deux poi tournent à côté de vous comme les roues d'un vélo, le haut des cercles roulant vers l'avant.","goodFor":"Le plan des roues, le long du corps.","alignmentCues":["Les cercles restent parallèles à vos côtés.","Coudes souples et près du corps."],"props":["paire de poi"],"commonMistakes":["Poi qui accrochent les jambes.","Roues qui s'écartent vers l'extérieur."]},"poi-reverse-wheels":{"name":"Roues arrière","description":"Roues qui roulent en arrière à côté de vous : les têtes montent devant et retombent derrière.","goodFor":"Les deux sens dans le plan des roues.","alignmentCues":["Les mêmes roues, en sens inverse.","Épaules basses et détendues."],"props":["paire de poi"],"commonMistakes":["Roues qui dérivent derrière le corps.","Poignets qui se crispent."]},"poi-fountain":{"name":"Fontaine","description":"Roues en timing décalé : un poi monte pendant que l'autre descend, comme l'eau d'une fontaine à côté de vous.","goodFor":"Timing décalé dans le plan roue, la base du walking weave.","alignmentCues":["Un en haut, un en bas.","Garde un rythme régulier entre les deux mains."],"props":["paire de poi"],"commonMistakes":["Timing qui retombe au même temps.","Roues qui s'inclinent vers l'intérieur."]},"poi-opposite-wheels":{"name":"Roues opposées","description":"Une roue tourne vers l'avant pendant que l'autre tourne en arrière. Les têtes se croisent en haut et en bas.","goodFor":"Coordination : les mains tournent en sens opposés.","alignmentCues":["Les deux arrivent en haut en même temps.","Chaque main garde son propre sens."],"props":["paire de poi"],"commonMistakes":["Les deux mains qui passent dans le même sens.","Une roue qui rétrécit."]},"poi-overhead":{"name":"Floor spin au-dessus de la tête","description":"Les deux poi tournent à plat au-dessus de ta tête comme des pales d'hélicoptère, en plongeant légèrement plus bas sur l'extérieur à chaque tour.","goodFor":"Le plan sol et des épaules stables au-dessus de la tête.","alignmentCues":["Mains juste au-dessus de la tête.","Laisse les poi s'aplanir ; ne les muscle pas."],"props":["paire de poi"],"commonMistakes":["Épaules qui se crispent.","Poi qui plongent devant."]},"poi-low-floor":{"name":"Floor spin à hauteur des hanches","description":"Le plan sol descendu au niveau des hanches : les poi balaient à hauteur de taille, à côté de toi.","goodFor":"Le plan sol bas utilisé dans les hybrides sol-mur.","alignmentCues":["Mains de chaque côté des hanches.","Garde les cercles bien à plat."],"props":["paire de poi"],"commonMistakes":["Poi qui touchent les cuisses.","Buste penché en avant."]},"poi-three-beat-weave":{"name":"Weave à trois temps","description":"Le mouvement signature des poi : en timing décalé, les poi balancent d'un côté du corps à l'autre, les bras se croisant et se décroisant quand les plans changent de côté.","goodFor":"La base sur laquelle tout spinner de poi construit son flow.","alignmentCues":["Tourne les épaules avec le weave.","Les plans s'inclinent légèrement vers chaque côté."],"props":["paire de poi"],"commonMistakes":["Mains qui restent au centre.","Poi qui se percutent au croisement."]},"poi-reverse-three-beat-weave":{"name":"Weave à trois temps inversé","description":"Le weave à trois temps avec les deux poi qui tournent en arrière. Les bras se croisent par-dessus au lieu de passer dessous.","goodFor":"Tressage dans les deux sens.","alignmentCues":["Même motif d'un côté à l'autre, spin inversé.","Garde les mains à hauteur de poitrine."],"props":["paire de poi"],"commonMistakes":["Les têtes se percutent en haut.","Tressage qui rétrécit d'un côté."]},"poi-two-beat-weave":{"name":"Tressage à deux temps","description":"Un tressage plus rapide qui change de côté à chaque temps. Les croisements plus rapides le rendent plus dense et plus compact.","goodFor":"Changements de côté rapides.","alignmentCues":["Rotations d'épaules plus courtes et plus rapides.","Croise les poignets près de la poitrine."],"props":["paire de poi"],"commonMistakes":["Retombée dans le rythme à trois temps.","Perte du split."]},"poi-five-beat-weave":{"name":"Tressage à cinq temps","description":"Un tressage plus long et plus ample : les poi font plus de tours de chaque côté avant de recroiser.","goodFor":"Garder la forme du tressage sur des phrases plus longues.","alignmentCues":["Rotations d'épaules amples.","Garde les croisements fluides."],"props":["paire de poi"],"commonMistakes":["Croisement trop tôt.","Plans qui s'aplatissent."]},"poi-behind-back-weave":{"name":"Tressage dans le dos","description":"Une paire de temps sur deux, le poi droit passe derrière ton dos et revient devant sans casser le rythme.","goodFor":"Des passages autour du corps qui changent le rendu d'un motif simple.","alignmentCues":["Descends bas derrière les hanches.","Regarde devant toi, fais confiance au rythme."],"props":["paire de poi"],"commonMistakes":["Le poi tape dans le dos.","Le poi de devant s'arrête pendant que celui de derrière continue."]},"poi-crossers":{"name":"Croisement","description":"Spins simultanés en wall plane : les bras se croisent devant toi puis se rouvrent, et les poi échangent de côté à chaque temps.","goodFor":"Croisements de bras en rythme avec les poi.","alignmentCues":["Croise au niveau des poignets.","Garde les deux poi en phase."],"props":["paire de poi"],"commonMistakes":["Les tethers s'emmêlent quand les bras se croisent.","Un poi qui se bloque."]},"poi-reels":{"name":"Bobines","description":"Les deux poi tournent ensemble d'un côté du corps pendant une mesure, puis se balancent vers l'autre côté.","goodFor":"Déplacer les deux poi comme un seul bloc autour du corps.","alignmentCues":["Les mains restent proches l'une de l'autre.","Tourne le corps pour faire face à chaque côté."],"props":["paire de poi"],"commonMistakes":["Les mains s'écartent pendant le croisement.","Croisement hors du temps."]},"poi-thread-the-needle":{"name":"Posture du fil dans l’aiguille (gauche)","description":"Poi en directions opposées et en split time, avec croisement des bras : un poi se glisse dans l'espace que l'autre vient de quitter.","goodFor":"Un timing précis entre les deux mains.","alignmentCues":["Croise quand l'espace s'ouvre.","Garde les cercles serrés."],"props":["paire de poi"],"commonMistakes":["Les poi se percutent en plein croisement.","Le timing glisse vers le same time."]},"poi-buzzsaw":{"name":"Scie circulaire","description":"Mains pressées l'une contre l'autre et les deux poi tournant comme un seul, les lanières côte à côte comme une lame unique en rotation.","goodFor":"Synchroniser parfaitement les deux poi.","alignmentCues":["Paumes jointes, poignets détendus.","Un cercle, deux têtes."],"props":["paire de poi"],"commonMistakes":["Les têtes s'écartent.","Les mains s'éloignent l'une de l'autre."]},"poi-one-hand-isolation":{"name":"Isolation à un poi","description":"La main décrit un cercle à l'opposé de la tête, à la même vitesse, si bien que le milieu de la lanière semble fixé en l'air pendant que le poi tourne autour.","goodFor":"La première illusion : un point fixe dans l'espace.","alignmentCues":["La main toujours à l'opposé de la tête.","Regarde le milieu de la lanière, pas la tête."],"props":["un poi"],"commonMistakes":["Cercle de la main trop petit, donc le point se balade.","Accélération en haut du cercle."]},"poi-isolation":{"name":"Isolements","description":"Isolations dans les deux mains en même temps, les deux points fixes côte à côte devant toi.","goodFor":"Contrôle de l'illusion à deux mains.","alignmentCues":["Les deux mains à l'opposé de leurs têtes.","Coudes souples, épaules basses."],"props":["paire de poi"],"commonMistakes":["Une main qui perd l'isolation.","Les points dérivent vers l'avant."]},"poi-split-isolation":{"name":"Isolations en split time","description":"Isolations décalées d'un demi-tour : une main en haut pendant que l'autre est en bas, les points fixes restent stables.","goodFor":"Timing de l'isolation en split time.","alignmentCues":["Les mains alternent en haut et en bas.","Les points restent au même niveau."],"props":["paire de poi"],"commonMistakes":["Les mains se synchronisent.","Les points descendent."]},"poi-wheel-isolation":{"name":"Isolations en plan de roue","description":"Isolations à côté de toi dans le plan de roue, les points immobiles flottant à tes côtés.","goodFor":"Isolations dans un second plan.","alignmentCues":["Points à hauteur des hanches.","Les mains tournent parallèlement à tes côtés."],"props":["paire de poi"],"commonMistakes":["Les plans se tordent vers l'extérieur.","Les mains trop près du corps."]},"poi-extension":{"name":"Extensions","description":"Bras et corde en une seule ligne droite, la main tourne large pour que le poi trace le plus grand cercle possible.","goodFor":"De grandes formes ouvertes et la moitié extension du cateye.","alignmentCues":["Étends depuis l'épaule.","Main et tête du poi alignées sur une même ligne depuis le centre."],"props":["paire de poi"],"commonMistakes":["Le poignet plie.","Les cercles s'écrasent en bas."]},"poi-cateye":{"name":"Œil de chat","description":"Une main isole pendant que l'autre fait une extension. Les deux trajectoires se chevauchent en forme d'amande, comme l'œil d'un chat.","goodFor":"Mélanger deux trajectoires de main différentes à la fois.","alignmentCues":["La main qui isole reste serrée, celle qui étend tourne large.","Les deux mains démarrent ensemble en haut."],"props":["paire de poi"],"commonMistakes":["Les deux mains font la même chose.","Forme déséquilibrée."]},"poi-one-hand-antispin":{"name":"Antispin à un poi","description":"La main tourne dans un sens pendant que le poi tourne dans l'autre : trois tours de poi pour chaque cercle de main, ce qui dessine une fleur à quatre pétales.","goodFor":"La sensation de l'antispin avant les fleurs avec deux poi.","alignmentCues":["Cercle de main large et lent.","Chaque pointe de pétale au bord du cercle de main."],"props":["un poi"],"commonMistakes":["Le poi repasse en spin simple.","Pétales irréguliers."]},"poi-antispin-flower":{"name":"Antispin à quatre pétales","description":"Fleurs antispin dans les deux mains en même temps, deux fleurs à quatre pétales qui s'épanouissent côte à côte.","goodFor":"La fleur de poi classique.","alignmentCues":["Les mains tournent ensemble.","Les pétales s'alignent : haut, côté, bas, côté."],"props":["paire de poi"],"commonMistakes":["Une main qui passe en spin.","Des fleurs qui dérivent vers l'avant."]},"poi-split-antispin":{"name":"Antispin en temps décalé","description":"Des fleurs à quatre pétales avec les poi décalés d'un demi-tour, les pétales d'une fleur comblant les espaces de l'autre.","goodFor":"Timing des fleurs en temps décalé.","alignmentCues":["Les mains opposées sur leurs cercles.","Les pétales s'entrelacent."],"props":["paire de poi"],"commonMistakes":["Glissement vers le même temps.","Les mains tournent à des vitesses différentes."]},"poi-three-petal-antispin":{"name":"Antispin à trois pétales","description":"Une fleur à trois pétales : deux antispins par cercle de main, d'où une floraison triangulaire.","goodFor":"Changer le nombre de pétales en changeant la vitesse de la main.","alignmentCues":["Main plus rapide qu'à quatre pétales.","Pétales à trois points régulièrement espacés."],"props":["paire de poi"],"commonMistakes":["Retour à quatre pétales.","Le cercle de main rétrécit."]},"poi-five-petal-antispin":{"name":"Antispin à cinq pétales","description":"Quatre antispins par cercle de main, une fleur à cinq pétales avec une main plus lente et plus large.","goodFor":"Contrôle fin du rapport main-poi.","alignmentCues":["Main très lente.","Compte quatre tours de poi par cercle de main."],"props":["paire de poi"],"commonMistakes":["On perd le compte des pétales.","Main qui s'arrête."]},"poi-wheel-antispin":{"name":"Antispin en plan de roue","description":"Des fleurs antispin à quatre pétales à côté de vous, dans le plan de roue.","goodFor":"Des fleurs dans le plan de roue.","alignmentCues":["Des fleurs parallèles à vos côtés.","Les mains tournent à côté des hanches."],"props":["paire de poi"],"commonMistakes":["Les plans s'inclinent vers l'intérieur.","Les pétales accrochent les jambes."]},"poi-overhead-antispin":{"name":"Antispin au-dessus de la tête","description":"Des fleurs antispin à plat au-dessus de la tête, les pétales s'ouvrant au-dessus de vous.","goodFor":"Fleurs dans le plan du sol.","alignmentCues":["Mains juste au-dessus de la tête.","Les pétales restent à plat."],"props":["paire de poi"],"commonMistakes":["Les fleurs penchent vers l'avant.","Les épaules fatiguent et s'affaissent."]},"poi-antispin-and-spin":{"name":"Antispin et spin","description":"La main droite dessine une fleur antispin à quatre pétales pendant que la gauche garde un simple spin avant.","goodFor":"Indépendance des mains : deux formes différentes en même temps.","alignmentCues":["La main en spin garde un cercle serré.","La main de la fleur dessine de grands cercles."],"props":["paire de poi"],"commonMistakes":["Les deux mains se copient.","Les poi en spin ralentissent."]},"poi-inspin-flower":{"name":"Inspin à quatre pétales","description":"La main tourne lentement dans le même sens que le poi, cinq spins par cercle de main, en dessinant des boucles qui pointent vers l'intérieur.","goodFor":"Fleurs inspin, le pendant de l'antispin.","alignmentCues":["La main et le poi tournent dans le même sens.","Les boucles des pétales font face au centre."],"props":["paire de poi"],"commonMistakes":["Cercle de main trop rapide.","Boucles irrégulières."]},"poi-three-petal-inspin":{"name":"Inspin à trois pétales","description":"Inspin avec quatre spins par cercle de main, en dessinant une fleur à trois boucles.","goodFor":"Changer le nombre de pétales en inspin.","alignmentCues":["Main légèrement plus rapide que pour quatre pétales.","Trois boucles, régulièrement espacées."],"props":["paire de poi"],"commonMistakes":["Erreur de comptage.","Les boucles s'aplatissent."]},"poi-wall-wheel-hybrid":{"name":"Hybride mur–roue","description":"À chaque révolution, les poi changent de plan, devant puis sur le côté, au moment où la tête passe droit vers le bas.","goodFor":"Changer de plan sans casser le spin.","alignmentCues":["Change de plan quand le poi pointe vers le sol.","Tourne le poignet, pas tout le bras."],"props":["paire de poi"],"commonMistakes":["Changement en plein milieu du cercle.","Les poi vacillent entre les plans."]},"poi-wheel-floor-hybrid":{"name":"Hybride roue–sol","description":"Les poi alternent entre tourner à côté de toi et balayer à plat, en changeant quand ils pointent vers l'avant.","goodFor":"Un second hybride avec un plan horizontal.","alignmentCues":["Changez de plan quand les poi pointent devant vous.","Gardez les mains à hauteur de hanches."],"props":["paire de poi"],"commonMistakes":["Les poi plongent pendant le changement.","Perte du rythme."]},"poi-floor-wall-hybrid":{"name":"Hybride sol–mur","description":"Du plan horizontal au-dessus de la tête au plan vertical devant, puis retour, en changeant quand les poi pointent sur les côtés.","goodFor":"Relier le plan au-dessus de la tête et le plan mural.","alignmentCues":["Changez de plan quand les poi pointent sur le côté.","Montez et descendez les mains en douceur."],"props":["paire de poi"],"commonMistakes":["Les poi touchent la tête.","Changements irréguliers."]},"poi-top-stall":{"name":"Caler","description":"Le poi monte au sommet, s'arrête un instant juste au-dessus de la main, puis retombe par où il est venu.","goodFor":"Stopper et repartir en arrière : la base des combos de stalls et des hyperloops.","alignmentCues":["Levez la main quand le poi atteint son point haut.","Laissez-le pendre, puis guidez-le en arrière."],"props":["un poi"],"commonMistakes":["La ficelle se détend et s'enroule.","Pause précipitée."]},"poi-stalls":{"name":"double rangée","description":"Les deux poi stallent ensemble en haut et repartent en arrière, côte à côte.","goodFor":"Contrôle du stall à deux mains.","alignmentCues":["Les deux atteignent le sommet au même moment.","Les mains se lèvent ensemble."],"props":["paire de poi"],"commonMistakes":["Un poi stalle en retard.","Les poi se percutent en redescendant."]},"poi-side-stall":{"name":"Stalles latérales","description":"Les poi stallent sur les côtés plutôt qu'au sommet, chacun marquant une pause à hauteur d'épaule avant de repartir.","goodFor":"Des stalls à un autre point du cercle.","alignmentCues":["Marquez la pause quand les poi pointent sur le côté.","Bras souples."],"props":["paire de poi"],"commonMistakes":["Les poi tombent au lieu de marquer la pause.","Le timing se décale."]},"poi-chasing-stalls":{"name":"Chasser les décrochages","description":"Des stalls espacés d'un demi-temps : un poi marque la pause en haut pendant que l'autre monte encore.","goodFor":"Stalls en split time.","alignmentCues":["Un stall, puis l'autre.","Garde les mains à hauteur de poitrine."],"props":["paire de poi"],"commonMistakes":["Les deux stalls en même temps.","Deuxième stall précipité."]},"poi-hyperloop":{"name":"Hyperloop","description":"Un stall où le plan bascule au point haut : le poi boucle et redescend sur l'autre face du cercle.","goodFor":"Des boucles en trois dimensions depuis le stall.","alignmentCues":["Pivote le poignet en haut du stall.","Garde la corde tendue."],"props":["un poi"],"commonMistakes":["Retournement avant le point haut du poi.","Corde qui se détend."]},"poi-arm-wrap":{"name":"Wrap de bras","description":"Le poi s'enroule autour de l'autre avant-bras tendu devant toi, tourne plus vite sur une corde plus courte, puis se déroule pour retrouver le cercle complet.","goodFor":"Le premier wrap, et comment les wraps accélèrent le poi.","alignmentCues":["Garde le bras d'appui immobile et à l'horizontale.","Garde la main qui tourne derrière le bras d'appui."],"props":["un poi"],"commonMistakes":["Bras d'appui qui bouge.","Déroulement dans le mauvais sens."]},"poi-leg-wrap":{"name":"Wrap de jambe","description":"Lève le genou et laisse le poi s'enrouler autour de la cuisse, puis redescends la jambe pendant qu'il se déroule.","goodFor":"Des wraps sur le corps.","alignmentCues":["Genou levé à l'arrivée du poi.","Reste bien vertical sur la jambe d'appui."],"props":["un poi"],"commonMistakes":["Genou levé trop tard.","Perte d'équilibre."]},"poi-neck-wrap":{"name":"Wrap de cou","description":"Depuis un spin au-dessus de la tête, descends la main pour que le poi s'enroule derrière la nuque, puis se déroule pour remonter au-dessus de la tête.","goodFor":"Un wrap spectaculaire qui enchaîne les spins au-dessus de la tête.","avoidIf":["Utilise des poi d'entraînement à têtes molles ; n'apprends jamais les wraps de cou avec le feu."],"alignmentCues":["Menton à l'horizontale, nuque longue.","Guide la corde vers la base de la nuque."],"props":["un poi"],"commonMistakes":["Wrap au niveau de la tête.","Corde trop molle."]},"poi-cord-wrap":{"name":"Enveloppe d'attache","description":"Depuis le papillon, les deux lanières s'enroulent l'une autour de l'autre en bas, les têtes tournoyant sur des cordes courtes avant de se dérouler.","goodFor":"Wraps entre les deux poi.","alignmentCues":["Fais se rejoindre les lanières en bas du papillon.","Garde les mains immobiles pendant l'enroulement."],"props":["paire de poi"],"commonMistakes":["Les mains s'écartent.","Wrap qui s'emmêle."]},"poi-toss":{"name":"Lancer de poi","description":"Lâche la poignée quand le poi remonte. Il tourne dans les airs, puis tu rattrapes la poignée quand elle revient vers toi.","goodFor":"Lâchers et rattrapes.","avoidIf":["Entraîne-toi aux lancers avec des poi souples et de l'espace autour de toi."],"alignmentCues":["Lâche en montée.","Regarde la poignée, pas la tête."],"props":["un poi"],"commonMistakes":["Lâcher trop tard.","Attraper la lanière au lieu de la poignée."]},"poi-high-toss":{"name":"Lancer haut","description":"Un lancer plus haut, avec un tour supplémentaire en l'air avant la rattrape.","goodFor":"Des lancers plus amples, avec plus de rotation.","alignmentCues":["Une poussée plus ferme au lâcher.","Rattrape la poignée quand elle revient."],"props":["un poi"],"commonMistakes":["Lancer qui dérive vers l'avant.","Rattraper brusquement."]},"poi-double-toss":{"name":"Double Lancer","description":"Les deux poi lancés en split time, l'un après l'autre, puis rattrapés dans la rotation.","goodFor":"Timing des lancers à deux mains.","alignmentCues":["Lâche l'un, puis l'autre.","Rattrape dans le même ordre."],"props":["paire de poi"],"commonMistakes":["Lâcher les deux en même temps.","Regarder un poi et perdre l'autre de vue."]},"shake-out":{"name":"Secouer les bras","description":"Pose les props et secoue les mains et les avant-bras. Laisse tomber les épaules.","goodFor":"Une courte remise à zéro entre les runs difficiles."},"breathe":{"name":"Pause et recentrage","description":"Pose les accessoires, tiens-toi détendu et laisse pendre les bras. Prends un moment avant la prochaine série.","goodFor":"Fait baisser le rythme cardiaque et dissipe la frustration après les drops."}}`),t={"warmup-mobility":{name:`Échauffement flow`,description:`Poignets, épaules, colonne et hanches assouplis sur un beat régulier. À faire avant toute session avec un prop.`,focus:`Échauffement · mobilité`},"first-throws":{name:`Premiers lancers`,description:`Une balle qui décrit un arc d'une main à l'autre à hauteur des yeux, puis l'échange à deux balles d'où naît chaque figure.`,focus:`Jonglage · fondamentaux`},"cascade-builder":{name:`Construire la cascade`,description:`Des échanges à deux balles enchaînés jusqu'à ce que la troisième balle rejoigne : courtes séries de cascade, reset, on repart.`,focus:`Jonglage · fondamentaux`},"juggling-tempo-ladder":{name:`Échelle de tempo en cascade`,description:`La cascade à trois tempos, quelques beats plus rapide à chaque palier. Lance plus bas pour les paliers rapides.`,focus:`Jonglage · tempo`},"siteswap-sampler":{name:`Échantillon de siteswap`,description:`Cascade vers 423, 441 et 531, avec la reverse cascade et la shower pour te purifier le palais. Chaque figure commence et se termine en cascade.`,focus:`Jonglage · figures`},"four-ball-session":{name:`Session à quatre balles`,description:`Deux dans une main de chaque côté, la fontaine à quatre balles, puis la fontaine synchrone.`,focus:`Jonglage · nombres`},"juggling-combo-flow":{name:`Enchaînement de jonglage`,description:`Un long set fluide : cascade, cascade inversée, Mills mess et les siteswaps enchaînés en un seul morceau de musique.`,focus:`Jonglage · enchaînements`},"cascade-tricks":{name:`Figures en cascade`,description:`Tennis, demi-douche et claws, chacun glissé dans une cascade en cours puis ressorti.`,focus:`Jonglerie · variations`},"juggling-body-throws":{name:`Lancers autour du corps`,description:`Sous la jambe, derrière le dos, chops et pingouins : la cascade lancée autour du corps.`,focus:`Jonglerie · lancers autour du corps`},"sync-shapes":{name:`Figures synchrones`,description:`Colonnes, le rainbow cross, la box et le yo-yo : trois balles lancées deux par deux.`,focus:`Jonglerie · patterns synchrones`},"club-foundations":{name:`Bases en massues`,description:`Spins simples, échange à deux massues et cascade à trois massues, avec des flats pour finir.`,focus:`Jonglerie · massues`},"passing-with-a-partner":{name:`Passing à deux`,description:`Faites face à votre partenaire et passez : une balle en travers, puis deux chacun, puis le six temps, le quatre temps et le deux temps.`,focus:`Jonglage · passing`},"club-passing-session":{name:`Passing de massues`,description:`Quatre temps à la massue pour l'échauffement, deux temps et trois temps pour le rythme, puis les doubles passes.`,focus:`Jonglage · passing de massues`},"hoop-juggling-session":{name:`Jonglerie au hoop`,description:`Des hoops pleine taille lancés à plat : lancers simples, l'échange, la cascade et son inverse.`,focus:`Jonglerie · hoops`},"staff-first-spins":{name:`Premiers spins au staff`,description:`Le wheel spin à côté du corps, puis le front spin. Des tours lents et réguliers, un par temps.`,focus:`Staff · bases`},"staff-foundations":{name:`Bases du staff`,description:`Wheel spin, front spin, figure 8 et le passage main à main reliés sur le temps.`,focus:`Staff · bases`},"staff-flow-weave":{name:`Weave fluide au staff`,description:`Figure 8 en butterfly, spins à une main et le helicopter, enchaînés pour que le staff ne s'arrête jamais.`,focus:`Bâton · flow`},"staff-isolation-lab":{name:`Labo d'isolations au staff`,description:`Isolations et antispin flower à un tempo plus lent, avec des passes dans le dos entre les deux.`,focus:`Staff · technique`},"staff-advanced-flow":{name:`Flow avancé au staff`,description:`Tout le vocabulaire en un seul long morceau : weaves, wraps, isolations et le neck roll.`,focus:`Bâton · flow`},"staff-both-ways":{name:`Staff dans les deux sens`,description:`Chaque spin de base à l'endroit puis à l'envers, plus l'hélicoptère à deux mains au-dessus de la tête.`,focus:`Staff · sens et plans`},"staff-contact-lab":{name:`Labo contact staff`,description:`Contact main ouverte et contact sur le corps : fishtails, le volant, rolls sur la main et l'avant-bras, et un lancer pour finir.`,focus:`Bâton · contact`},"double-staff-session":{name:`Session de double staff`,description:`Un staff court dans chaque main : same time, split time, wheels et split wheels.`,focus:`Bâton · double bâton`},"hoop-first-spins":{name:`Premiers spins au hoop`,description:`Hoop à la taille avec une poussée avant-arrière, puis le hoop qui tourne autour d'une main.`,focus:`Hoop · bases`},"hoop-body-flow":{name:`Flow on-body au hoop`,description:`Faire monter le hoop jusqu'à la poitrine, descendre aux genoux et revenir à la taille, sans s'arrêter.`,focus:`Hoop · sur le corps`},"hoop-off-body":{name:`Hoop off-body`,description:`Hand spins, lasso, wedgies et passes, pour finir avec des isolations qui immobilisent le hoop dans l'espace.`,focus:`Hoop · hors du corps`},"hoop-full-flow":{name:`Flow complet au hoop`,description:`On-body et off-body ensemble : escalators, neck hooping et les figures off-body en un seul long flow.`,focus:`Cerceau · flow`},"hoop-body-zones":{name:`Zones corporelles du hoop`,description:`Taille dans les deux sens, puis hanches, cuisses et poitrine, en faisant monter et descendre le hoop entre les zones.`,focus:`Hoop · sur le corps`},"hoop-tricks-session":{name:`Figures de hoop`,description:`Des side spins, le coin flip, le weave, un lancer et le drop-in pour revenir sur le corps.`,focus:`Hoop · hors du corps`},"hoop-doubles-session":{name:`Doubles au hoop`,description:`Deux hoops : rotations de main en miroir et décalées, spins latéraux, et un hoop à la taille avec une rotation de main.`,focus:`Cerceau · doubles`},"poi-foundations":{name:`Les bases du poi`,description:`Un poi, puis deux : wall spins avant et arrière, roues sur les côtés, split time et le papillon.`,focus:`Poi · premières rotations`},"poi-weave-session":{name:`Weaves de poi`,description:`Du split time vers le weave à trois temps, dans les deux sens, puis le weave à deux temps, les reels et les crossers.`,focus:`Poi · Weaves`},"poi-flower-lab":{name:`Labo des fleurs au poi`,description:`Extensions et isolations, puis antispin avec un poi puis avec deux, et une fleur en inspin pour finir.`,focus:`Poi · fleurs`},"daily-mixed-flow":{name:`Flow mixte quotidien`,description:`Un peu de chaque art : cascade, spins au staff et hoop, avec un mouvement de mobilité entre les agrès.`,focus:`Mixte · pratique`}},n=JSON.parse(`{"start-here":{"title":"Commence ici : ta première semaine de flow","summary":"Choisis un agrès, pratique dix minutes par jour sur le temps, et laisse l'arbre de déblocage te dire ce qui vient ensuite.","imageAlt":"Figure 3D lançant une seule balle de jonglage d'une main à l'autre","body":["De l'extérieur, les arts du flow ressemblent à de la magie : des balles suspendues dans l'air, un bâton qui se transforme en flou, un cerceau qui orbite autour d'une danseuse qui semble à peine bouger. De l'intérieur, c'est un empilement de très petites compétences, chacune apprenable en un après-midi, superposées jusqu'à ce que l'ensemble paraisse sans effort. Votre première semaine concerne le bas de cet empilement.","Choisissez un agrès pour commencer. La jonglerie enseigne le timing et la coordination œil-main ; le bâton enseigne les plans et les changements de main fluides ; le cerceau enseigne le rythme à travers tout le corps. Vous pouvez apprendre les trois, mais un à la fois garde votre attention là où se trouve le progrès. L'arbre des Récompenses montre chaque mouvement pour chaque art, du premier lancer ou spin aux figures avancées, et ouvre les suivants quand vous maîtrisez ce sur quoi ils se construisent.","Pratiquez peu et souvent. Dix minutes concentrées par jour valent mieux qu'une heure le dimanche, car la coordination se consolide entre les sessions, surtout pendant le sommeil. Une courte routine depuis la page Routines, un échauffement, et quelques pas comptés de votre mouvement actuel constituent une pratique complète.","Pratiquez en rythme dès le premier jour. Chaque mouvement dans SynthFlow est compté en mesures à un tempo, avec de la musique ou des percussions générées qui correspondent. Le beat vous donne quelque chose à quoi vous accrocher quand l'agrès ne coopère pas, et il rend le progrès mesurable : une série propre à 90 BPM cette semaine, 100 la semaine prochaine.","Attendez-vous à faire tomber. Tout le monde fait tomber, y compris les professionnels en répétition. Une chute vous dit quel lancer ou quelle réception demande de l'attention ; elle ne dit rien sur le talent. Ramassez l'agrès, attendez le prochain temps fort, et repartez. À la fin de la semaine, vous aurez un mouvement que vous pouvez faire sans réfléchir, et c'est le moment où le flow commence."]},"counting-and-the-beat":{"title":"Les comptes, les mesures et le beat","summary":"Pourquoi chaque mouvement est compté en mesures à un tempo, et comment caler vos lancers et vos spins sur la musique.","imageAlt":"Figure 3D jonglant une cascade à trois balles avec des arcs dessinés au-dessus des mains","body":["La musique est faite de beats groupés en mesures, généralement quatre beats par mesure. Les mouvements de flow sont faits de cycles : un lancer de chaque main, un demi-tour du bâton, une orbite du cerceau. Quand un cycle tombe sur le beat, le mouvement et la musique ne font plus qu'un. C'est pourquoi SynthFlow mesure chaque pas de routine en mesures plutôt qu'en secondes, et pourquoi chaque mouvement indique combien de beats prend un cycle.","Dans une cascade à trois balles, chaque lancer tombe sur un beat, en alternant droite et gauche. Dans un front spin au bâton, un demi-tour prend généralement un beat. Le hooping à la taille correspond souvent à une orbite par beat à un tempo détendu. Les comptes dans le lecteur nomment ce qui se passe à chaque beat, et la figure 3D bouge exactement sur la même horloge que l'audio, pour que vous puissiez la copier en rythme.","Le tempo se mesure en battements par minute (BPM). Chaque mouvement a une plage confortable : assez lent pour rester propre, assez rapide pour que l'agrès garde son élan. En dessous de la plage, les agrès en rotation calent et les lancers montent si haut qu'ils dérivent ; au-dessus, vous commencez à vous précipiter et à faire tomber. Le builder vous avertit quand un pas sort de la plage de son mouvement.","Commencez chaque pas sur le temps fort, le « un » de la mesure. Le décompte vous donne une mesure pour mettre l'agrès en mouvement avant que les mesures comptées ne commencent. Si vous perdez le beat, ne le poursuivez pas : arrêtez-vous, écoutez le prochain « un », et revenez. Les musiciens appellent cela retrouver le haut de la mesure, et ça marche aussi pour les flow artists.","Compter à voix haute pendant quelques sessions aide plus qu'il n'y paraît. Dire « un, deux, trois, quatre » en jonglant lie le rythme à votre souffle et à votre voix, pour qu'il survive quand la figure devient difficile. Une fois que les comptes vivent dans votre corps, désactivez les comptes parlés dans les Réglages et laissez la musique vous porter."]},"tempo-ladders":{"title":"Échelles de tempo : lent c'est fluide, fluide c'est rapide","summary":"Montez de quelques BPM à la fois depuis un tempo que vous maîtrisez proprement, et redescendez dès que la forme se casse.","imageAlt":"Figure 3D faisant tourner un bâton devant le corps dans le plan du mur","body":["Une échelle de tempo, c'est le même mouvement répété à des tempos croissants : huit mesures à 80 BPM, huit à 88, huit à 96, et ainsi de suite. C'est la façon la plus fiable de rendre un mouvement plus rapide sans le rendre plus brouillon, et plusieurs routines intégrées sont construites autour de ça.","Commencez sur un barreau que vous pouvez faire proprement, même s'il semble trop facile. Le but du barreau du bas n'est pas le défi ; c'est de répéter la forme correcte pour que ce soit elle qui accélère. Montez d'un petit palier, environ cinq à dix pour cent. Les grands sauts changent le mouvement : les lancers deviennent plus bas, les spins plus superficiels, et vous finissez par pratiquer un autre trick.","Arrêtez de monter quand la forme se casse, pas quand vous faites tomber. Surveillez les premiers signes : des sommets qui deviennent inégaux, le bâton qui dérive hors de son plan, le cerceau qui monte ou descend. Ce sont les signaux pour redescendre d'un barreau et recommencer. Terminer une échelle sur une série propre à un tempo juste sous votre limite apprend ce tempo à votre corps ; terminer sur un crash apprend le crash.","Les tempos lents sont plus difficiles qu'ils n'en ont l'air pour les agrès en rotation, car l'agrès a moins d'élan pour le porter. Si un bâton ou un cerceau cale au bas de sa plage, gardez le tempo et élargissez légèrement le mouvement, ou prenez-le en half time avec la musique : un cycle tous les deux beats.","Suivez votre meilleur tempo propre pour chaque mouvement dans Progrès. Voir ce nombre grimper au fil des semaines est une bonne motivation, et cela montre aussi quand un mouvement a plafonné et a besoin d'un autre exercice plutôt que de plus de la même chose."]},"siteswap-notation":{"title":"Siteswap : la jonglerie écrite en chiffres","summary":"Chaque chiffre indique combien de beats plus tard une balle est relancée ; les chiffres impairs croisent, les pairs restent, et la moyenne est le nombre de balles.","imageAlt":"Figure 3D jonglant le siteswap 441 avec deux lancers hauts et un zip rapide","body":["Les figures de jonglerie sont difficiles à décrire en mots et faciles à décrire en chiffres. Le siteswap, développé indépendamment au milieu des années 1980 par des jongleurs à Cambridge, à Caltech et à Santa Cruz, écrit une figure comme une séquence répétée de chiffres. C'est ainsi que les jongleurs partagent des figures, vérifient si une idée peut fonctionner, et découvrent des tricks que personne n'a essayés. SynthFlow l'utilise pour animer chaque figure de jonglerie depuis le même moteur.","Imaginez les mains lançant en alternance à chaque beat : droite, gauche, droite, gauche. Chaque chiffre d'un siteswap indique combien de beats à partir de maintenant la balle lancée sur ce beat sera relancée. Un 3 revient trois beats plus tard ; comme trois est impair, il atterrit dans l'autre main. Une cascade à trois balles n'est que 3, 3, 3, 3 à l'infini, écrit simplement 3. Un 4 revient quatre beats plus tard dans la même main, c'est la fontaine à quatre balles.","Les petits chiffres ont des significations spéciales. Un 2 revient dans la même main deux beats plus tard, ce qui en pratique signifie tenir la balle un instant. Un 1 croise vers l'autre main au beat suivant, un zip rapide droit à travers. Un 0 est une main vide. Les chiffres plus grands sont des lancers plus hauts : un 5 est un grand lancer croisé.","Lisez une figure chiffre par chiffre. Dans 441, deux lancers restent de leur propre côté tandis qu'une troisième balle zip à travers en dessous. Dans 531, un lancer croisé haut monte tandis qu'un lancer de cascade et un zip font bouger les deux autres balles. Dans 423, un lancer à hauteur de fontaine, une balle tenue et un lancer de cascade se relaient.","Le théorème de la moyenne vous dit combien de balles une figure nécessite : additionnez les chiffres et divisez par leur nombre. 441 fait 9 sur trois chiffres, donc trois balles. Si la moyenne n'est pas un nombre entier, la séquence ne peut pas être jonglée. Une seconde vérification est que deux balles ne peuvent pas atterrir dans la même main sur le même beat, c'est ainsi que les jongleurs repèrent les figures impossibles avant de les essayer.","Le siteswap a aussi une notation pour les deux mains lançant ensemble, écrite entre parenthèses comme (4,4), et pour lancer deux balles d'une main en même temps, écrite entre crochets. Vous n'avez besoin de rien de tout cela pour bien jongler, mais une fois que les chiffres font tilt, chaque nouveau nom de figure commence à s'expliquer de lui-même. Ouvrez le glossaire Flow pour les chiffres individuels."]},"passing-basics":{"title":"Les bases du passing : jongler à deux","summary":"Placez-vous face à un partenaire, lancez de la main droite en même temps, passez tout droit vers sa main gauche, et comptez : six temps, quatre temps, deux temps.","imageAlt":"Deux jongleurs 3D face à face, se passant des balles en ligne droite","body":["Le passing, c'est jongler avec quelqu'un d'autre. Deux jongleurs se placent face à face, chacun fait sa cascade, et de temps en temps un lancer part vers le partenaire au lieu de revenir vers vous. C'est l'un des aspects les plus conviviaux du jonglage : le passing de massues est la façon dont beaucoup de jongleurs passent une soirée de festival, et il transforme l'entraînement en conversation.","Placez-vous à environ deux mètres et demi l'un de l'autre avec des balles, un peu plus loin avec des massues. Vous commencez tous les deux à jongler sur le même compte, mains droites qui lancent ensemble. La passe standard est droite : elle part de votre main droite et atterrit dans la main gauche de votre partenaire, directement en face de vous. On ne la lance pas au visage. Visez sa hanche gauche et donnez-lui une trajectoire en arc qui culmine juste au-dessus de la hauteur de la tête, à mi-chemin entre vous.","Les patterns de passing tirent leur nom de la fréquence des passes. Dans le six temps, vous passez tous les six lancers, ce qui laisse cinq selfs entre deux pour souffler. Dans le quatre temps, l'échauffement standard, vous passez un lancer sur deux à la main droite : passe, self, self, self. Dans le deux temps, chaque lancer de la main droite est une passe et chaque lancer de la gauche un self. Dans le trois temps, les passes alternent de main en main, donc vous apprenez aussi à passer de la gauche. L'ultimates, ou un temps, transforme chaque lancer en passe.","Comptez à voix haute ensemble au début. « Passe, deux, trois, quatre » vous garde sur le même tempo, et dès que l'un de vous décroche, les passes n'arrivent plus à temps. La voix de comptage de SynthFlow dit « passe » sur vos passes et « self » sur les autres lancers, en rythme, pour que vous puissiez travailler le timing seul pendant que le partenaire à l'écran jongle avec vous.","Commence avec une seule balle. Lance-la en travers, laisse ton partenaire la faire passer de sa main gauche à sa main droite et te la renvoyer. Prenez ensuite deux balles chacun et passez en même temps de la main droite, en transférant la balle reçue de la gauche vers la droite. Ce n'est qu'ensuite qu'on ajoute la cascade. La plupart des chutes en passing viennent de passes trop longues ou trop plates, et les deux se corrigent plus facilement avec une balle qu'avec six.","Dans la notation SynthFlow, un pattern de passing liste tes lancers et ceux de ton partenaire, un par temps, avec p pour marquer une passe : le quatre-temps s'écrit <3p 3 3 3|3p 3 3 3>. Les chiffres signifient la même chose qu'en siteswap. Un 4p est une double passe qui retombe un temps plus tard, et c'est comme ça qu'on construit les patterns à sept massues."]},"planes-and-geometry":{"title":"Les plans : mur, roue et sol","summary":"Les agrès en rotation vivent dans des plans plats ; garder le plan propre est l'essentiel de ce qui rend un bâton ou un cerceau net.","imageAlt":"Figure 3D tissant un bâton en figure-8 des deux côtés du corps","body":["Un bâton ou un cerceau en rotation balaie une surface plate, appelée son plan. Les flow artists décrivent trois plans de base par rapport au corps. Le plan du mur est devant vous, comme une vitre contre laquelle vous pourriez poser les paumes. Le plan de la roue est à côté de vous, comme une roue de charrette qui tourne le long de votre flanc. Le plan du sol est horizontal, parallèle au sol, comme dans un helicopter au-dessus de la tête ou un lasso.","Les plans propres sont ce que le public lit comme de la compétence. Un bâton qui vacille hors de son plan paraît incertain même s'il ne tombe jamais ; un cerceau qui reste parfaitement plat pendant un pass paraît sans effort. La plupart du travail précoce concerne discrètement les plans : empêcher les poignets de se tordre, empêcher les coudes de s'écarter, et laisser les épaules bouger l'agrès plutôt que les mains.","Beaucoup de tricks se définissent par le changement de plan. Un weave en figure-8 fait passer le bâton du plan de la roue d'un côté au plan de la roue de l'autre. Un butterfly le plie derrière l'épaule et le ramène. Un escalator fait monter et descendre un cerceau le long du corps tandis que son plan reste horizontal. Apprendre où chaque mouvement commence et finit dans l'espace, c'est ainsi que vous les reliez en flow.","Le visualiseur 3D peut dessiner le plan pendant que vous pratiquez. Activez-le en apprenant un nouveau spin et comparez : votre bâton penche-t-il vers vous en haut ? Le cerceau plonge-t-il à l'avant ? Un miroir ou une caméra de téléphone montre la même chose. Regarder depuis la vue de côté est particulièrement utile pour les mouvements dans le plan du mur, car l'inclinaison est invisible de face.","Les plans aident aussi pour la sécurité et l'espace. Avant une session, vérifiez que chaque plan que vous allez utiliser est dégagé : le mur devant, les murs à côté, et le plafond au-dessus pour les mouvements dans le plan du sol et au-dessus de la tête. Un plan propre sans rien dedans est un plan confiant."]},"spin-and-antispin":{"title":"Spin, antispin et isolations","summary":"La façon dont l'agrès tourne par rapport à la main donne trois familles de mouvement : spin, antispin et isolation.","imageAlt":"Figure 3D dessinant une fleur antispin à quatre pétales avec un staff","body":["Quand tu fais tourner un agrès en mouvement circulaire, deux rotations se produisent en même temps : ta main parcourt un cercle, et l'agrès tourne autour de son propre centre. La théorie du flow nomme les mouvements selon la relation entre ces deux rotations. C'est le même vocabulaire pour le staff, le hoop et le poi, c'est pourquoi les compétences se transfèrent si bien entre les agrès.","En spin, parfois appelé inspin, l'agrès tourne dans le même sens que le cercle de la main. C'est la direction naturelle ; la plupart des premiers spins sont des inspins sans que personne ne les nomme ainsi. La forme tracée est une fleur dont les pétales pointent vers l'extérieur.","En antispin, l'agrès tourne dans le sens opposé au cercle de la main. Ça paraît étrange au début, comme se taper la tête et se frotter le ventre, mais ça dessine la fleur à pétales classique. Le nombre de pétales dépend du nombre de rotations de l'agrès par cercle de main : trois contre-rotations par cercle donnent quatre pétales, ce qui est l'Antispin à Quatre Pétales dans l'arbre du staff.","Une isolation est le cas particulier où la main tourne de sorte qu'un point de l'agrès semble figé dans l'espace. Avec un staff, le centre reste immobile pendant que les extrémités balayent autour ; avec un hoop, le centre de l'anneau ou un point du bord reste en place. Les isolations donnent l'impression que l'agrès flotte et que le corps orbite autour. Elles exigent des trajectoires de main précises, ce qui en fait un excellent entraînement pour toutes les autres figures.","Apprends-les lentement et en rythme. L'antispin surtout bénéficie d'un tempo bien en dessous de ta vitesse normale, avec des comptes qui nomment où l'agrès doit se trouver : haut, côté, bas, côté. Utilise le ghost dans la vue 3D pour voir la position de la prochaine mesure, et la traînée pour vérifier si ta fleur a des pétales réguliers.","Une fois que spin, antispin et isolation sont familiers dans un plan, essaie-les dans un autre. La théorie reste la même et ton corps apprend que le plan n'est qu'un réglage, ce qui est un grand pas vers l'improvisation du flow."]},"sequencing":{"title":"Comment se construisent les routines de flow","summary":"Échauffe-toi, travaille un focus avec des enchaînements qui coulent, garde les sauts de tempo petits, et termine par un retour au calme facile.","imageAlt":"Figure 3D faisant passer un hoop de main en main devant le corps","body":["Une bonne routine de flow a la même forme qu'un bon set musical : une ouverture qui réchauffe la salle, un milieu qui monte, et une fin qui laisse tout le monde respirer. Les routines intégrées de SynthFlow suivent cette forme, et le co-pilote du builder vérifie la tienne par rapport à elle.","Commence par un échauffement. Les cercles de poignets, les cercles de bras et les rotations d'épaules amènent les articulations que tu vas solliciter dans toute leur amplitude à un tempo doux. Deux ou trois minutes suffisent pour une courte session ; les sessions plus longues et les jours froids méritent plus.","Donne au bloc de pratique un seul focus. Choisis un mouvement que tu travailles et entoure-le de mouvements qui s'y enchaînent. Le builder montre comment chaque étape se connecte à la précédente : enchaînement direct depuis la même position de main, un petit re-grip, poser l'agrès, ou construire sur une figure précédente. Les routines qui coulent ressemblent à une danse ; les routines pleines de poses ressemblent à une liste.","Garde les changements de tempo petits entre les étapes. Passer de 80 à 130 BPM réinitialise ton timing et invite les chutes. Le co-pilote signale les sauts de plus d'environ un quart, en repliant le half et le double time pour qu'une étape de hoop à 70 BPM puisse côtoyer un morceau à 140 BPM.","Reviens au mouvement focus plus d'une fois. La répétition au fil d'une session, avec d'autres mouvements entre les deux, développe la compétence mieux qu'un seul long bloc, parce que chaque retour est une tentative fraîche depuis un point de départ légèrement différent.","Termine par un retour au calme : un mouvement facile à tempo lent, ou un court repos avec quelques respirations. Ça fait redescendre le rythme cardiaque et donne à ta coordination une fin paisible à mémoriser. Prévisualise la routine avant de la jouer et retire tout ce qui est clairement l'ambition d'hier."]},"effort":{"title":"Quand pousser le tempo","summary":"Pousse quand la forme tient et que tu es frais ; relâche quand les peaks vacillent, que la prise se crispe ou que les chutes commencent à s'accumuler.","imageAlt":"Figure 3D jonglant cinq balles en cascade haute","body":["Le progrès en flow vient de la pratique à la limite de tes capacités, mais la limite bouge. Certains jours elle est plus loin que prévu ; d'autres jours elle a reculé. Apprendre à la lire est une compétence qui vaut autant que n'importe quelle figure.","Pousse quand les bases tiennent. Si tes peaks sont réguliers, que ton staff reste dans son plan, que ton hoop reste à niveau et que ta respiration est facile, monte d'un échelon sur l'échelle de tempo ou essaie le drill suivant dans la progression. Les quinze premières minutes d'une session, après l'échauffement, sont généralement le meilleur moment pour du nouveau matériel.","Relâche quand la qualité baisse. Des chutes groupées, une prise qui se crispe, des épaules qui remontent vers les oreilles et une respiration retenue disent tous que ton système nerveux est fatigué. Baisse le tempo, reviens à un mouvement que tu maîtrises, ou termine la session. Pousser à travers la fatigue ne fait surtout que répéter les erreurs.","Surveille aussi les signaux physiques. Les lancers et les rotations répétitifs sollicitent les poignets, les avant-bras et les épaules. Une courbature qui disparaît en un jour est une adaptation normale. Une douleur vive, une douleur qui augmente pendant la pratique, un engourdissement ou des picotements sont des raisons de s'arrêter et de se reposer ; des symptômes persistants méritent un clinicien.","Utilise la note d'effort après chaque session. Le practice wizard la lit : plusieurs sessions difficiles d'affilée et il suggère quelque chose de plus doux, plusieurs faciles et il suggère un peu plus. Des notes honnêtes font de meilleures suggestions."]},"drops-are-data":{"title":"Les chutes sont des données","summary":"Une chute te dit quel lancer ou quelle réception corriger ; la traiter comme un échec ne t'apprend qu'à te crisper.","imageAlt":"Figure 3D échangeant deux balles de jonglage entre les mains","body":["Chaque jongleur a un jour un sol couvert de balles. Chaque spinner de staff a entendu le fracas. La différence entre les gens qui continuent de progresser et ceux qui arrêtent est rarement le talent ; c'est la façon dont ils traitent la chute.","Une chute est une mesure. Elle te dit quel lancer a mal tourné, quelle réception tu as cherchée, quel moment du spin a perdu son plan. Si la même balle retombe toujours devant toi, tes lancers dérivent vers l'avant. Si les chutes arrivent après six lancers, quelque chose dans ton troisième ou quatrième lancer ne va pas. Regarde où et quand, puis choisis une chose à changer.","Traiter les chutes comme un échec a un coût. La peur crispe les épaules et raccourcit la respiration, et la tension rend les mouvements plus petits et plus rapides, ce qui cause plus de chutes. La réponse calme — ramasser, respirer, attendre le temps fort, repartir — n'est pas seulement agréable ; c'est la réponse techniquement correcte.","Compte les runs propres, pas les chutes. SynthFlow valide un mouvement quand tu as assez de runs propres et de minutes de pratique, donc les chutes en chemin font simplement partie des minutes. Certains jours tu enregistreras dix runs propres, d'autres deux. Les deux jours comptent.","Fais tomber exprès parfois. Quand tu apprends une nouvelle figure, travaille le premier lancer ou le premier demi-spin et laisse tomber. Puis ajoute la réception. Isoler le moment risqué le réduit, et tu apprends que le sol n'est pas ton ennemi. C'est juste là où va l'agrès quand tu apprends."]},"safety":{"title":"Sécurité : espace, agrès et signaux d'alerte","summary":"Dégage tes plans, choisis des agrès indulgents, échauffe-toi, et arrête-toi en cas de douleur vive, d'engourdissement ou de vertige.","imageAlt":"Figure 3D faisant tourner un staff à plat au-dessus de la tête avec de l'espace dégagé autour","body":["Les flow arts présentent peu de risques comparés à la plupart des sports, mais les agrès vont vite et voyagent plus loin que prévu. Quelques habitudes gardent la pratique sûre pour toi, les personnes proches et le mobilier.","Dégage ton espace avant de commencer. Vérifie chaque plan que tu vas utiliser : devant, sur les côtés et au-dessus. Le staff et le hoop ont besoin de plus de place que tu ne le penses, généralement un cercle d'au moins l'envergure plus la longueur de l'agrès dans chaque direction, sans rien de cassable à portée. À l'intérieur, attention aux luminaires et aux ventilateurs ; dehors, attention au sol irrégulier et aux passants.","Utilise des agrès indulgents pendant l'apprentissage. Les balles de jonglage en beanbag ne roulent pas loin. Les staffs rembourrés ou à embouts en mousse font moins mal quand ils touchent ta tête, ce qui arrivera. Un hoop plus grand et plus lourd tourne plus lentement et est plus facile à maintenir. Passe à des agrès plus rapides ou plus flashy une fois les bases automatiques.","Échauffe-toi avant chaque session et augmente le volume progressivement. Lancer et faire tourner sont répétitifs, et la charge répétitive sur des tissus froids est la cause habituelle des poignets et coudes douloureux. Si tu ajoutes beaucoup de pratique d'un coup, ajoute aussi des jours de repos.","Arrête-toi en cas de signaux d'alerte : douleur vive ou électrique, engourdissement ou picotements dans les mains, douleur qui s'aggrave en continuant, vertige, ou un coup à la tête avec des symptômes persistants. Les mouvements de nuque et les contact rolls méritent une attention particulière ; apprends-les lentement avec un agrès rembourré.","Cette app enseigne la technique, pas les soins médicaux. Grossesse, blessures récentes, problèmes articulaires et tout ce qui t'inquiète sont des raisons de consulter un professionnel qualifié avant d'ajouter de la charge. La performance avec feu est une discipline à part avec sa propre formation sécurité ; SynthFlow ne l'enseigne pas."]},"warm-up":{"title":"Pourquoi l'échauffement compte pour le travail des agrès","summary":"Deux à cinq minutes de mobilité des poignets, bras, épaules et hanches rendent les rotations plus fluides et préservent tes articulations.","imageAlt":"Silhouette 3D faisant des cercles lents des poignets, bras tendus devant","body":["La pratique du flow paraît douce, mais elle sollicite beaucoup quelques articulations. La jonglerie répète le même lancer des milliers de fois ; le staff fait rouler les poignets sur toute leur amplitude ; le hoop balance la colonne et les hanches à chaque orbite. Un tissu chaud tolère bien mieux cette répétition qu'un tissu froid.","Un bon échauffement flow est court et spécifique. Les cercles de poignets dans les deux sens préparent les articulations qui font la majorité du travail. Les cercles de bras et les rotations d'épaules réveillent la coiffe des rotateurs et les omoplates, qui contrôlent le plan de chaque rotation. Les cercles de hanches et les torsions du buste comptent surtout pour le hoop. Les demi-cercles de nuque, jamais les rotations complètes, relâchent la tension liée au fait de regarder un pattern vers le haut.","Bouge lentement et en rythme. Les étapes d'échauffement dans SynthFlow sont comptées comme tout le reste, à un tempo détendu, pour que les premières minutes d'une session accordent aussi ton timing. Quand les agrès arrivent, tu bouges déjà avec la musique.","Termine l'échauffement avec l'agrès à moitié vitesse. Quelques lancers lents, un front spin tranquille ou une grande orbite de hoop lente relient le travail de mobilité au mouvement que tu vas travailler, et ils te disent comment ton corps se sent aujourd'hui.","L'échauffement est aussi une transition mentale. Les mêmes trois minutes au début de chaque session deviennent un signal que la pratique a commencé. Les jours chargés, l'échauffement est parfois toute la pratique, et ça compte quand même."]},"anatomy-basics":{"title":"Le corps derrière les agrès","summary":"Les avant-bras serrent et relâchent, les épaules dirigent le plan, le centre te garde stable : une carte simple pour le flow.","imageAlt":"Silhouette 3D faisant du hoop à la taille, haut du corps relâché","body":["Pas besoin de connaître l'anatomie pour jongler, mais une carte simple t'aide à comprendre ce qui fatigue, quoi échauffer et quoi reposer. La section Muscles de Learn a un modèle interactif ; cet article est la visite rapide.","Les avant-bras font la plupart du travail fin. Les muscles côté paume ferment les doigts et fléchissent le poignet ; les muscles du dos de l'avant-bras ouvrent les doigts et étendent le poignet. Attraper et relâcher, tenir un staff et le laisser rouler, tout se passe ici. La fatigue des avant-bras est la sensation la plus courante après une longue session, et c'est pourquoi la prise relâchée est un rappel si fréquent.","Les épaules dirigent. Les deltoïdes lèvent les bras ; la coiffe des rotateurs, quatre petits muscles autour de l'articulation, garde le haut du bras centré pendant qu'il bouge. Les muscles autour des omoplates maintiennent tout le système stable. Quand un staff dérive hors de son plan, la cause est souvent l'épaule, pas la main.","Le centre te garde tranquille. En jonglerie, un buste immobile empêche le pattern de dériver. En hoop, les muscles abdominaux et du dos entraînent le hoop avec de petites impulsions avant-arrière. Les hanches et les jambes sont ta base : des genoux souples absorbent le mouvement et te laissent déplacer ton poids sans perturber l'agrès.","Tes yeux et ton oreille interne comptent aussi. La jonglerie t'entraîne à regarder les sommets, pas les mains ; le spin entraîne ton équilibre. Des sessions courtes avec des pauses laissent les deux s'adapter sans vertiges. Prends cette carte comme un savoir de base, pas un diagnostic, et consulte un professionnel pour une douleur qui ne passe pas."]},"biomechanics-safety":{"title":"Poignets, épaules et charge répétitive","summary":"Prise relâchée, poignets neutres et volume progressif gardent heureuses les articulations qui font tout le travail.","imageAlt":"Silhouette 3D faisant tourner un staff d'une main sur le dos de la main","body":["Les blessures en flow sont rarement spectaculaires. Ce sont presque toujours des surcharges : trop de répétitions, trop de prise, trop peu de repos. La bonne nouvelle, c'est que les mêmes quelques habitudes évitent la plupart d'entre elles.","Relâche la prise. Une balle de jonglerie n'a besoin que de juste assez de pression pour rester dans la main ; un staff a besoin d'un anneau de doigts lâche dans lequel il peut rouler. Serrer fatigue les muscles de l'avant-bras et charge les tendons au coude. Si tes jointures blanchissent ou que tes avant-bras brûlent après quelques minutes, relâche et baisse le tempo.","Garde les poignets proches du neutre quand tu peux. Le spin fait passer les poignets sur de grandes amplitudes, ce qui est très bien avec modération. Les tenir en fin d'amplitude longtemps, ou forcer un poignet raide à tourner, voilà ce qui les irrite. Laisse le coude et l'épaule partager le mouvement.","Laisse les épaules travailler, mais sans les hausser. Les grands cercles viennent de l'articulation de l'épaule ; une épaule haussée pince et fatigue vite. Vérifie dans le miroir ou le mode caméra que tes épaules restent basses, surtout dans les mouvements au-dessus de la tête comme l'hélicoptère et le lasso.","Augmente le volume progressivement. Si tu pratiques vingt minutes d'habitude, ne passe pas à deux heures parce qu'un festival arrive. Augmente le temps total d'une quantité modeste chaque semaine et garde au moins un jour facile. Alterne les agrès pour répartir la charge : le hoop repose les avant-bras que la jonglerie fatigue.","Une douleur qui disparaît en un jour est une adaptation normale ; une douleur qui persiste, s'aggrave ou s'accompagne d'engourdissement ne l'est pas. Repose-toi, réduis le volume et demande un avis professionnel si ça persiste. Ceci est éducatif, pas un avis médical."]},"choosing-props":{"title":"Choisir ses premiers agrès","summary":"Des beanbags pour la jonglerie, un staff léger rembourré et un grand hoop adulte rendent les premières semaines bien plus faciles.","imageAlt":"Silhouette 3D faisant tourner un hoop autour d'une main","body":["De bons agrès de débutant rendent l'apprentissage plus rapide et moins frustrant. Pas besoin de matériel cher, mais quelques choix comptent.","Pour la jonglerie, commence avec trois beanbags d'environ 60 à 130 grammes chacun. Les beanbags ne rebondissent pas et ne roulent pas quand ils tombent, ce qui évite beaucoup de courses. Ils doivent tenir confortablement dans ta paume. Les stage balls, plus grosses, et les balles en silicone rebondissantes, c'est pour plus tard. Des couleurs assorties t'aident à voir le pattern ; trois couleurs différentes t'aident à suivre chaque balle quand tu apprends les siteswaps.","Pour le staff, un staff de spin débutant mesure généralement autour de 1,2 à 1,5 mètre, léger, avec des embouts rembourrés ou en caoutchouc. En gros, il devrait arriver entre ta poitrine et ton épaule posé debout. Un staff plus long et plus lourd tourne plus lentement et plus doucement une fois les bases acquises, mais il est plus dur pour commencer et fait plus mal quand il te touche. Une prise au milieu aide.","Pour le hoop, commence plus grand et plus lourd que tu ne le penses. Un hoop adulte débutant arrive généralement entre la taille et la poitrine posé au sol. Les grands hoops tournent plus lentement, te donnant le temps de trouver le rythme pour le waist hooping. Les hoops plus petits et plus légers conviennent aux tricks rapides hors du corps une fois à l'aise.","Quoi que tu choisisses, assure-toi que la plage de tempo du mouvement convient à l'agrès. Les agrès plus lourds aiment généralement les tempos plus bas. Si la plage confortable de l'app te semble précipitée avec ton agrès, règle ton propre tempo dans le builder ; les comptes suivent."]},"practice-at-home":{"title":"Pratiquer à la maison et au parc","summary":"Des sessions quotidiennes courtes, un espace dégagé, un bord de lit ou de canapé pour rattraper les chutes, et un jam au parc quand tu peux.","imageAlt":"Silhouette 3D secouant les bras entre les rounds de pratique","body":["La plupart des flow artists apprennent à la maison, quelques minutes à la fois. Un petit aménagement rend la pratique à la maison plus facile à commencer et à tenir.","Trouve ton coin. Pour la jonglerie, te tenir devant un lit ou un canapé fait que les balles tombées atterrissent à hauteur de taille au lieu de rouler sous les meubles, et ça t'empêche aussi d'avancer. Pour le staff et le hoop, trouve le plus grand espace dégagé que tu as, vérifie le plafond et range tout ce qui est fragile. Un jardin ou un parc est mieux pour les grandes rotations.","Garde les agrès visibles. Des balles sur le bureau se jonglent pendant les appels et les pauses thé ; un hoop près de la porte sert. Moins il faut d'effort pour commencer, plus souvent tu le feras. Une routine de cinq minutes compte, et plusieurs sessions courtes par jour s'additionnent vite.","Utilise l'appli comme structure. Choisis une routine ou laisse l'assistant t'en suggérer une, joue-la en entier et note ton effort. Les programmes courts comme Zero to Cascade donnent un objectif clair à chaque semaine, ce qui t'évite de dériver entre les figures.","Entraîne-toi avec d'autres quand tu peux. Les clubs de jonglage, les écoles de cirque et les jams de flow en plein air existent dans beaucoup de villes. Regarder quelqu'un qui a un pas d'avance sur toi corrige souvent ce qu'un tutoriel n'a pas pu, et enseigner à quelqu'un qui a un pas de retard rend ta propre technique plus claire. Apporte tes agrès, demande aux gens ce qu'ils travaillent et partage ce que les comptes t'ont appris."]},"learning-with-the-app":{"title":"Apprendre avec le coach 3D","summary":"Ralentis, mets en miroir, active le ghost et les trails, change la caméra et utilise le mode caméra pour avoir un retour.","imageAlt":"Figure 3D exécutant une isolation au staff avec un trail montrant la trajectoire","body":["Chaque mouvement dans SynthFlow est animé en 3D sur la même horloge que la musique, donc la figure est toujours exactement sur le beat. Bien utilisé, le viewer est un professeur patient qui ne se lasse jamais de te montrer le même lancer.","Ralentis d'abord. L'échelle de progression de chaque mouvement commence par des versions lentes et partielles, puis mains seules, puis le mouvement complet sur le beat. La demi-vitesse garde les relations de timing intactes tout en donnant à tes yeux le temps de suivre.","Mets la figure en miroir si tu apprends mieux face à un professeur, et change la caméra quand une vue cache quelque chose. Les vues de côté montrent l'inclinaison du staff et la dérive des lancers ; les vues du dessus montrent les plans du hoop et les trajectoires d'hélicoptère. Les trails dessinent où chaque agrès est passé, ce qui transforme un flou en une forme que tu peux étudier. Le ghost montre où l'agrès sera sur le beat suivant.","Observe les erreurs courantes. Chaque mouvement peut montrer ses défauts typiques, comme dériver vers l'avant, des hauteurs inégales ou précipiter, joués volontairement mal sur la figure, avec l'indice qui les corrige. Reconnaître un défaut sur le modèle rend beaucoup plus facile de le ressentir dans ton propre corps.","Le mode caméra te donne un retour sur toi. Avec ton accord, il suit tes mains et ton corps pendant que tu t'entraînes et compare ton timing avec le beat. Le traitement se fait sur ton appareil. Ce n'est pas parfait, et un bon éclairage aide, mais même un retour approximatif sur le fait que tu sois en avance ou en retard est précieux.","Enfin, ferme parfois le viewer. Entraîne-toi avec la musique seule et fais confiance aux comptes. L'objectif est un mouvement que tu peux faire sans rien regarder du tout."]},"music-for-flow":{"title":"Trouver une musique qui colle","summary":"Des tempos mesurés, la demi et le double tempo, des percussions générées et tes propres morceaux gardent les comptes honnêtes.","imageAlt":"Figure 3D faisant du hoop à la poitrine avec les bras levés","body":["La musique transforme la pratique en flow, mais seulement si le beat de la musique est le beat des comptes. Un morceau à 118 BPM sous une routine à 120 BPM se décale en moins d'une minute, et tu finis par te battre contre la musique au lieu de la chevaucher.","Les morceaux inclus dans SynthFlow ont des tempos et des downbeats mesurés, donc le lecteur peut commencer chaque étape sur le « un » de la musique et garder les comptes alignés. Le builder liste d'abord les morceaux qui correspondent au tempo d'une section, y compris les morceaux à la moitié ou au double du tempo : un morceau à 140 BPM porte parfaitement bien une étape de hoop à 70 BPM.","Les percussions générées fonctionnent à n'importe quel tempo. Choisis un kit pour une section et le lecteur synthétise un beat qui correspond exactement, que tu fasses une échelle de tempo ou un drill lent. C'est aussi la meilleure option quand tu veux la pulsation sans qu'une mélodie attire ton attention.","Tu peux analyser des morceaux depuis ton propre appareil. L'appli estime le tempo et le downbeat et te laisse les vérifier en tapant en rythme. Les morceaux avec une pulsation électronique ou acoustique régulière fonctionnent le mieux ; la musique avec des changements de tempo, du rubato ou de longues intros est plus difficile à mesurer et plus difficile pour s'entraîner.","Le streaming vidéo est désactivé pendant la pratique comptée car son timing ne peut pas être contrôlé précisément. Utilise-le plutôt pour les échauffements ou le free play, là où rien n'a besoin de s'aligner."]},"plateaus":{"title":"Les plateaux et le long milieu","summary":"Chaque flow artist passe par des semaines où rien ne progresse ; change le drill, le tempo ou l'agrès avant de changer l'objectif.","imageAlt":"Figure 3D jonglant le Mills Mess avec les bras croisés","body":["Le début du flow est merveilleux : quelque chose de nouveau à chaque session. Puis, souvent vers le moment où tu sais jongler une cascade régulière ou garder un hoop en l'air indéfiniment, la progression semble s'arrêter. C'est dans ce long milieu que la plupart des gens abandonnent, et que l'apprentissage le plus intéressant se produit.","Les plateaux sont généralement de la consolidation. Ton système nerveux réorganise le mouvement pour qu'il demande moins d'attention, ce qui ne se voit pas sous forme de nouvelles figures. Souvent, une compétence qui semblait bloquée pendant deux semaines apparaît soudain un matin. Continue à pratiquer pendant la partie plate.","Change le drill, pas l'objectif. Si la cascade ne veut pas s'accélérer, travaille-la à un tempo plus bas avec des sommets parfaits, puis avec les yeux fixés sur un point au-dessus du pattern, puis avec une seule main. Si un mouvement de staff ne vient pas, découpe-le en deux moitiés et travaille chacune sur le beat. De nouveaux drills donnent à ton cerveau de nouvelles informations sur la même compétence.","Fais du cross-training. Apprendre un deuxième agrès débloque souvent le premier. Le hoop améliore le rythme derrière le jonglage ; le travail du staff enseigne les plans qui rendent les figures de hoop propres. L'arbre de Rewards de chaque art est indépendant, donc la variété ne coûte jamais de progression.","Sois bienveillant avec toi-même. Compare-toi au mois dernier, pas aux performeurs en ligne qui s'entraînent depuis dix ans. La page Progress garde une trace honnête des minutes, des tempos max et des mouvements maîtrisés. Une semaine plate, regarde-la et vois jusqu'où la ligne est déjà montée."]},"history-of-juggling":{"title":"Une brève histoire du jonglage","summary":"D'une peinture de tombe égyptienne aux jongleurs médiévaux, au théâtre de variétés et aux mathématiques modernes.","imageAlt":"Figure 3D jonglant une shower à trois balles en cercle","body":["Le jonglage est très ancien. L'une des plus anciennes images connues est une peinture murale dans une tombe du Moyen Empire à Beni Hasan en Égypte, vieille d'environ quatre mille ans, montrant des femmes lançant des balles. Des récits et des images de Chine, de Grèce, de Rome et du Pacifique suggèrent que des personnes de nombreuses cultures ont trouvé le chemin du lancer et de la rattrape pour le spectacle et le jeu.","Dans l'Europe médiévale, le mot jongleur, d'où vient « juggler », désignait des artistes itinérants qui chantaient, racontaient des histoires, faisaient des acrobaties et lançaient des objets. Le jonglage était une compétence parmi d'autres, faisant partie de la boîte à outils d'un performeur plutôt qu'un art à part entière.","Les théâtres de variétés et les cirques des XIXe et début XXe siècles ont fait du jonglage un numéro de tête d'affiche. Les performeurs se sont spécialisés : jongleurs gentlemen avec chapeaux et cannes, jongleurs de massues, et jongleurs de nombres poussant vers sept, huit balles et plus. Enrico Rastelli, au début du XXe siècle, est encore souvent cité comme l'un des plus grands.","À partir des années 1970, une culture du jonglage de loisir s'est développée autour de clubs, de festivals et de conventions, avec des gens partageant librement des figures. Les mathématiques s'y sont jointes dans les années 1980 quand la notation siteswap a donné aux jongleurs un moyen d'écrire les patterns sous forme de nombres, menant à de nouvelles figures découvertes sur papier avant que quiconque ne les lance.","Aujourd'hui, le jonglage se situe au point de rencontre du cirque, du sport, de la danse et des maths. Certains jongleurs rivalisent sur les nombres et l'endurance, d'autres exécutent des chorégraphies sur musique, d'autres explorent des patterns pour eux-mêmes. Chaque voie commence par le même échange de deux balles, que tu peux apprendre cette semaine."]},"history-of-staff":{"title":"Le staff spinning : de l'arme au flow","summary":"Les bâtons d'arts martiaux, le twirling de baton et la performance avec le feu ont tous nourri le spin staff moderne.","imageAlt":"Figure 3D exécutant un butterfly au staff derrière les épaules","body":["Un staff est l'un des plus anciens outils qui existent, et en faire tourner un est une compétence ancienne. De nombreuses traditions martiales s'entraînent avec un long bâton, parmi elles le bō d'Okinawa, le gun chinois et le combat au quarterstaff européen, et leurs drills incluent des spins rapides et des changements de main pour la défense comme pour la démonstration.","Le spinning de performance a d'autres racines aussi. Le twirling de baton est devenu une discipline compétitive au XXe siècle, avec des lancers, des roulades et des spins que les spinners empruntent encore. Le théâtre, les parades et le spectacle de rue à travers le monde utilisaient des bâtons et des perches en rotation bien avant que quiconque n'appelle cela du flow.","La scène moderne du staff flow est née à la fin du XXe siècle, en parallèle du spectacle de feu et de la culture festivalière. Les staffs de feu, avec des mèches à chaque extrémité, rendaient la rotation visible dans l'obscurité et poussaient l'art vers un mouvement fluide et continu plutôt que vers des frappes. Les staffs LED ont ensuite apporté les mêmes visuels en intérieur.","À la même époque, les flow artists ont commencé à décrire la rotation avec une théorie partagée : les plans, le spin et l'antispin, les isolations, le timing et la direction. Une grande partie a été développée dans la communauté du poi puis transposée au staff, au hoop et à d'autres props, c'est pourquoi les mêmes mots apparaissent partout dans cette app.","Le contact staff, où le staff roule sur le corps au lieu d'être saisi, est devenu un style à part entière avec des rolls sur la nuque, les épaules et les bras. Aujourd'hui, le staff spinning va de la démonstration martiale au contact flow lent et méditatif, le tout construit sur le même premier wheel spin."]},"history-of-hoop":{"title":"Le hoop : du jouet ancien à l'art du flow","summary":"Les hoops sont des jouets et des outils depuis des millénaires ; une mode des années 1950 et un renouveau festivalier ont fait de la hoop dance un art.","imageAlt":"Silhouette 3D faisant monter un hoop en rotation le long du corps","body":["Les hoops comptent parmi les jouets les plus anciens. Des enfants de l'Égypte, de la Grèce et de la Rome antiques sont décrits ou représentés faisant rouler des hoops avec des bâtons et les faisant tourner autour du corps, et des jeux de hoop apparaissent dans de nombreuses cultures depuis.","Les hoops portent aussi une signification culturelle profonde dans certaines traditions. La Hoop Dance pratiquée dans de nombreuses communautés amérindiennes utilise plusieurs hoops pour former des figures comme des animaux et la terre, racontant des histoires par le mouvement. C'est une tradition vivante à part entière, distincte de la scène flow moderne, et qui mérite d'être découverte auprès de ses propres praticiens.","La mode du hula hoop en plastique à la fin des années 1950, portée par des hoops produits en masse aux États-Unis, a mis un hoop dans des millions de foyers presque du jour au lendemain. Pendant des décennies ensuite, le hoop a surtout été vu comme un jouet pour enfants et un gadget de fitness.","À partir de la fin des années 1990 et des années 2000, des hoopers adultes dans les festivals et les communautés en ligne ont commencé à traiter le hoop comme un partenaire de danse. Des hoops plus grands et plus lourds, faits main, ont rendu le on-body hooping plus facile pour les adultes, tandis que les hoops plus petits ouvraient des tricks off-body rapides. Les vidéos partagées ont diffusé un vocabulaire comme les isolations, les wedgies et les escalators bien au-delà d'une seule ville.","La hoop dance moderne emprunte la théorie au staff et au poi et le rythme à toutes sortes de musiques. Elle est accessible, joyeuse et profonde : un débutant peut trouver le rythme de taille en un jour, et un expert peut passer des années à affiner une seule isolation."]},"fire-and-led":{"title":"Props de feu, LED et de spectacle","summary":"Les props de spectacle changent le poids, la vitesse et le risque ; apprends chaque mouvement avec des props d'entraînement d'abord et travaille le feu séparément.","imageAlt":"Silhouette 3D faisant tourner un hoop à plat au-dessus de la tête comme un lasso","body":["Voir un staff de feu ou un hoop LED la nuit est souvent ce qui attire les gens vers le flow. Les props de spectacle sont merveilleux, mais ils ne sont pas identiques aux props d'entraînement, et passer à eux mérite un plan.","Les props LED sont généralement plus lourds que leurs versions d'entraînement à cause des batteries et de l'électronique. Cela change l'élan : les rotations portent plus loin, les lancers sont différents, et les poignets travaillent plus. Apprends chaque mouvement avec ton prop d'entraînement d'abord, puis attends-toi à une courte période d'adaptation en LED. Baisse le tempo pour les premières sessions.","Le spectacle de feu est une discipline à part. La manipulation du carburant, les zones de rotation sûres, les safety spotters avec couvertures anti-feu, des vêtements adaptés et les règles locales comptent, et il vaut mieux les apprendre en personne auprès de performers de feu expérimentés. SynthFlow n'enseigne pas le feu, et rien dans l'app ne doit être pratiqué avec des props allumés.","Une bonne règle utilisée dans de nombreuses communautés flow est de ne réaliser un mouvement avec un prop de spectacle qu'une fois qu'on peut le faire de manière fiable, plusieurs fois d'affilée, avec un prop d'entraînement. Sous les lumières ou les flammes, il n'y a pas de place pour les expérimentations.","Le spectacle change aussi ta façon d'enchaîner. Le public lit les grands plans, les transitions propres et les moments de stillness clairs. Construis tes routines de spectacle dans le builder comme n'importe quelle autre, prévisualise-les, et répète avec la même musique à chaque fois pour que les counts deviennent de la chorégraphie."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"Le jour où la cascade a cliqué","summary":"Trois semaines à courir après les balles à travers la pièce se sont terminées le moment où j'ai arrêté de regarder mes mains et commencé à compter.","body":["Pendant trois semaines, ma cascade à trois balles a duré exactement quatre lancers. Droite, gauche, droite, et puis la troisième balle était quelque part derrière le canapé. J'ai regardé des vidéos, j'ai ralenti, j'ai accéléré. Je me suis placé devant le lit comme tous les tutos le disent. Rien n'a changé, sauf mon vocabulaire.","La solution, quand elle est venue, était d'une simplicité gênante. J'ai mis un morceau à 90 BPM et j'ai dit les counts à voix haute : un, deux, trois, quatre, un lancer sur chaque temps. Soudain, les lancers avaient un endroit où aller. Au lieu de lancer quand la main se sentait prête, c'est-à-dire quand la panique le lui disait, chaque lancer attendait son temps. Le pattern est devenu plus lent, plus haut et plus calme.","La deuxième solution était où je regardais. Je fixais mes mains, ce qui revient à lire un livre en regardant ses paupières. Quand j'ai levé le regard vers les peaks, les deux points au sommet des arcs, mes mains ont commencé à rattraper toutes seules. Les peaks me disaient si les lancers étaient réguliers ; les mains n'avaient pas besoin de surveillance.","Douze lancers sont devenus vingt, puis cinquante. Un soir, j'ai jonglé pendant tout un step de huit mesures sans drop et j'ai souri au plafond comme un idiot. L'app a appelé ça un clean run. Moi, j'ai appelé ça la première fois que la jongle ressemblait à de la musique plutôt qu'à un combat.","Si tu es bloqué à quatre lancers, essaie ce qui a marché pour moi : compte à voix haute, lance sur le temps, regarde les peaks. Et drop sans drama. Le sol, c'est là où commence toute cascade."]},"why-we-count-in-bars":{"title":"Pourquoi on compte en mesures, pas en secondes","summary":"Une tenue de quarante secondes a du sens pour un étirement ; un pattern de jongle vit sur un temps, alors on mesure la pratique en mesures.","body":["Quand on a commencé à construire SynthFlow, la première grande décision a été comment mesurer un step de routine. Notre app sœur SynthYoga compte les tenues en secondes et en respirations. Ça marche pour une pose que tu tiens. Ça ne marche pas pour un pattern qui se répète sur un temps.","Un lancer de jongle, un demi-tour de staff et une orbite de hoop sont tous des cycles. Si la musique tourne à 100 BPM et que ta cascade tourne à 103, tu ne jongles pas sur la musique ; tu jongles à côté, et en une minute tu es un temps en retard. Mesurer les steps en mesures à un tempo signifie que la musique, les counts, la silhouette 3D et le step suivant démarrent tous sur le même downbeat.","Les mesures rendent aussi le progrès concret. « Jongle pendant une minute » est vague : une minute de quoi, à quelle vitesse ? « Huit mesures de cascade à 96 BPM » est un défi précis et reproductible. Si tu y arrives proprement, la session suivante peut demander 104. C'est comme ça que fonctionnent les échelles de tempo, et pourquoi la maîtrise dans l'app dépend de clean runs plutôt que du simple temps.","Ça a demandé une vraie ingénierie. Chaque animation est pilotée par la même horloge audio que la musique, planifiée à l'avance pour que rien ne saccade. Les morceaux intégrés ont des tempos et des downbeats mesurés. Les percussions générées remplissent n'importe quel tempo que tu choisis. Les morceaux de ton appareil sont analysés et vérifiés avec un tap test. La vidéo en streaming est désactivée en pratique comptée parce qu'on ne peut pas la garder sur le temps.","Le résultat, c'est que le beat devient un professeur. Quand tu dérives, tu l'entends. Quand tu te cales, tu le sens. Compter en mesures s'est révélé être le choix de design le plus important qu'on ait fait."]},"staff-hit-me-in-the-head":{"title":"Le staff m'a frappé à la tête (et autres leçons)","summary":"Chaque staff spinner se fait bonker ; le padding, les plans et la patience transforment les bonks en progrès.","body":["Mon premier figure-8 s'est terminé avec le staff qui rebondissait sur mon crâne et le chien qui quittait la pièce. Mon deuxième s'est terminé pareil, sans le chien. Si tu apprends le staff, tu te feras frapper. La question, c'est à quel point fort, et ce que tu en apprends.","Leçon un : le padding n'est pas de la lâcheté. Un staff d'entraînement avec des embouts souples a transformé les bonks de cris en haussements d'épaules. Le haussement d'épaules compte, parce que la peur fait flincher, et un poignet qui flinche tire le staff hors de son plan, ce qui cause le bonk suivant.","Leçon deux : la plupart des coups viennent de plans inclinés. Quand je me suis filmé de côté, je pouvais voir le staff pencher vers mon visage au sommet de chaque tour. Mes poignets roulaient vers l'intérieur. L'overlay de plan dans la visionneuse 3D montrait la version propre : le staff dans une feuille plate à côté du corps, sans jamais pencher vers l'intérieur. Corriger le poignet a corrigé les bonks.","Leçon trois : lent et compté bat rapide et plein d'espoir. J'ai baissé le tempo au bas de la plage du figure-8 et j'ai compté « côté droit, côté gauche » avec la musique. À cette vitesse, je pouvais sentir le changement de main et garder le plan plat. Une semaine plus tard, je pouvais remonter.","Leçon quatre : ris. Le staff spinning est ridicule et merveilleux. Les bonks font partie de l'histoire que tout le monde dans la scène partage. Mets un chapeau si besoin, dégage les lumières du plafond, et continue à spinner."]},"hooping-for-people-who-cant-hoop":{"title":"Le hooping pour ceux qui pensent ne pas savoir hooper","summary":"La plupart des adultes qui « ne savent pas hooper » ont essayé avec un hoop de la taille d'un jouet ; un hoop plus grand et une impulsion avant-arrière règlent la plupart du temps le problème.","body":["« Je ne sais pas hooper » est une phrase que les profs de hoop entendent constamment, généralement de quelqu'un qui a essayé pour la dernière fois avec un hoop de jouet pour enfant. Les hoops petits et légers tournent vite et tombent vite. Ils exigent des hanches rapides et frénétiques. Les adultes avec un hoop de taille adulte trouvent souvent cela bien plus gérable.","Commencez grand. Un hoop qui atteint à peu près entre votre taille et votre poitrine posé au sol tourne assez lentement pour que vous sentiez le rythme. Les hoops plus lourds portent aussi plus d'élan. Vous pourrez passer à plus petit plus tard pour la vitesse et les tricks off-body.","Pulsez, ne faites pas de cercles. L'erreur la plus courante est d'essayer de faire de grands cercles avec les hanches. Le waist hooping est généralement un petit balancement avant-arrière, ou latéral, en rythme avec le hoop. Un pied légèrement en avant aide. Le hoop touche votre ventre et votre dos ; vous poussez doucement quand il passe.","Comptez. Un tempo détendu, une orbite par temps, donne à votre corps un rythme dans lequel s'installer. L'app commence le waist hooping lentement, puis vous laisse monter. Si le hoop descend, ajoutez un peu de vitesse à votre impulsion, pas un mouvement plus grand.","Attendez-vous à ce qu'il tombe beaucoup pendant quelques sessions, puis soudainement plus. Le hooping est l'une de ces compétences qui fait tilt. Une fois que c'est le cas, tout un monde de flow on-body et off-body vous attend, et une bonne partie n'a même pas besoin de la taille."]},"unlocking-is-not-a-race":{"title":"Débloquer n'est pas une course","summary":"L'arbre des récompenses ouvre des mouvements plus difficiles à mesure que vous maîtrisez leurs fondations ; l'essentiel, ce sont les fondations.","body":["Les récompenses de SynthFlow sont des mouvements. Maîtrisez la cascade et la reverse cascade s'ouvre ; maîtrisez le front spin et le figure-8 apparaît. C'est satisfaisant de voir l'arbre s'illuminer, et nous l'avons conçu pour ça. Mais il y a un piège dans tout système de déblocage, et ça vaut la peine de le nommer.","Le piège, c'est de traiter la maîtrise comme une case à cocher. Vous pouvez techniquement enregistrer les runs propres d'un mouvement un bon jour, débloquer le suivant, et passer à autre chose avec une fondation qui ne fonctionne que quand tout va bien. Ensuite, les mouvements plus difficiles semblent impossibles, parce qu'ils supposent que la fondation tient quand ça va mal.","La maîtrise en flow, c'est quand le mouvement survit à la distraction : un peu de fatigue, un tempo différent, quelqu'un qui passe. C'est pourquoi la maîtrise demande des runs propres sur plusieurs sessions, pas seulement une. Et c'est pourquoi nous suggérons de revenir régulièrement aux mouvements maîtrisés. La cascade n'est pas un niveau que l'on termine ; c'est le sol sur lequel tout l'arbre du jonglage repose.","Les mouvements verrouillés ont quand même des pages. Vous pouvez les lire, les regarder en 3D et voir ce qu'ils demandent. Regarder devant est motivant. Pratiquer devant, sans les fondations, est surtout frustrant.","Alors profitez des déblocages, mais mesurez-vous à la facilité de vos plus anciens mouvements. Quand la cascade est ennuyeuse, vous êtes prêt pour le Mills Mess. Quand le Mills Mess est ennuyeux, l'arbre a plus à offrir."]},"practice-in-ten-minutes":{"title":"Une vraie pratique en dix minutes","summary":"Échauffement, un mouvement focus, un lien, une petite montée de tempo et un retour au calme : dix minutes, chaque jour.","body":["La raison la plus courante que les gens donnent pour ne pas pratiquer, c'est le temps. La vérité, c'est que les compétences de flow répondent brillamment à des sessions courtes et fréquentes. Voici la forme en dix minutes que nous utilisons nous-mêmes.","Minutes une à deux : échauffement. Cercles de poignets, cercles de bras, rotations d'épaules, quelques cercles de hanches si vous faites du hoop. Comptés, à un tempo détendu, pour que votre timing se réveille avec vos articulations.","Minutes trois à cinq : votre mouvement focus. Un mouvement sur lequel vous travaillez, à un tempo que vous pouvez tenir proprement. Plusieurs courts passages comptés plutôt qu'un long, avec une respiration entre eux.","Minutes six à sept : un lien. Associez le mouvement focus à quelque chose dans lequel il s'enchaîne ou d'où il vient. Cascade vers reverse cascade. Front spin vers figure-8. Waist vers chest. Les liens sont ce qui fait qu'une pratique ressemble à du flow plutôt qu'à des drills.","Minutes huit à neuf : une petite montée de tempo. Deux ou trois paliers, quelques BPM chacun, en s'arrêtant avant que la forme casse. Terminez sur un palier propre.","Minute dix : retour au calme. Un mouvement lent et facile ou un court repos. Enregistrez votre effort. Terminé.","Dix minutes par jour, c'est plus d'une heure par semaine de pratique concentrée, répartie de la façon que la coordination préfère. Le practice wizard construit des sessions de cette taille quand vous lui dites que vous manquez de temps, et les routines courtes intégrées suivent la même forme."]},"antispin-broke-my-brain":{"title":"L'antispin m'a cassé le cerveau (pendant une semaine)","summary":"Tourner le staff contre le cercle de la main semble impossible jusqu'à ce que les comptes donnent à chaque pétale un temps.","body":["L'antispin, c'est là où le staff spinning commence à ressembler à un devoir de géométrie. Votre main dessine un cercle dans un sens pendant que le staff tourne dans l'autre, et les extrémités tracent une fleur. La première fois que j'ai essayé, j'ai produit quelque chose qui ressemblait plus à un pissenlit fané.","Ce qui a aidé, c'est de rendre la forme comptable. Un antispin à quatre pétales a quatre moments où une extrémité pointe droit vers l'extérieur du cercle. J'ai donné à chacun un temps : haut, côté, bas, côté. Puis j'ai ralenti la musique bien en dessous de mon tempo habituel et j'ai simplement visé les positions sur les temps.","Le ghost dans la visionneuse 3D, qui montre où le staff devrait être au temps suivant, a été mon meilleur ami cette semaine-là. Tout comme la traînée, qui dessinait ma fleur pour que je voie quand les pétales étaient inégaux. En général, le pétale du bas était écrasé, parce que je précipitais le bas du cercle.","Après environ une semaine, quelque chose a basculé. J'ai arrêté de penser à la main et au staff comme deux choses et j'ai commencé à sentir la fleur comme une seule forme. Le tempo est revenu tout seul.","Si l'antispin vous casse le cerveau, c'est normal. Donnez à chaque pétale un temps, ralentissez la musique, et laissez votre corps trouver la solution. C'est l'une des meilleures sensations en flow quand ça arrive."]},"siteswaps-for-the-maths-shy":{"title":"Les siteswaps pour ceux qui n'aiment pas les maths","summary":"Vous n'avez pas besoin d'aimer les maths pour utiliser les siteswaps ; vous avez seulement besoin de savoir que les grands chiffres vont plus haut.","body":["La notation siteswap a une réputation qui fait fuir les gens. Les jongleurs diront joyeusement « essaie 531 » comme si ça expliquait quelque chose. C'est le cas, mais seulement une fois que vous savez deux ou trois choses, et ces choses sont plus simples qu'elles en ont l'air.","Voici presque tout ce dont vous avez besoin. Chaque chiffre est un lancer. Les grands chiffres vont plus haut. Les chiffres impairs croisent vers l'autre main ; les chiffres pairs reviennent dans la même main. Un 3 est un lancer de cascade normal. Un 1 est un zip rapide vers l'autre main. Un 2, c'est généralement juste tenir la balle.","C'est assez pour lire 441 : deux lancers plus hauts qui restent de leur côté, puis un zip vers l'autre main. Vous pouvez maintenant l'essayer sans lire un mot de plus. Lancer, lancer, zip, sur le temps.","Si vous voulez une pièce de plus : additionnez les chiffres et divisez par leur nombre, et vous obtenez le nombre de balles. 4 + 4 + 1 = 9, divisé par 3 donne 3 balles. Si la réponse n'est pas un nombre entier, le pattern ne peut pas être jonglé. C'est tout le fameux théorème de la moyenne.","Dans SynthFlow, chaque mouvement de jonglage a un siteswap, et le moteur 3D s'anime directement à partir de lui. Cela signifie que la figure lance toujours exactement les hauteurs que les chiffres décrivent, sur les temps exacts. Regarder un siteswap animé lentement est le moyen le plus rapide que nous connaissions pour que les chiffres aient du sens. Aucun diplôme de maths requis."]},"music-that-fights-you":{"title":"Quand la musique vous combat","summary":"Un morceau qui dérive par rapport aux comptes rend chaque mouvement plus difficile ; des tempos mesurés et des beats générés règlent ça.","body":["Vous l'avez probablement ressenti : une chanson que vous aimez, un mouvement que vous connaissez, et pourtant tout semble faux. Vous précipitez, vous faites tomber, vous vous blâmez. Souvent, le problème n'est pas vous. C'est que le tempo de la chanson ne correspond pas au mouvement.","Chaque mouvement de flow a une plage de tempo confortable. En dessous, les props s'arrêtent ; au-dessus, les lancers deviennent bas et frénétiques. Un morceau à 128 BPM sous un mouvement de hoop qui aime 90 vous demande de choisir entre la musique et le hoop. La bonne nouvelle, c'est que la half time et la double time aident : 128 peut porter un mouvement à 64, un cycle toutes les deux temps.","Le drift est le problème plus subtil. Si la musique dit 120 mais que les counts disent 116, les deux glissent l'un par rapport à l'autre en une minute, et votre corps ne peut pas suivre les deux. C'est pourquoi SynthFlow utilise des tempos mesurés pour ses morceaux intégrés, génère des percussions à n'importe quel tempo exact, et vérifie les morceaux de votre appareil avec un tap test.","Quand un morceau vous résiste, ne résistez pas. Passez au beat généré pour l'étape, ou laissez le builder suggérer un morceau dans la bonne plage. Gardez les chansons que vous aimez pour le free play, là où rien n'a besoin de s'aligner.","La musique doit se sentir comme un partenaire. Si elle se sent comme un adversaire, changez la musique, pas votre mouvement."]},"learning-alongside-my-kid":{"title":"Apprendre à jongler avec mon enfant","summary":"Deux débutants, un sac de balles et une règle : on célèbre les chutes aussi fort que les catches.","body":["Ma fille a demandé à apprendre la jonglerie, et j'ai réalisé que je ne savais pas jongler non plus. Alors on a appris ensemble, dix minutes après le dîner, avec trois beanbags chacun et une règle : on acclame les chutes aussi fort que les catches.","La règle semble ridicule. Elle s'est avérée être la partie la plus importante. Les enfants, et les adultes, se crispent quand ils pensent qu'une erreur est embarrassante. La tension rend les lancers pires. Acclamer chaque chute a transformé le sol en partie du jeu et nous a gardés tous les deux détendus.","On a commencé avec une balle, en la lançant d'une main à l'autre sur le beat, pics à hauteur des yeux. Ça semblait trop facile pendant environ trois sessions, puis soudain important, parce que les échanges à deux balles ne fonctionnent que si ces lancers simples sont réguliers. Elle a réussi l'échange avant moi et était insupportable à ce sujet.","La musique comptée nous a aidés à pratiquer ensemble. Même tempo, même downbeat, deux personnes qui lancent en rythme. Quand l'un de nous perdait le pattern, l'autre continuait, et celui qui avait fait tomber revenait au prochain « un ».","Quatre semaines plus tard, on a tous les deux une cascade bancale. Plus important encore, on a une habitude qu'on attend tous les deux avec impatience. Si vous avez un enfant qui veut apprendre quelque chose, apprenez-le avec lui. Être débutant ensemble est sous-estimé."]},"why-your-throws-drift-forward":{"title":"Pourquoi tes lancers dérivent vers l'avant","summary":"Si tu termines chaque cascade trois pas plus loin que ton point de départ, tes lancers penchent loin de toi. Voici comment les ramener à la maison.","body":["Chaque jongleur connaît la marche. Tu commences la cascade au milieu de la pièce et tu la termines le nez contre le mur, poursuivant le motif pas à pas. On a l'impression que les balles te tirent. Ce n'est pas le cas. Tu les lances vers l'avant, quelques centimètres à la fois, puis tu marches pour rattraper.","La cause, ce sont presque toujours les coudes. Quand tu te crispes, les avant-bras basculent vers l'avant et les mains lâchent la balle légèrement devant le corps. Chaque lancer atterrit un peu plus loin, donc la prochaine réception se fait plus loin, donc le prochain lancer part de plus loin. Ça s'amplifie vite.","Le correctif que j'enseigne en premier, c'est de rentrer les coudes. Garde les coudes près des côtes, les avant-bras à peu près à l'horizontale, et lance les balles droit vers le haut, au-delà de tes yeux, plutôt que devant toi. Ça semble serré pendant une journée. Ensuite, ça semble calme.","Le deuxième correctif, c'est un mur. Tiens-toi face à lui, à environ un avant-bras de distance, et jongle. Si les lancers dérivent, le mur te le dit immédiatement, et fort. Dix minutes de pratique contre le mur apprennent au corps ce qu'est un motif bien vertical plus vite que tout ce que je peux dire.","Le mode caméra de SynthFlow surveille aussi la dérive. Il suit à quel point ton torse paraît plus grand à la caméra au fil d'un pas, ce qui signifie que tu marches vers elle, et te pousse avec un court signal. Le coach 3D peut aussi montrer le fantôme d'un lancer vers l'avant à côté du lancer propre, pour que tu voies la différence au lieu de simplement en entendre parler.","La dérive n'est pas un défaut de caractère. C'est une habitude de tension, et les habitudes changent avec la répétition. Rentrer les coudes, lancer vers le haut et non vers l'avant, et laisse le mur te garder honnête."]},"practising-to-a-click":{"title":"Pratiquer sur un clic","summary":"Un métronome, ça semble être la chose la moins amusante du monde. Il s'est avéré que c'est ce qui a fait que mon flow ressemble à de la danse.","body":["J'ai résisté au clic pendant des années. La musique était l'essentiel du flow arts pour moi, et un métronome ressemblait à des devoirs. Puis une amie batteuse m'a regardé jongler et m'a dit, gentiment, que j'accélérais chaque fois que je m'enthousiasmais et que je ralentissais chaque fois que j'avais peur. Elle avait raison, et je n'en avais aucune idée.","Alors j'ai essayé une semaine de pratique avec rien d'autre qu'un clic. La première découverte, c'est qu'une pulsation régulière est plus difficile qu'il n'y paraît. Mon motif deux-en-une-main voulait se précipiter. Mon figure-8 au staff voulait traîner du côté faible. Le clic ne se souciait pas de ce que je ressentais ; il gardait juste le tempo.","La deuxième découverte, c'est que le clic rendait la musique plus facile. Après une semaine, quand j'ai remis de vrais morceaux, je pouvais sentir où le beat se trouvait dans le son. J'ai arrêté de me battre avec les chansons au timing flou et j'ai commencé à choisir sur quelle partie du groove me caler.","Les percussions générées par SynthFlow sont une version plus sympathique du clic. Tu choisis un kit, d'un simple clic aux tambours à main, et il joue à n'importe quel tempo, pour qu'un motif puisse vivre exactement à la vitesse que tu peux tenir. Il peut aussi tourner discrètement sous une piste musicale comme guide. Je l'utilise encore seul pour les premières minutes de chaque session.","Si tu veux essayer, choisis un motif et un tempo qui semble légèrement trop lent. Compte à voix haute pendant quatre mesures, puis arrête de compter et écoute simplement. Quand le motif et le clic semblent ne faire qu'un seul son, ajoute quatre BPM. C'est toute la méthode."]},"staff-in-a-small-apartment":{"title":"Le staff dans un petit appartement","summary":"Un staff de 1,4 mètre et un plafond de 2,4 mètres peuvent vivre ensemble. Il faut juste choisir ses plans.","body":["Mon appartement a des plafonds bas, une suspension à laquelle je tiens, et un voisin du dessous qui travaille de nuit. Rien de tout ça n'est idéal pour le staff. J'ai pratiqué dans les parcs pendant un an avant de comprendre que la plupart de mon entraînement pouvait finalement se faire à l'intérieur.","L'astuce, ce sont les plans. Les spins dans le plan de la roue, les grands à côté du corps, ont besoin de toute la hauteur du staff au-dessus de ta tête. Le travail dans le plan du mur, devant le corps, a besoin de largeur mais de moins de hauteur. Les spins dans le plan du sol, comme l'hélicoptère, ont besoin de dégagement au-dessus de ta tête mais de rien autour des tibias. Chaque pièce supporte des mouvements différents.","Dans mon salon, je peux faire des isolations, des spins avant et des figure-8 lents avec les bras bas. Dans le couloir, je ne peux rien faire du tout, donc le couloir sert aux échauffements des poignets. La chambre a le plafond le plus haut, donc le travail dans le plan de la roue s'y fait, lentement, avec la suspension retirée et rangée dans un tiroir.","Les staffs courts aident aussi. Un staff d'entraînement plus court d'une main que mon staff de performance a transformé beaucoup de quasi-accidents en dégagements faciles. Le timing change un peu, donc je vérifie mon staff pleine longueur dehors une fois par semaine.","Pour les voisins : tapis de pratique et staffs à embouts souples. Une chute sur un tapis de yoga fait un bruit sourd au lieu d'un claquement. Je limite aussi les sessions intérieures à des routines comptées de dix minutes, ce qui garde le bruit court et la pratique concentrée.","SynthFlow te permet de marquer les mouvements que tu ne peux pas faire chez toi comme non désirés, pour que le générateur les laisse hors des routines intérieures. Les petits espaces n'arrêtent pas le progrès. Ils te rendent juste très bon en isolations."]},"hooping-after-40":{"title":"Le hooping après 40 ans","summary":"J'ai pris un hoop pour la première fois à 43 ans. Mon dos, mes genoux et ma fierté avaient tous des opinions. Voici ce qui a marché.","body":["J'ai acheté mon premier hoop adulte sur un coup de tête après un festival, convaincu que je serais nul. J'étais nul. J'étais aussi, en un mois, en train de hooper à la taille pendant des chansons entières, et en six mois je faisais de simples mouvements hors du corps. L'âge ne m'a pas arrêté. Il a juste changé ma façon de devoir pratiquer.","La grande leçon était de bien s'échauffer. Les cercles de hanches, les torsions du buste et les petits rebonds de genoux prennent trois minutes et font que le premier hoop de la session semble fluide au lieu de grinçant. SynthFlow place les échauffements au début de chaque routine pour une raison, et j'ai arrêté de les sauter après une matinée raide.","La deuxième leçon était la taille du hoop. Un hoop plus grand et légèrement plus lourd tourne plus lentement, ce qui te donne plus de temps et demande moins d'effort au bas du dos. J'ai commencé avec un hoop qui atteignait entre ma taille et ma poitrine posé au sol, et je l'utilise encore pour les longues sessions.","Troisième : pulse, ne fais pas de cercle. Les débutants balancent souvent les hanches en cercle, ce qui tord la colonne plus que nécessaire. Une pulsation avant-arrière, ou latérale si le hoop tourne dans ce sens pour toi, garde le hoop en haut avec moins de tension. Le coach 3D le montre clairement si tu regardes les hanches plutôt que le hoop.","Enfin, court et souvent bat long et occasionnel. Dix minutes quatre fois par semaine m'ont plus apporté qu'une heure le dimanche. Mon corps récupérait entre les sessions, et les mouvements restaient.","Si tu as plus de 40 ans et que tu es curieux, commence. Le hoop ne sait pas quel âge tu as."]},"fire-and-the-beginner":{"title":"Le feu et le débutant","summary":"Le fire spinning est la partie la plus visible du flow arts et celle sur laquelle les débutants posent le plus de questions. La réponse honnête est : pas encore, et pas seul.","body":["Chaque semaine, quelqu'un nous demande quand SynthFlow enseignera le feu. C'est une question légitime. Le feu est beau, et beaucoup de spinners sont entrés dans le milieu après avoir vu un cercle de feu la nuit. Mais nous ne coacherons jamais quelqu'un pour allumer un prop, et ce post explique pourquoi.","Le feu ajoute des dangers qui n'ont rien à voir avec la compétence : manipulation du carburant, vêtements, vent, spectateurs, brûlures et extinction. Tout ça s'apprend de personnes expérimentées en personne, avec une personne de sécurité formée présente et l'équipement adéquat prêt. Une app ne peut pas vérifier ta réserve de carburant, tes vêtements en coton ou ta serviette de sécurité.","Ce que l'app peut faire, c'est t'aider à construire les compétences dont le feu a besoin avant même que tu t'en approches. Ça veut dire des mouvements que tu peux faire de façon fiable pendant une chanson entière, à un tempo régulier, sans chutes. Si un motif te surprend encore chez toi avec un prop d'entraînement, il n'est pas prêt pour le feu.","Un test utile venu de la communauté du feu : peux-tu exécuter ta routine les yeux à moitié fermés, dans le noir, pendant que quelqu'un te parle ? Le feu est lumineux, chaud et bruyant, et il capte ton attention. Ton corps doit connaître les mouvements sans surveillance.","Les props LED sont une excellente étape intermédiaire. Ils te donnent le look nocturne, les traînées et la réaction du public sans le risque. Le pack de style LED de SynthFlow montre à quoi ressembleront tes figures une fois éclairées, ce qui est aussi un bon moyen de repérer les plans approximatifs.","Quand tu te sens prêt, trouve un fire jam près de chez toi, présente-toi et demande à apprendre la sécurité en premier. En attendant, entraîne-toi avec des props de practice. Le feu sera toujours là."]},"four-balls-taught-me-patience":{"title":"Quatre balles m'ont appris la patience","summary":"Passer de trois balles à quatre m'a pris plus de temps que d'apprendre les trois au départ, et cela a changé ma façon de concevoir la pratique.","body":["Trois balles m'ont pris cinq semaines. Quatre m'ont pris cinq mois. Personne ne m'avait prévenu, alors je te préviens : quatre balles, ce n'est pas trois balles plus une. C'est une figure complètement différente, et ton corps doit l'apprendre de zéro.","Dans une fontaine à quatre balles, chaque main jongle deux balles de son côté, et les balles ne se croisent jamais. Les mains alternent généralement, mais il n'y a aucun échange entre elles. Tout ce que j'avais appris sur la réception d'une balle venant de l'autre main devenait soudain inutile.","Alors je suis revenu à une main. Deux balles dans la main droite, en colonnes, puis en cercles, jusqu'à pouvoir faire cinquante lancers sans réfléchir. Puis la main gauche, qui a pris trois fois plus de temps. Puis les deux mains ensemble, d'abord en sync, puis en alterné. L'échelle de tempo dans SynthFlow m'a aidé ici : je commençais chaque semaine en bas de la plage de la fontaine et je ne montais qu'après une série propre.","La leçon de patience est venue des plateaux. Certaines semaines, rien ne progressait. J'enregistrais quand même les chutes et les séries propres, et le graphique montrait une lente progression même quand je n'en ressentais aucune. Les données rendaient les semaines ennuyeuses supportables.","L'autre leçon concernait le repos. Quatre balles fatiguaient mes avant-bras d'une manière que trois n'avaient jamais fait. Quand je pratiquais tous les jours, je régressais. Quand je pratiquais un jour sur deux, je progressais. Les muscles de la prise ont besoin de récupération comme les autres.","Si tu es bloqué entre trois et quatre, découpe le problème, fais confiance aux semaines lentes et donne un jour de repos à tes avant-bras. Ça finit par arriver."]},"the-escalator-and-hand-traffic":{"title":"L'escalator et l'art du trafic des mains","summary":"Les mouvements de mains au hooping ressemblent à de la magie jusqu'à ce que tu comprennes qu'ils ne sont qu'une gestion minutieuse du trafic entre deux mains.","body":["La première fois que j'ai vu un escalator, le hoop semblait monter le long des bras de la hoopeuse et redescendre en flottant, sans fin, sans prise évidente. Je pensais qu'il fallait des années de pratique. Il a fallu environ trois semaines, une fois que j'ai compris que ce n'est qu'un enchaînement de passes de main.","Presque tous les mouvements de hoop off-body reposent sur quelle main tient le hoop, quand elle lâche, et où l'autre main le rejoint. Si le timing entre les mains est flou, le hoop vacille hors de son plan et le mouvement s'effondre. Si le timing est propre, le hoop semble bouger tout seul.","Alors j'ai commencé à nommer les passes. Sur le compte de SynthFlow, je disais les mains à voix haute au lieu des chiffres : droite, gauche, droite, gauche, une sur chaque temps. Les dire avec la musique m'obligeait à remarquer quand ma main gauche attrapait trop tôt. Les prises précoces étaient la source de presque toutes les vacillations.","La deuxième clé était de garder le hoop dans son plan. Une main qui pivote en saisissant incline le hoop, et un hoop incliné est un hoop échappé une demi-seconde plus tard. L'overlay de plan aide ici, tout comme s'entraîner devant un miroir à tempo lent.","Une fois l'escalator fiable, les autres mouvements de mains sont venus plus vite. Isolations, passes et lassos utilisent tous la même idée : passes claires, plans plats, timing régulier. La magie n'est que de la gestion de trafic."]},"behind-the-back-without-fear":{"title":"Derrière le dos sans peur","summary":"Les passes de staff derrière le dos sont le point où la plupart des spinners calent. Le problème n'est généralement pas la compétence mais l'envie de regarder.","body":["Pendant des mois, ma passe derrière le dos était une passe devant avec une torsion pleine d'espoir. Je lançais le mouvement, paniquais quand le staff quittait mon champ de vision, et le ramenais devant moi. Le staff ne passait jamais réellement derrière mon dos. Mon cerveau ne le permettait pas.","Le déclic est venu en acceptant que je ne pouvais pas voir le mouvement. On ne peut pas regarder une passe derrière le dos. Il faut sentir où est le staff depuis la main qui lâche et faire confiance à la main qui attend.","J'ai entraîné cette sensation au ralenti. Sans spinner du tout, je passais le staff derrière mon dos, de main en main, les yeux vers l'avant. Puis avec un lent demi-tour d'abord. Puis en bas de la plage de tempo du mouvement, en comptant. Chaque étape semblait ridicule. Chaque étape fonctionnait.","Le coach 3D était étonnamment utile parce que je pouvais faire pivoter la vue et regarder le mouvement depuis l'arrière. Voir où les mains se rejoignent, et comment le staff reste dans le plan du mur en tournant, a donné à mon corps une carte qu'il ne pouvait pas obtenir de face.","La deuxième peur était de me frapper. Un staff de practice à embouts souples et un grand espace dégagé ont résolu ça. Une fois que je savais qu'une erreur coûterait un léger choc plutôt qu'un bleu, j'ai arrêté de tressaillir, et c'était le tressaillement qui causait les ratés.","Si le derrière du dos te fait encore peur, ralentis vraiment, enlève la rotation et garde les yeux vers l'avant. Tes mains en savent plus que tu ne le penses."]},"why-reverse-feels-wrong":{"title":"Pourquoi la cascade inversée semble bizarre","summary":"La cascade inversée utilise les mêmes mains, les mêmes balles et le même rythme que la cascade. Alors pourquoi donne-t-elle l'impression de repartir de zéro ?","body":["Quand j'ai appris la cascade inversée, je pensais que ça prendrait un après-midi. C'est les mêmes trois balles, les mêmes mains en alternance et le même tempo que la cascade. Ça m'a pris trois semaines, et je n'arrivais pas à comprendre pourquoi.","La réponse est la direction. Dans une cascade normale, chaque balle est lancée depuis l'intérieur de la figure et rattrapée à l'extérieur. Dans une cascade inversée, la balle est lancée depuis l'extérieur, par-dessus la balle qui arrive, et rattrapée à l'intérieur. Tes mains font le même rythme mais des formes complètement différentes.","La nouvelle forme casse ton timing. Dans la cascade, tu lances juste au moment où la balle qui arrive commence à retomber. Dans l'inversée, tu dois lancer un peu plus tôt pour que ta balle passe au-dessus de l'autre. Lance au moment habituel et les balles se percutent.","J'ai corrigé ça avec deux balles d'abord. Deux balles, direction inversée, en comptant sur le temps, jusqu'à ce que ce soit automatique. Puis trois balles à tempo lent avec les comptes dits à voix haute. L'overlay fantôme de SynthFlow m'a montré une erreur typique, un lancer trop bas qui accroche l'autre balle, et je pouvais voir que je faisais exactement ça.","Une fois le déclic passé, ça a tout débloqué. Mélanger cascade et inversée est la base de nombreux tricks, et la forme inversée réapparaît dans le Mills Mess. Avoir été mauvais pendant trois semaines en valait la peine."]},"making-a-prop-stand-still":{"title":"Les isolations : faire tenir un prop immobile","summary":"Une isolation est un mouvement où le prop semble rester au même endroit pendant que tu tournes autour de lui. C'est l'illusion la plus satisfaisante des flow arts.","body":["La première fois que j'ai réussi une isolation au staff, mon ami m'a demandé comment le staff flottait. Il ne flottait pas, bien sûr. Mes mains décrivaient un cercle précis pour qu'un point du staff reste fixe dans l'air. Mais de l'extérieur, ça semblait impossible, et c'est ce sentiment qui me fait aimer les isolations.","Chaque isolation fonctionne de la même façon. Choisis un point sur le prop, généralement le centre ou une extrémité, et garde ce point immobile pendant que le reste du prop tourne. Tes mains doivent bouger exactement à l'opposé de la direction que le prop veut prendre. C'est contre-intuitif et légèrement hypnotique.","Le plus dur, c'est que ton corps bouge aussi. Les hanches se décalent, les épaules tournent, et chaque petit mouvement se traduit par un vacillement du point fixe. Je m'entraînais devant un miroir avec un morceau de ruban adhésif sur la vitre marquant l'endroit où le point fixe devait rester. Si le centre du prop quittait le ruban, je le savais.","Les isolations au hoop suivent la même idée. Dans SynthFlow, j'active les traînées dans la visionneuse 3D et je regarde le coach : dans une isolation propre, la traînée autour du point fixe reste minuscule. Quand je ralentissais vraiment le tempo et copiais, je sentais mes mains dériver en haut de chaque cercle.","Les isolations développent aussi un contrôle qui aide tout le reste. Une fois que tu peux tenir un prop immobile, tu peux le placer où tu veux. Les plans deviennent plus plats, les transitions plus propres, et ton flow commence à sembler intentionnel plutôt que chanceux.","Commence lentement, marque le point fixe et surveille-le comme un faucon. Ensuite, montre-le à un ami et savoure sa réaction."]}}`),i={"zero-to-cascade":{name:`De zéro à la cascade en 4 semaines`,description:`Une balle, puis deux, puis la troisième rejoint. Une courte session par jour suffit : terminez la routine de chaque semaine pour maîtriser son mouvement et ouvrir la suivante.`,weeks:[{label:`Semaine 1 · Une balle`},{label:`Semaine 2 · Deux balles`},{label:`Semaine 3 · La troisième balle`},{label:`Semaine 4 · Cascade`}]},"beyond-the-cascade":{name:`Au-delà de la cascade`,description:`Quatre semaines de variété à trois balles : tennis et claws, puis lancers autour du corps, puis figures synchrones deux balles à la fois.`,weeks:[{label:`Semaine 1 · Tennis et claws`},{label:`Semaine 2 · Demi-shower`},{label:`Semaine 3 · Lancers autour du corps`},{label:`Semaine 4 · Colonnes`}]},"first-clubs":{name:`Premières massues`,description:`D'une seule massue en rotation à une cascade à trois massues bien stable, puis les doubles pour la hauteur et le contrôle de la rotation.`,weeks:[{label:`Semaine 1 · Une massue`},{label:`Semaine 2 · Échange`},{label:`Semaine 3 · Cascade`},{label:`Semaine 4 · Doubles`}]},"passing-with-a-partner":{name:`Le passing à deux`,description:`Deux jongleurs, face à face. Une balle en travers, puis deux balles chacun sur le même temps, puis le six-temps, le quatre-temps et le deux-temps avec trois balles chacun.`,weeks:[{label:`Semaine 1 · Une balle en travers`},{label:`Semaine 2 · Deux balles chacun`},{label:`Semaine 3 · Six-temps et quatre-temps`},{label:`Semaine 4 · Deux-temps`}]},"staff-foundations":{name:`Les fondations du staff`,description:`Wheel spin et front spin, le figure 8 et le pass-through : les quatre mouvements sur lesquels presque tout le flow au staff se construit.`,weeks:[{label:`Semaine 1 · Wheel spin`},{label:`Semaine 2 · Front spin`},{label:`Semaine 3 · Figure 8`},{label:`Semaine 4 · Pass-through`}]},"staff-contact":{name:`Contact staff`,description:`Assouplissez la prise semaine après semaine : steering wheel et fishtail, puis hand rolls, puis le staff qui tourne sur l'avant-bras.`,weeks:[{label:`Semaine 1 · Steering wheel`},{label:`Semaine 2 · Fishtail`},{label:`Semaine 3 · Hand roll`},{label:`Semaine 4 · Forearm roll`}]},"double-staff-start":{name:`Débuter au double staff`,description:`De deux staffs en phase au split time, puis des wheels des deux côtés.`,weeks:[{label:`Semaine 1 · Même temps`},{label:`Semaine 2 · Split time`},{label:`Semaine 3 · Wheels`},{label:`Semaine 4 · Split wheels`}]},"hoop-body-ladder":{name:`Échelle corporelle au hoop`,description:`Hoop à la taille dans les deux sens, puis descente vers les hanches et les cuisses, remontée vers la poitrine.`,weeks:[{label:`Semaine 1 · Dans les deux sens`},{label:`Semaine 2 · Hanches`},{label:`Semaine 3 · Cuisses`},{label:`Semaine 4 · Chest lift`}]},"hoop-doubles-start":{name:`Début des doubles cerceaux`,description:`Un cerceau dans chaque main : spins en miroir, spins décalés, spins latéraux, puis un à la taille et un en main.`,weeks:[{label:`Semaine 1 · Spins en miroir`},{label:`Semaine 2 · Spins décalés`},{label:`Semaine 3 · Spins latéraux`},{label:`Semaine 4 · Taille et main`}]},"off-body-hoop":{name:`Hoop off-body`,description:`Du hoop qui tourne sur une main aux lassos, passes, wedgies et à l'isolation qui fait sembler le hoop flotter.`,weeks:[{label:`Semaine 1 · Hand spin`},{label:`Semaine 2 · Lasso et pass`},{label:`Semaine 3 · Wedgie`},{label:`Semaine 4 · Isolation`}]},"first-poi":{name:`Un poi pour commencer`,description:`Un poi, puis une paire : spins en plan mural dans les deux sens, spins en plan roue sur les côtés, puis split time.`,weeks:[{label:`Semaine 1 · Un poi`},{label:`Semaine 2 · Spins en plan mural`},{label:`Semaine 3 · Spins en plan roue`},{label:`Semaine 4 · Split time`}]},"poi-weave-ladder":{name:`Progression des weaves au poi`,description:`Du chase the sun au weave à trois temps dans les deux sens, puis le weave à deux temps, plus rapide.`,weeks:[{label:`Semaine 1 · Chase the sun`},{label:`Semaine 2 · Weave à trois temps`},{label:`Semaine 3 · Weave inversé`},{label:`Semaine 4 · Weave à deux temps`}]},"poi-antispin-start":{name:`Débuter l'antispin`,description:`D'abord extensions et isolations, puis antispin avec un poi, et la fleur à quatre pétales avec deux.`,weeks:[{label:`Semaine 1 · Extensions`},{label:`Semaine 2 · Isolation`},{label:`Semaine 3 · Antispin à un poi`},{label:`Semaine 4 · Fleur en antispin`}]}},a={"sf-ambient-70":{name:`Orbite lente`},"sf-world-75":{name:`Pas de marché`},"sf-ambient-80":{name:`Dérive de lanterne`},"sf-world-85":{name:`Roue du désert`},"sf-handdrum-90":{name:`Tambour circulaire`},"sf-funk-95":{name:`Poignets souples`},"sf-handdrum-100":{name:`Mains de feu`},"sf-world-105":{name:`Cloches de rivière`},"sf-funk-110":{name:`Cascade de poche`},"sf-handdrum-115":{name:`Groove de cour`},"sf-electronic-120":{name:`Staff néon`},"sf-funk-125":{name:`Motif rebond`},"sf-electronic-130":{name:`Hoop Pixel`},"sf-handdrum-135":{name:`Djembé coucher de soleil`},"sf-electronic-140":{name:`Traînées LED`},"sf-funk-145":{name:`Cycle de rotation`},"sf-electronic-150":{name:`Flow stroboscopique`},"sf-handdrum-155":{name:`Paumes rapides`},"sf-electronic-160":{name:`Spinner nocturne`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};